/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20151109-9","meetingId":"h27-cm11","date":"2015年11月9日","dateIso":"2015-11-09","committee":"文教委員会","time":"午後 １時００分～午後 ３時３８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)「芳水小学校・城南小学校の改築」","agenda":"はじめに、(1)「芳水小学校・城南小学校の改築」","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"学校校舎の改築ということで、芳水小学校と城南小学校の２校を承りました。坂道があるので、周りに相当な迷惑がかかるかもしれないなというのがちょっと気になったのですが、その点を教えてほしいと求めました。","respondent":"品川庶務課長","answer":"イメージパースで見ますと右下ぐらいの部分になりますか、その部分からもう直接車両を入れるような形を工事期間中はとっていきたいと考えています。基本的には工事車両は通らず、一番北側の部分のみ、車両を通していこうと現在のところは検討しているような状況です。","id":"exchange-001"},{"speaker":"浅野委員","kind":"質問・要望","question":"意見とか要望とかを聞いていただいて、周りの方から反対意見が出ないと思いますけれども、そういうことのないようにしてほしいと求めました。もしそういうものができるのであればやってほしいとは前々から思っていたのですけれども、何かそういうことに関して、教えてほしいと求めました。","respondent":"品川庶務課長","answer":"これも当然改築する際に、掘ってもう一回やり直しをかけていくように考えております。その辺も、この周辺地域も含めまして、総合的にやはり排水対策はこの改築の際に見直していくという考えで、現在のところは進めている状況です。","id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"それとあと、城南小学校のほうなのですが、こちらも道路というか旧東海道ですか、そちらのほうからしか入れない。点々になっているところはお墓なんか尋ねました。","respondent":"品川庶務課長","answer":"そういったところは道路の線引きをして、十分安全を確保していくしかないとは考えております。この期間だけでもこちらから出入りができないかというようなところも現在考えながら、動線のほうは今非常に悩みながら検討しているような状況です。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問","question":"これはどのような工事になるのかという手順とかが多分あると思うので、その概要をもし説明していただけるのであれば、教えてほしいと求めました。どちらに何を建ててとか、奥に校舎を建ててとか、そういうように考えられているものがあれば教えてほしいと求めました。","respondent":"品川庶務課長","answer":"ですので、まずはこの城南小学校のグラウンド側に新校舎を建てていくという段取りになります。今現在のところ、ざっとですけれども、工事の流れという形になります。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"芳水小学校で１つ質問を忘れたのですけれども、子どもたちは校庭で遊ぶのがちょっと難しい、それを一つ教えてほしいと求めました。それとあと、両方ともそうですけれども、とにかく地域の方に理解していだだけるような工事と、あと絶対無事故で進めてほしいと求めました。","respondent":"品川庶務課長","answer":"これにつきましては次ページの資料にありますとおり、ステップ４のところをご覧いただきますと、一番最後に壊していくような形を考えております。それからあと…","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回は芳水小学校と城南小学校なのですが、改築してほしいと願っている学校はあちこちにあると思うのです。どうしてここが、うちはどうなの」という質問が地域では出るので、大もとのところを説明を求めました。","respondent":"品川庶務課長","answer":"簡単にご説明をしますと、やはりこういう危険を考えまして、早急に改築しなければいけないという部分が一つあります。人口が増えていくというような傾向もありますので、やはりそれに準じた形で教室数も対応していこうという理由で、改築に踏み切っております。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"今後の計画というのは決まっていないのか、ちょっと先ほどお伺いしたので、そこが一つ。お子さんたちや保護者、そこの地域をよく知っていたり使っていらっしゃる方々の意見がどの辺で聞かれて、加味されるのかというのを説明を求めました。","respondent":"品川庶務課長","answer":"は１点目、それからその後どうなるかという部分も加味しながら改築は考えていきますので、そのような計画は立ててございません。各地区の町会長とか、その場でご意見等を伺いながら、できることに関しては当然やっていくという考え方で現在のところ進めているような状況です。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"学校が楽しくてもう行きたくなる場所になってほしいので、それをお伺いしたので、一つ答えていただきたいです。これの性格はどのようなことに使っていく部分なのかなというを一つ教えていただきたいのと、あと、ちょっとこの意味がわからないので説明を求めました。","respondent":"品川庶務課長","answer":"バルコニーですけれども、斜面に合わせてバルコニーをセットバックするということですけれども、少しデザイン的なところになるかと考えています。多分１階、２階、３階と少しずらしたような形で建設をしていくというイメージで、この辺は表記してあると考えております。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"できるところはそういうふうにしていくということなのかどうか、その辺がよくわからなかったので、その辺を教えていただきたいのです。専用の部屋を確保してほしいと思っているのですが、この書き方でよくわからないので、どうなっているのか教えてほしいです。","respondent":"品川庶務課長","answer":"ほかに利用できる場所がないかということもありますし、その辺の部分についてはまだまだ検討しているような段階ですので、よろしくお願いします。どちらも単体の小学校ですので、大きさにつきましてはほぼ同じ大きさでつくっていくと考えています。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後になるのですが、地下なのですけれども、これは半地下なのですか。場所的な意味でどのような状況なのか教えてほしいのと、同等の図書エリアというのはスペース的にひとつどうなのかなというところを説明を求めました。","respondent":"品川庶務課長","answer":"図書館のほうが約５００m2で、こちらの多目的室を貸し出すほうが、ざっくりですけれども１００m2という形になってあります。このスペースですと、十分既存の大崎図書館の機能は入るという形で、この広さをつくってあります。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"そして大きさ的には大体ということで、図書館長もいらっしゃるので、ここに大崎図書館と同じような機能が備わるのかどうか。閲覧コーナーとか、あと職員の配置とか、そういった同じ機能が果たされるのかどうか、ちょっとそこの点を説明を求めました。","respondent":"品川庶務課長","answer":"同じ機能が入るかですけれども、機能としては全く同等のものを考えてあります。あくまでも現状の大崎図書館相当のものをここに配置するという考えです。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後に改めて同じ質問で、不十分だからお伺いしているのでお許しほしいと求めましたが、同じ地域のところで同じ機能を果たしてほしい。そこの図書館にないものをよそに求めたりしたときに、同じように求められるかどうかというのがとても重要だし、そこは図書館長か尋ねました。","respondent":"品川庶務課長","answer":"ですので、現在の大崎図書館にある本の機能とか、その機能につきましては十分維持をした形でここに設置していくという考えです。細かい点でいろいろ多少ずれる部分はあると思いますが、概ね同じ機能を移していきたいと考えております。","id":"exchange-012"},{"speaker":"鈴木（博）委員","kind":"質問","question":"僕は１点だけ質問します。工事をするとほこりがいっぱいになって、その辺のフォローとかご説明とかいうのは、どのようにされているのか尋ねました。","respondent":"品川庶務課長、野呂瀬学務課長","answer":"保護者を呼んで全体で細かい説明会をするとか、そのような対応は現在のところはしていない状況です。理由を言いますと、細かい部分で決まっていないということで… その時点で決まっていることですけれども、芳水小学校は来年度から工事に入りますみたいなことでご説明はしています。それによって、逆に言えば、今年と同等ぐらいの希望の人数は入ってきていると把握しています。","id":"exchange-013"},{"speaker":"鈴木（博）委員","kind":"意見","question":"一応その辺の説明は別に保護者を集めて説明とかしなくても、いろいろな広報媒体とかを使っていろいろご説明する努力はお願いしたいと思います。具体的な数字とかというのは、要するに直接数字を把握しているわけではなくて…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"仮設校舎のことで、今少しお話があったので、仮設校舎の機能についてどういうことを考えているか教えてほしいと求めました。品川区も今子どもたちにさまざまな取組みをしている中で、運動の確保というのはどのように考えているか教えてほしいと求めました。","respondent":"品川庶務課長","answer":"それで、教室数は大体２１ぐらい配置をするようなことで考えております。運動の面から言いますと、体育館、それからプール等を残しまして、こういう残っている部分で極力運動については確保していきたいと考えております。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"体育館とかを使ってどういった休み時間等の運動というのを確保していくかというところが知りたかったので、もしあればもう一回お話しいただきたい。防音とか、例えば夏場とか冬場とか、そういった部分での子どもたちの学習環境というところに配慮していただきたいと思って質問しましたので。","respondent":"品川庶務課長","answer":"仮設校舎の部分につきましては、当然防音とか、その他もう児童が使いやすいような形で建設のほうは考えていく予定です。芳水小学校のほうからいろいろ場所の確保だとか、そういうことのご要望があれば、極力協力した形で教育委員会としても進めていきたいと考えています。","id":"exchange-016"},{"speaker":"大倉委員","kind":"意見","question":"運動場所がないということで、体育館であったり、そういった場所に多く子どもたちが集まって休み時間等に遊ぶのだろうと思っているのですが、そういうところでけががないようにとか、その辺の配慮をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"このイメージ図、要は校庭と校舎の場所が入れ替わっているのですけれども、こういう形で設計が進んでいくという形で見ていいのですか。それで幼稚園もここにあるということでしたけれども、幼稚園も一緒に改築されていくということになるんか尋ねました。","respondent":"品川庶務課長","answer":"先ほどいろいろ説明したとおり、やはり校庭のところに仮設校舎を建てるということになりますので、確保するのは難しいと考えています。ですので、これは改築する際には、新しい校舎に幼稚園を入れた形で改築をしていくようなことで、現在のところは考えております。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ学校の要望なども聞きながらということだったので、ぜひそういう機会があれば確保していただきたいなと思います。何か地域からの意見とかがあったのか、それとも何か設計上の効率性なのか、何なのかをちょっとほしいと求めました。","respondent":"品川庶務課長","answer":"それぞれ各業者がいろいろどちらの位置に校舎をつくるだとか、そういうことを出してプロポーザルのほうを進めていくことになっております。梓設計のほうで出した配置案ということで、この案を区としても選定しておりますので、この状況が今パースに落ちているという状況です。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"以前別の機会に質問させていただいたときに、全クラスに遮光、そのあたりについてのカーテンの手配等はどうなっているのかということをお尋ねします。これ、想像するに４クラスだとすると２階のどれかの端になるのかなと思うのですが、その辺の配慮を考えられてやられているのかということがあります。","respondent":"品川庶務課長","answer":"日差し等、その辺につきましては、改築していく際に少し検討事項として頭に入れていきたいと思います。現在この状況でいいかというようなことも一つ検討する事項かとは思いますので、現時点では確かにこの２５教室のうちのどこかを使う予定ですが。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問","question":"それからあと、特に城南小学校のほうは日産プリンスとあとナムコですか、そういうところも含めて基本設計等はされていっているのでしょうか。いろいろほかの委員の方が質問されていましたけれども、そういう点についてもどういった考慮をされていっているのかという点を。","respondent":"品川庶務課長","answer":"この辺の点につきまして、防災課のほうと随時協議しながら進めてまいりたいと考えております。その辺につきましては、選挙管理委員会と話し合いながら進めていくことになるかと考えております。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問","question":"就学人口は、先ほどのバンダイナムコとか日産プリンス、城南小学校のほうなので、そちらの増加をくんで、今、基本設計をされているのでしょうかということです。","respondent":"品川庶務課長","answer":"申しわけございません。城南小学校のほうも就学人口等を考えた形で、既存よりも教室数のほうを増やした形で当然やっていくということで、配置のほうは考えてあります。","id":"exchange-022"},{"speaker":"伊藤副委員長","kind":"確認","question":"一、二点確認と、それから質問します。それからあと、防災備蓄品の置き場所はこれから設計していくのでしょうから、それはどうお考えなのでしょうかということを説明を求めました。","respondent":"品川庶務課長","answer":"そういった実績等も見まして、改築のほうはひとつ参考にしてやはり進めていくべきだと私のほうも思っております。１階に置くのか２階に置くのかというあたりは学校と、それから避難所運営会議とか、そういった部分でも話し合いながら考えていきたいと考えています。","id":"exchange-023"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"確かに庶務課長がおっしゃるように、体感するのではやはり雨の降り方が違うわけですから、これはもう取り返しがつかないことがある。この芳水小学校についてはもう設計が決まってしまっているのでしょうから変えることはできないだろうけれども、学園、いかがか尋ねました。","respondent":"品川庶務課長","answer":"昨今の雨の状況、それから洪水等の状況を見ますと、想定外ということがかなり起きてきているような状況もあります。そういった部分は十分加味しながら、今後の学校改築につきましては考えていきたいと思います。","id":"exchange-024"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"要望だけしますけれども、それから品川区の防災課とも調整をとっていただいていろいろな方策を考えていただいて。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]},{"id":"topic-02","title":"平成２７年度小・中学校移動教室実施結果について","agenda":"平成２７年度小・中学校移動教室実施結果について","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"確認で１点だけ。特別支援学級のところが入ってきてそうなっているのかどうか、この人数の見方だけ、教えてほしいと求めました。","respondent":"野呂瀬学務課長","answer":"引率教員の数につきましては、私どもで実施要綱というのを定めていまして、これはクラス数掛ける１.５プラス校長と養護教員を基本にしております。３クラスだと５人プラス２で７人で行くというのが基本なのですけれども、だめですということはありませんので…","id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"質問","question":"非常につまらない質問かもしれないのですが、区立中学校の移動教室を同じ時期に磐梯と、それから菅平高原とダブって実施されていますけれども、これは振り分けとかは何か、要するに基準とかはあるのか尋ねました。","respondent":"野呂瀬学務課長","answer":"これにつきましては、平成２３年に３.１１がありまして、当初福島県の磐梯高原には平成２４年度は行きませんでした。行くときには実態調査等をしながら進めているわけですけれども、今のところ平成２７年度までは２ルートに分かれて実施していたという経緯があります。","id":"exchange-027"},{"speaker":"鈴木（博）委員","kind":"質問","question":"では、特に学校でどちらかに振り分けするとかという基準みたいなものはないわけか尋ねました。","respondent":"野呂瀬学務課長","answer":"私が申し上げたとおり、だんだん前のとおり磐梯のほうに戻していくという状況がありますので、実態的にこういう基準というのはありません。あくまでも学校の中で判断していただいて、最終的に決めていただくです。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"参加できないお子さんもいらっしゃるかと思うのですが、どのくらいいらっしゃるのか、ちょっとそれを教えていただきたいです。１人当たりの費用がどのくらいかかるのかと、あと保護者負担がどうなっているのかと、そして就学援助の状況も説明を求めました。","respondent":"野呂瀬学務課長","answer":"特別支援学級については７名、小学校については報告されています。ある一定の条件、今言った５,２００円と６,３００円がそれぞれ後ほどほかのものと一緒に保護者の口座に振り込まれるという仕組みになってあります。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"意見","question":"本当に現場の先生方のご苦労がたくさんおありかと思いますけれども、本当に楽しい経験をいっぱいしてほしいと考えていますので、これからもとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"浅野委員","kind":"質問","question":"今、不参加が小・中学校で７名と３名ということですけれども、特別支援学級の生徒の中での欠席ということですね。そして大事なのは行かれなかったということで、その行けなかった児童・生徒に対して何らかのフォローとかはされているのかどうか説明を求めました。","respondent":"野呂瀬学務課長","answer":"２６名の中には、先ほど申し上げた７名の特別支援学級のほうも含めて２６名です。大体率にすると１.２％ぐらいで、ほとんど１名とか２名とか参加されないというのは、急遽キャンセルになったというような数と認識しております。","id":"exchange-031"},{"speaker":"浅野委員","kind":"意見","question":"そして何か１人だけ仲間外れにされたような気持になってしまう。小学校のときに友達が１名だけでしたけれども、１人だけ孤立するということになってしまうとかわいそうですので、これからもとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"２つお尋ねして、１つは、それがもしちょっとわかればです。クラス数掛ける１.５というのは、専任の先生の数で、あと校長先生と養護教員の方の数なのか尋ねました。","respondent":"村尾教育総合支援センター長、野呂瀬学務課長","answer":"ただマイスクール八潮自体が、実はマイスクール八潮単独で、９月３０日から日光のほうにマイスクール八潮としての移動教室をしています。今年度は２９名中１６名の子どもたちが参加をして、できるだけその辺に近づけて… 引率の数ですけれども、基本的には正規の職員というか、いわゆる担任の先生だとか、非常勤の先生は含めていないということで考えております。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"マイスクール八潮のほうは大変すばらしい取組みだと思いますので、ぜひ続けていってほしいと求めました。これはもう要望も含めてなのですが、そういった形で１人そういった要員の方をつけていただければと思うのですが、どうか尋ねました。","respondent":"野呂瀬学務課長","answer":"学校のほうから特別な配慮だけなくて、こういう事情がある方も含めて、ご要望いただければそれなりの加配の措置はとっていけるかなと思っています。これは学校のほうで判断していただいて、学務課に申請していただければ…","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、ふだん不登校だったけれども、移動教室には来たよとか、そういう例が今回あったのかどうか。先ほどの就学援助の認定者で小学校は５,２００円、前もって出していただくようにしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"野呂瀬学務課長","answer":"１学期に行ったお子さんもいれば、例えば６年生であれば学用品費だとかそういうのも含めて、６年生でかかる分についてはこれだけ。必ず学期に１回ずつ支払うということで決めてありますので、１学期中にほかの部分も含めてやってありますので、ご了解いただきたいと思います。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりどうして来られていないのかという働きかけから、達成感とおっしゃっていたので、状況をそのときそのときで工夫していただきたいと思うのです。１学期に１回ずつということでやられているということなのですけれども、ぜひここは前もって出していっていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"}]},{"id":"topic-03","title":"「平成２６年度保護者アンケート」、「平成２６年度児童・生徒アンケート」の結果","agenda":"「平成２６年度保護者アンケート」、「平成２６年度児童・生徒アンケート」の結果","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほどアンケートは児童・生徒には二度目だとおっしゃっていたのですけれども、要は昨年から始まったアンケートだというところ、保護者の方にもそうなのかというところで、保護者のほうは、いつからやっているのかというのとか、基本的なところを教えていただきたいのですが。","respondent":"渋谷指導課長","answer":"保護者アンケートは、学務課でずっとアンケートをとっていた経緯がありまして、実際やっていたのはかなり長くからになります。一旦、３分の１の保護者を対象にしたアンケートというのを何年か前から始めまして、保護者については今年で３回目ということになります。","id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問","question":"自主学習、中学生になっていくと、「あまりしていない」「全くしていない」というのがすごく増えるのですね。これは、区としたら、どのような状況にあると考えているのか、ちょっとお聞きしたいと思います。","respondent":"渋谷指導課長","answer":"まず保護者のかかわり方として、子どもの自主性を尊重するような姿勢が大きく出てくるというのがまず一つ影響しているのかなというところがあります。この部分の数値が上がるように引き続き努力していく必要があろうと考えているものです。","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問","question":"保護者の方のかかわりが中学校になってくると減っていくと、自主性も尊重しつつというところもあるのですけれども、これがいいのか悪いのか。やはり中学生になってくると、勉強よりも楽しいものがあるのかというものは、区としてはどう考えているのかなというのをお聞きしたいのですが。","respondent":"渋谷指導課長","answer":"区としての考えというよりも、そもそも学習に対する一般的な認識としてどうなのかということでのお答えになろうかと思いますが。１つは勉強であったり、委員もおっしゃいましたが、一概にこの数字だけを見て判断はでき兼ねるものであると考えております。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"「自分には良いところがあると思う」という２０ページの設問で、中学生になると、若干ですけれども増えてきていると思うのです。そう思わない子が増えているというのはどうしてなのかなと率直に思うのですけれども、どうなのか尋ねました。","respondent":"渋谷指導課長","answer":"これはまさに子どもの発達段階に応じたようなものだと思っています。まさに人生そのものを迷う、葛藤する、そういった時期のものが数値として表れているのではないかと思うところです。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こういったアンケートで教育課程に活かしていくとおっしゃっていたのですけれども、ぜひそういう中学生の思春期のいろいろな思いがある状況を踏まえていただいた自由な教育課程をつくってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問","question":"設問２４だと「学校を選択する際、最も重視したこと」とあって、要するに希望申請している場合の選択の理由みたいなのはとっていないですか。要するに指定校以外を希望した方の中でどのような情報、どのような理由で指定校以外を希望したかというのはわからないか尋ねました。","respondent":"渋谷指導課長","answer":"委員ご指摘のとおり、地元の学校を選択するのも選択と考えておりますので、学校選択制を利用した子どもを抽出した形でのアンケートはとってございません。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"どうして指定校以外を選択したかというのは、指定校もそうだし、ぜひそれがわかるような仕組みをお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この読書冊数というのは、具体的に言うと例えばどういう本なのでしょうか。今の小学生、中学生は本を読まないんだなということになってしまうのだけれども、そういう素直な感想でよろしいのか尋ねました。","respondent":"渋谷指導課長","answer":"これは子どもが判断して答えているので、なかなか難しいところではあるのですけれども、一般に小学校低学年は、一部絵本のようなものも含みます。３年生でも非常に文字数の少ない絵中心のものも１冊とカウントしていますので、委員ご指摘のとおりということです。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"家庭に求めること、地域に求めること、それを少しずつ整理して出していただきたいと思うのが一番。はっきり言ってしまったら語弊があるでしょうから、ちょっと勉強をあまりしたくないという子どもが増えていっているのではないか。","respondent":"渋谷指導課長","answer":"この後また今後１０年先、保護者アンケートはこの後ずっと継続してとっていって、今をベースにしてどのように変化していったのか。学力については、平成１５年から学力定着度調査をずっと品川区独自でとってまいりました。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ活用していただきたいという意味では、これを実際に書いた児童・生徒の方々と、あと保護者の皆さんにもそれなりの返し方が必要ですよね。より子どもたちのことを真剣に話し合う場をつくっていただきたい、地域にも返してほしいと求めましたので、その辺はいかがか尋ねました。","respondent":"渋谷指導課長","answer":"自分の学校の課題を洗い出して、次年度の教育課程の編成に活かしていただくという手続をとるために、毎年この時期にはご提供しています。では自分の学校はどのようにしていくのかということを考えていただくというのが、しっかりと活用してまいりたいと思っています。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１３ページ、実際的に選択してどうだったのかというあたりもぜひつかんでいただきたいと思うのですが、やはりそういうマイナス面もありますよね。そういった意味で、実施してみて実際にどうだったのかというところもぜひつかんでいただきたいと思うのですけれども、いかがか尋ねました。","respondent":"渋谷指導課長","answer":"選択制をとった子どもの学校の満足度はどうなのか等、詳細な分析ができますので、そういったこともこの後研究してまいりたいと思っています。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"意見","question":"４・３・２を理解していただいて、それについてはどのようにお考えなのかということと、そのあたりを。先ほどちょっと聞き忘れたとの意見を述べました。","respondent":"渋谷指導課長","answer":"品川区独自に作成している小中一貫教育要領に基づく考え方ですので、平成３０年度、平成３１年度に学習指導要領の改訂があります。この４・３・２のまとまりをどのように考えていくのかということについては、改めて現場の先生たちとも議論をしていきたいと思っているところです。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は実際に具体的にどう変化しているのか、そういった具体例をきちんと伝えていく必要があるのではないかと思っているのです。子どもたちにどう変化が起こっているのかというあたりをわかりやすくお伝えしていただきたいと思うのですが、いかがか尋ねました。","respondent":"渋谷指導課長","answer":"もう、そのわかりやすくご説明するというところに尽きるのだろうなと思います。現行の学習指導要領で選択教科そのものの考え方がなくなりましたので、今、しっかりとその辺を改良していきたいと思っているところです。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問","question":"やはりその辺の移行がスムーズにというのがかなり強調されたのですけれども、その辺はどうなのですか。６年生から７年生については、今どのように考えられているのか尋ねました。","respondent":"渋谷指導課長","answer":"不登校についても、６年生から中学校１年生に進む段階で大きく増えているというのは、このことについて否定されるというところではないかと思います。滑らかな接続をという考え方だったり取組みについては非常に高く評価されているところではないかなと思っているところです。","id":"exchange-050"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"そのようなことがもし、後からでも結構ですから載せていただくほうが、より内容が具体的になるのでないでしょうかということが一つ。３０％の方は満足していないわけだから、こういうところは基本的に短期間にできるのではないでしょうかという思いがあるので、いかがか尋ねました。","respondent":"渋谷指導課長","answer":"それから、まず１点目の短期に対応すべきことについては、翌年のアンケートの結果でまたしっかりと検証していきたいと思います。このスマートフォンの対応についてさまざまな取組みを考えて、そういった取組みによって、具体的な施策の改善に役立ててまいりたいと考えています。","id":"exchange-051"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"それからいじめの言葉というのは、もうご存じと思いますが、それはしっかりと対処していっていただきたいことをお願いします。あるいは名目なのかもしれないけれども、これは長期にわたって取り組んでいくべきだと思いますが、いかがか尋ねました。","respondent":"渋谷指導課長","answer":"諦めずに粘り強くしっかりと、これはじっくり取り組んでいきたいと考えています。品川の教育が目指すべき児童・生徒像をどう考えるのかということにも、こういったアンケートを十分に活用して、しっかりと取り組めばと考えています。","id":"exchange-052"},{"speaker":"伊藤副委員長","kind":"質問","question":"だから、やはりその伸びしろといったらいいのか、そのことをやはり現場ではしっかりと見据えて対処してください。なかなか難しいとは思いますけれども、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"}]},{"id":"topic-04","title":"平成２７年特別区および東京都人事委員会勧告の概要について","agenda":"平成２７年特別区および東京都人事委員会勧告の概要について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"例えば係員の１級２９号給、２２歳というところの方の給料月額のところの差がないのですが、若い方のところが薄いということなのですか。人事委員会の意見のところで、４ページのところにメンタルヘルスの推進というのが書かれているのですけれども、その辺を説明を求めました。","respondent":"渋谷指導課長","answer":"１点目のところはちょっと調べる時間をいただければと思います。２点目のパワー・ハラスメントについては、１２月には体制を整備して、皆さんにご周知をしたいというところで準備しています。","id":"exchange-054"}]},{"id":"topic-05","title":"認可保育園等の新規開設について","agenda":"認可保育園等の新規開設について","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"なかなか足りないという地域ですので、やはり足りないからという声が多かったからここになったのかとか、ちょっとそういった経緯を伺いたいです。これのまた次の計画というのはもう進んでいる状況なのか、ちょっとその辺を伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"子ども・子育て支援事業計画の中で、今後の平成３１年度までの計画を練っておりますので、その中でまた検討しています。事業者からの提案も随時受けて検討を進めているところです。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問","question":"これで終わりでしょうかというのもあれですけれども、来年４月に向けての開設計画というのは、まだあるかもしれないという状況でしょうか。あるのか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"今、１件協議を進めているところはありますが、こちらは東京都との協議がまだ済んでおりませんので、報告はできない状況です。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、先ほど来年４月に開設するそれぞれの全体数を教えていただいたのですけれども、来年４月に開設予定の認可保育園、小規模保育事業、認証保育所、保育施設というものの来年４月開設の数を改めて伺いたいのですが。","respondent":"今井待機児童対策担当課長","answer":"１園が区立の広町の大規模保育施設、それから、私立保育園のほうが前回報告した５園プラス今回のウィズブック武蔵小山で１園、私立が６園です。今回報告いたしましたこちらの東大井かがやき保育園が１園、来年４月に向けまして…","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、この認可保育園のほうですけれども、武蔵小山の今回できるところはやはりビルの中ということで園庭はない状況です。このウィズブック保育園武蔵小山ですけれども、ここが代替公園として、屋外遊戯場として通うとしたらどこになるのかちょっと伺いたいのですけれども。","respondent":"今井待機児童対策担当課長","answer":"こちらについても、今、計画中ですので、ほかの５園と同様にまだ公表してもいません。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これからこの工事というのはどのくらい工期がかかって、開設に向かうのかなというのを１点お聞きしたいです。ちょっとこの辺の中身を教えてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"認証保育所につきましては、私どものほうから国と品川区を合わせまして、事業者の負担は１６分の１という負担になっております。１人当たり開設の補助金という形で、１人頭の定員数で開設の補助金を出しまして、補助をしている形になっております。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ次々と必要な部分の保育園をつくっていただきたいという願いが届いているのですが、先ほどの石田ちひろ委員の質問の中で、１つですか。ぜひ４月の待機児を出さないように頑張っていただきたいというところで、ちょっとその辺を聞かせてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"今年度から新制度になりまして、東京都の児童福祉審議会で計画承認をとらなければなりませんので、それが終わってから工事の着工、建築計画の承認になりますので、今現時点では認可保育園については今後も来年４月の開設が現時点では難しいと考えています。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"認可保育園以外だったら可能なのでしょうか。受け皿が足りないので、何とか受け皿をつくっていただきたいのですが、その辺の可能性はいかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"申しわけありません。こちらのほうもまだ協議が整っておりませんので、今後また、次回の委員会等で報告できればと考えています。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"計画承認というのは、認可保育園も小規模保育事業のところも一緒ということですか。ちょっとその辺の流れがよくわからないので、建設に至るまでの手続のところをもうちょっと詳しく説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"ここの部分につきましては、平成２８年、来年４月の部分につきましては、工期の問題等がありますので、現時点では来年４月は難しいと考えております。それぞれ進み方は違います。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当に４月待機児ゼロというのをもうずっと言い続けているわけですけれども、さまざまな可能性を追究して、本当に受け皿をつくっていただきたい。もうこの努力は本当に続けてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"浅野委員","kind":"意見","question":"大丈夫だとは思いますけれども、ちょっと環境がどうかなというのがふと頭をよぎったので、問題なければいいなと思います。結構飲み屋が、それで差しつかえなければ、ちょっと私が間違ているかもしれませんけれどもちょっとそこら辺のところが気になりましたとの意見を述べました。","respondent":"今井待機児童対策担当課長","answer":"ただ、横町に入ると、確かに委員ご指摘のとおり、少し込み合ったところがあります。広い道路のほうに面しているほうの入り口は外になります。","id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"質問","question":"その中で、勝島の公務員宿舎の中に保育施設をつくるというのがあったと思うのですが、それの進捗状況というのはいかがなものでしょうか。もし以前報告があったのならばあれですが、説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"こちらは８月２４日に、認可保育園の５つのうちの一つとして、株式会社ポピンズが面積４５８m2で定員６０人で開設するという旨を報告しています。進捗管理等も私どもも気を配ってやっておりますけれども…","id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/184577?Template=document&Id=4868#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":48678,"voices":161}},{"id":"h27-20151109-5","meetingId":"h27-cm11","date":"2015年11月9日","dateIso":"2015-11-09","committee":"総務委員会","time":"午後 １時００分～午後 ４時１９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件整理しています。","topics":[{"id":"topic-01","title":"品川区総合戦略の策定","agenda":"品川区総合戦略の策定","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この４つを掲げておりますけれども、それぞれどうしてそこに問題意識を持ったのか、ちょっと概要的に特徴を伺いたいと思います。こういうものに対する品川区としての総括、現状の課題とか問題をどう捉えているのか、そこもあわせて伺いたいと思います。","respondent":"柏原企画調整課長","answer":"国の目標と全く合っていなくてはいけないといったものではありませんので、区としての認識をしている部分について戦略を立てたといったところです。実施計画がありますので、その中からこれに合致する部分を組み合わせたり、新しいものを出したりということで掲げたところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"本当にどういう状況になっているかというのは随分不確定要素がある中で、品川区の基本目標４つに照らして、そこを改めて伺いたいと思います。超過ですから、転入超過を問題と捉えているのか、その原因をどう捉えているのか、そこを伺いたいのが１つです。","respondent":"柏原企画調整課長","answer":"継続していくというところがありますので、今の状態が保たれていることを考えると、全体を見ながら施策というのは考えなくてはいけないだろう。実施計画等々でお示ししているように、その辺を課題にしながら現在も進めておりますし…","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"いわゆる平成４０年前半まではほぼ横ばいなのですけれども、この横ばいを維持したいという考え方なのか、そこを１点伺いたいと思います。やはり原因がはっきりしないと必要な対策につながってこないと私は思いますが、その点お考えを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"基本的には今の状態で、高位推計の部分での人口構成といったところを一定程度見ながら進めていくというのが１つの考え方だろうと考えています。これは、これで５年間コンクリートというところではありませんので、見直しをしながらというところだと考えております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点今のお話で、お話の中でそう思ったのですが、そういうことでよろしいのでしょうか。それはなぜかということで、さらに増設を進めていくべきだと私は思うのですけれども、その点も伺いたいと思います。","respondent":"柏原企画調整課長","answer":"ただ、出生数を伸ばしていくというような考え方を持ったときに、推移というのは一定程度見込む必要があるのではないかといったところです。この戦略というのは総合実施計画、実施計画のほうで計画的に行っていくといったところで、こちらには載せていないというものです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ数字を教えていただきたいのと、待機児ゼロの年度を伺いましたが、ご説明ほしいと求めました。再度総務委員会にぜひご報告をいただいて、質疑の機会を確保してほしいと求めましたけれども、今後のスケジュールを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"施設の総合管理計画をつくっていくというところで、これを基本といいますか、ベースになるような計画になっているという考えです。それから今後の予定ですけれども、次の策定委員会が１２月の終わりになりますので、また総務委員会のほうにもご報告させていただきたいと思います。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"集まっているからその近隣地域に住まいを求めて人も集まってくると。でもやっぱり統計上、将来を見越したらこういうふうな数値、予測を立てなければいけないのか尋ねました。","respondent":"柏原企画調整課長","answer":"１００％お答えできるかは自信がないですが、今回のこの総合戦略を立てるに当たって、ポイントになるといったところです。その１つが、例えば出生率なども、先ほどもお話があったような形でどう上げていくかということを考えていかなければならない。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"ちょっと不思議な気がしたので、責めているわけではないのですが、一応意見だけ言わせてくださいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"向上したとか、こういうメリットがあったとか、こう変わったとかというものはあるのでしょうか。ちょっとまず先に、１点目について説明を求めました。","respondent":"柏原企画調整課長","answer":"計画だけではなくて事業を実施する中でも、これはちょっと今までより進んだというところの効果はあるのだろうと考えています。実施計画が基本でありますので、そういう形ですが、先ほど言ったようなところが効果としてもいいところではないかなと思ってあります。","id":"exchange-008"},{"speaker":"あべ委員","kind":"提案","question":"５年で改定するのだというような話もありますけれども、これはもうご提案ですけれども、その辺についてお伺いしたいと思います。これは目標を掲げるということは、その達成のために区が努力をするということで受けとめてよろしいのか尋ねました。","respondent":"柏原企画調整課長","answer":"自治体によってはそういう総合実施計画をつくることがこの戦略だと言っているところもありますので、それは全く今までつくっていなかったところです。今後その実施計画の見直しの時期、内容については少し検討が必要かと思ってありますが、考え方としてはそういうことです。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"区がすべきことは何なのか、今後もう少し精査していただいて、実際の施策に落とし込んでいただきたいなと思います。区としてはどうお考えか、お伺いします。","respondent":"柏原企画調整課長","answer":"これは１つの政策をするに当たって指標となるものは幾つかあると。もう少し練らなくてはいけないだろうとは思ってありますので、引き続きこの辺のところは検討しながらというところで考えていきたいと思ってあります。","id":"exchange-010"},{"speaker":"あべ委員","kind":"意見","question":"２６ページの観光については、ホームページのアクセス数ですとか、幾つかの指標があるかなと思います。そういった、一つ一つあると思いますけれども、今後練り上げてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"１ページの国と品川区との関わりは書いてあるのですけれども、そこはどういうふうに仕分けというか、整合を図るという中でどういうふうな調整をしていくのか説明を求めました。","respondent":"柏原企画調整課長","answer":"先ほどは総合戦略をご説明するときに国との関係を特にお話をしたわけですけれども。考え方は議論もしながら、入れ込みをどういう形で行くかは別にしまして、都の戦略とは整合を図っていこうと考えております。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"質問としてはごく単純に、パブリックコメントの実施についてありますけれども、どの程度のもので、閲覧場所という、これらのところにどの程度の資料が示されるのか、まずお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"そこに考え方をお示しして、こちらのほうも合わせて置かせていただきますので、両方ご覧をいただける形にする予定です。〔「ほかの閲覧場所」と呼ぶ者あり〕ほかの資料コーナー、地域センター等にもこちらは閲覧できるような状態でご用意する予定です。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"例えばもう少し具体的にどういうことを考えているとか、そういうことがないと、なかなかパブリックコメントで意見も言いにくいかなと。それを具体的に実施するに当たっては税金がもとになるわけですから、はっきり言って税の配分をどうするかということにもつながってきますので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１１ページの、先ほどの質疑の確認なのですけれども、これを国が今回は定めなさいということだというご説明でした。は指標の例示みたいなものは来ているのか、例えばすまいるスクールは品川区でしかやっていないわけですから、そこについての説明をお願いします。","respondent":"柏原企画調整課長","answer":"そのパフォーマンス、その動きを満たしているところもありますので、正直そこを国がガチガチにこうしなさいと言っているわけではありません。計画期間の中で変わっていく可能性もあるといった意味も含めて、今後内容や数値が変わる可能性があるといったところです。","id":"exchange-015"}]},{"id":"topic-02","title":"特別区全国連携プロジェクトに関わる連携事業の実施","agenda":"特別区全国連携プロジェクトに関わる連携事業の実施","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"それで幾つか教えていただきたいのですが、まず一連の事業にかかるコストというものはどのくらいで、それを誰が負担をするのかということ。それから最後の行で、坂井市の広報より取材依頼リリースを行うとあるのですけれども、これは品川区としてはリリースはしないのか尋ねました。","respondent":"柏原企画調整課長","answer":"確定ではないのですが、およそ７０万円、８０万円ぐらいのコストになるのではないかというふうには聞いてあります。品川区のほうも広報ということで、本日この委員会報告の後、プレスのほうにはリリースしていきたいと思ってあります。","id":"exchange-016"},{"speaker":"あべ委員","kind":"意見","question":"新聞、今ネット上での地域ニュースを運営しているところもありますし、あるいは品川を中心に情報提供しているタウン誌などもありますよね。そういったことも含めて、できるだけ広報にご努力してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"平成３１年度までに１０事業ぐらいということでＫＰＩ、計算すれば５年後ですから、１年に２自治体ぐらいずつというお考えなのかどうか。１つこれは要望なのですけれども、ぜひまたああいった都市とも交流事業を進めてほしいと求めましたが、以上まとめてお願いします。","respondent":"柏原企画調整課長","answer":"どういった連携ができていくのかと今後お話をしながらというところになりますので、先方との連携をとりながらというところであろうかと思います。その都市についてもそういった形で、規模がどの程度、そういうものをいろいろ見ながら進めていくものであろうと思います。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"今のご質問とちょっとかぶるところがあるのですけれども、戦略というか、もくろみがお有りでのオファーなのか。せっかくこういうことを１つやるわけですから、それは相手があることですからうまくいくかどうかはまた別として、その辺を伺いたいと思います。","respondent":"柏原企画調整課長","answer":"持っている、展示しているものであるとか、いろいろ有している課題等々もあるというところです。どういう連携を今後築いていくのかというのは、今後先方の自治体とお話をしながら、事業をしながらというところになってこようかと思います。","id":"exchange-019"}]},{"id":"topic-03","title":"品川区シティプロモーション","agenda":"品川区シティプロモーション","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"アトレとタイアップということであるのですけれども、それはお互いに出し合う形なのか、品川区として全てこちら持ちで進めているのでしょうか。そのお金の配分などについて説明を求めました。","respondent":"中元広報広聴課長","answer":"ただ、ちょっと店舗によってはやはりそれが難しい店舗もありまして、場合によってはお金を払うというところもあります。やはりできる店舗、できない店舗が出てまいりますので、内訳のところはまだ私のほう確認ができていない状態です。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"ＣＳＲでやるかどうかで大分内訳が変わってくるのかなと思いますけれども、１,５００万円のほぼ全てがこのロゴマークをつくるところから、どんな感じになっているものなのか尋ねました。","respondent":"中元広報広聴課長","answer":"ＪＲ大井町とかが週２万８,０００円かかりますので、それが２枚ということで掲載をしてまいりますので、２週間で１１万２,０００円です。車内吊り広告も別に料金がございまして、すみません、ちょっとそれは手元にないのですけれども。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"それとも広告代理店の調整料が実はメインのところであるとか、何かどういう感じなのでしょうか。いずれは明らかになるのか尋ねました。","respondent":"中元広報広聴課長","answer":"それに応じた要素を入れたポスターを４種類ということで、全部で５種類のポスターを、屋外で撮影をしたりということでやっています。区の職員のお子さんであるとか、あと商店街の方にご協力をいただいているもので調整をさせていただいて、なるべく節約をしています。","id":"exchange-022"}]},{"id":"topic-04","title":"マイナンバー法施行に関わる個人番号の指定等","agenda":"マイナンバー法施行に関わる個人番号の指定等","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"既に自治体によっては通知カードの簡易書留の郵送が始まっているように伺っているのですけれども、遅いというか、そこを伺いたいと思います。ミスが相次いでいると伺っていますけれども、一歩後から始まるだけに、そこについても伺いたいと思います。","respondent":"仁平情報推進課長","answer":"持ち込みが終わっておりますので、品川郵便局では１１月１０日頃から順次配達開始となります。そういう報道を踏まえまして、何分郵便事情ですので、品川区でどうできるかというところはちょっとお答えできかねるです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"そのもとになるものですから、郵便局に何を求めるのかという角度もあるかもしれませんけれども、そこは改めて伺いたいと思います。担当者も頭を抱えているというお話を伺いますけれども、届かないというか、そこを伺いたいと思います。","respondent":"仁平情報推進課長","answer":"こちらの行政側のほうからマイナンバーについて個人情報を問い合わせる予定はないというような、そういうＱ＆Ａ関係も周知しています。先ほどもちょっとお話し申し上げましたけれども、多くて１万件ぐらいが戻ってくるのではないかというように…","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこがどういう体制になっているのか改めて伺いたいのと、そういう意味での１万件ということなのでしょうか、そこをちょっと確認したいと思います。ここに表示があること自体わからなければわからないわけですし、そういう対応がどういうふうになっているのか、その点も伺いたいと思います。","respondent":"仁平情報推進課長","answer":"特に窓口要員、それを担当する職員向けに、改めてこちらのほうの事務上の取扱い上の研修を実施していくという予定になっております。情報推進課としましてはちょっとお答えしかねる部分がありますので、各所管のほうへ改めて対応のほうをお問い合わせいただければと思います。","id":"exchange-025"},{"speaker":"中塚委員","kind":"意見","question":"多様な国民、住民の実情を無視して一方的に番号を振り分けて、こういう乱暴な推進はやっぱりやめるべきだと改めて指摘します。個人のプライバシーを危険にさらす、不利益をもたらすマイナンバーは凍結、中止すべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問・要望","question":"不利益になるということがないようにしていただきたいのですけれども、特に障害関係のところとは、何か話し合いの場を持っていらっしゃるのか。今までも何かはあったと思うのですけれども、どんな形で対応されているのか尋ねました。","respondent":"仁平情報推進課長","answer":"それぞれ対応の細かい点につきましては、個別に各所管のほうで工夫しながら対応しておりますので、その辺は課長間のほうで連絡をとっていきたいと思います。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"連携というより、その部分はお任せしているという印象だったのですけれども、そういうニュアンスでしょうか。それと様々な理由によって受け取っていらっしゃらない方、あるいはどう言ったらいいんですかね、戻ってきて届かないと言ったらいいんですかね。","respondent":"仁平情報推進課長、中山企画部長","answer":"受け取れなかった方に対しては、それで通知カードがご本人に届いているかどうかとか、その辺を履歴管理するというふうな形になっております。ただ、細かい事務手順のほうは戸籍住民課のほうの関係になってしまいますので… 都市部と地方によってどうなのか、先行自治体の情報等もありますので、どれぐらいになるかというのは見守りたいと思います。個別にもう１回その方にお知らせするわけですけれども、その反応の仕方だとか…","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"ちょっと変な質問かもしれないですけれども、番号がないわけですよね、そうするとその後の社会保障のこととか、それがどうなってしまうのでしょうか。うまく受け取れない人にもう１回はがきとは、どの辺まで徹底するのかということですね、それについても伺いたいと思います。","respondent":"仁平情報推進課長","answer":"区のほうで管理していますので、通知カードが届かなかったからということで、行政上不利益を被ることはないと考えていただいて結構だと思います。ただ、何分にも細かい点につきましては、ちょっと私のほうではお答えをしかねるところです。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり今のお答えを伺って、やはり一番厳しい状況にある方たちというのはなかなか、そもそもいろいろな制度に乗れていない。その辺はちゃんと、もう既にそこに瑕疵が出てきていると認識していただいたほうが、今後進めるに当たってもいいのではないかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"中塚委員","kind":"確認","question":"はおじいちゃん、おばあちゃん、そういうときに書留でどうやって確認して相手に渡すのか。だからミスが起きているのかなと想像してしまうのですけれども、ちょっとそこを改めてご説明いただけますか尋ねました。","respondent":"仁平情報推進課長","answer":"それと郵便のほうなのですけれども、確かにこれだけの量を配送するというのは、過去にはなかったかなと考えています。郵便局持ち込みから大体２０日程度で全世帯のほうへ一巡、ご自宅も土日、それらを活用して受け取っていただくということになるかと考えています。","id":"exchange-031"},{"speaker":"中塚委員","kind":"確認","question":"そこをどういうふうに本人を書留で確認をするのか、なりすましをどう防いでいくのか。そこを改めて伺いたいと思います。","respondent":"中山企画部長","answer":"これは郵便局でどう対応するかというのは、何らかの次の郵便局の扱いの中での配慮というのは、一定の対応はあるのではないかと思います。それから戸籍住民課長と連携して、目配りをするということをお願いするということをやっておりますので…","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"ごめんなさい、もう１点だけ。まだそういうことはやるかどうかも含めて決めていないというようなお返事だったと思うのですけれども、今考えていらっしゃるのか伺いたいと思います。","respondent":"中山企画部長","answer":"いわゆる区の活用方針等々、基本的なやるべきものというのは、一定考えを持って方針をとっているところです。今の配送の状況だとか、また今後のシステムの進捗状況等を見ながら、どういうシステムにするかについてはまた考えていきたいと思ってあります。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"最終的にそういうことが検討された結果、何か示される予定なのでしょうか。それが質問と、ぜひそういうものはつくるべきじゃないかなという意見と、両方なのですが。","respondent":"中山企画部長","answer":"一定の方針というのは今後定めてまいりたいと考えております。〔「示されるのか」と呼ぶ者あり〕 その辺の策定の方法というか、やり方によって示し方、また周知というのは、それによって決まってくるかと思います。どういう形でこれをきちんと周知し、また進めていくかについての考えは…","id":"exchange-034"}]},{"id":"topic-05","title":"国民保護共同図上訓練の実施","agenda":"国民保護共同図上訓練の実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この情報漏れを防ぐために直前になったというのはどういう意味合いなのか、ちょっとそこを伺いたいと思います。２３区での自治体としては３回目だけれども、品川区としては今回が初めてということなのか尋ねました。","respondent":"江部危機管理室長","answer":"４月ですか、４月に各区市町村の国民保護担当課長あてに意向調査がございまして、ぜひ取り組むべきであるという判断のもと手を挙げました。品川区は９０名、それから外部の事業者の方が３０名、それから東京都や国の関係者が５０名、全体で１７０名と聞いております。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"品川区の９０人というのは、いわゆる区の職員のみなのですか。それと外部の３０人というのは、いわゆるバスとか、電車とか、そういうことなのか尋ねました。","respondent":"江部危機管理室長","answer":"お話しできる範囲で説明をさせていただきたいと思います。内容的には東京都が決めてきているものでございまして、この化学テロ、爆発物のテロというのは東京都が決めているものです。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"全部の自治体というわけでもないですから、ちょっと今回初めてということで、区の動機について改めて伺いたいと思います。復旧復興だったり、この訓練を通じて何を区が得たいというのでしょうか、そこがよくわからないのでご説明ほしいと求めました。","respondent":"江部危機管理室長","answer":"それから、先ほどのお手元の資料の訓練内容を見ていただきたいのですが、実際にテロが発生したときの被害情報の収集とか初動対応をどうするのか。それから住民避難に関する情報伝達への対応をどうするかという広報的部分。","id":"exchange-037"},{"speaker":"中塚委員","kind":"確認","question":"危機管理を強めたいというのは、何か具体的に脅威が高まっているという認識なのか、それは何かというのを最後に伺いたいと思います。安保法制の関係で国民保護法に基づく訓練で、何か変更があるのか、そこを確認したいと思います。","respondent":"江部危機管理室長","answer":"東京都のほうでも考え方として持っておりますのは、首都東京では求められていることであるということから、行うものです。それから安保法制の改正との絡み、自衛隊の内容はということについてですが、その辺は我々としては全く関係ないものだと、変更はないと捉えています。","id":"exchange-038"},{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれども、東京都が主催者となって今回は品川区と連携し、また国やその他機関と連携する訓練というふうに考えていいのでしょうか。とすると、また他の道府県も同様の訓練を同じようにやっているということなのか尋ねました。","respondent":"江部危機管理室長","answer":"やはり区市町村、発災現場である区市町村を巻き込んでということの流れが平成２１年から始まり、今回で３例目となったと認識をしております。基本的には都が中心となって、その年その年で区を巻き込んでということだと思います。","id":"exchange-039"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、いろいろな区でやりながら、その関係の機材などもそれぞれの区に充実させていくようなものなのであるのか。まあ図上ですからそんなに大がかりなものは必要ないとは思うのですけれども、何かその辺どうなっているのか、ちょっとイメージで伺っているのですが。","respondent":"江部危機管理室長","answer":"それを借りてお返しするというふうに、今回は予定されております。防災課のほうでもビブス、大震災のときに持っていますので、それをどのように使うか、この訓練を踏まえまして考えていきたいと思います。","id":"exchange-040"},{"speaker":"あべ委員","kind":"質問","question":"図上訓練があるということは、実地訓練というのもまた別の自治体か何かでなさっているのか、あるいは今後そういった形にもなっていくのか。図上訓練をやった区は次は実地訓練みたいな流れがあるのかどうか、ご存じでしたら説明を求めました。","respondent":"江部危機管理室長","answer":"平成１８年度スタートしまして、実働訓練を３年ぐらい続けまして図上、ちょっとずれていますけれども。近いところでは日比谷公園で実働訓練を平成２４年度にやったようには聞いております。","id":"exchange-041"},{"speaker":"あべ委員","kind":"質問","question":"つまり、今回図上訓練を行うことによって、あるいはそれと関係なくかもしれないのですけれども、実働訓練というのですか、実働訓練というのがまた今後品川区でも行われる可能性もあるということか尋ねました。","respondent":"江部危機管理室長","answer":"そこに、要は平成７年の地下鉄サリン事件のような、道路が人を寝かせる場所になるという空間をつくらなくてはいけないのです。現実的には公園とか、広い場所がないとできないということで、なかなか難しいのではないかと今は想像しています。","id":"exchange-042"},{"speaker":"須貝委員","kind":"提案","question":"これはもう提案というか、意見なのですが、自然災害用の映像、ビデオ等はあるのですね。意見だけですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"}]},{"id":"topic-06","title":"平成２７年特別区人事委員会勧告の概要","agenda":"平成２７年特別区人事委員会勧告の概要","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"ちょっと言葉を幾つか教えていただきたいのですけれども、地域手当等にということでしたが、諸手当の中に地域手当は入らないのでしょうか。諸手当の中にはどんな手当があって、諸手当に入らない手当というのはどんなものがあるのか伺いたいと思います。","respondent":"米田人事課長","answer":"今回の場合でいいますと、諸手当は扶養手当の改正分のみです。その分、いわゆる地域手当が増えるということで、今回についてはこのはね返りというのも地域手当のみということになってあります。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"今回のみというだけではなくて、通常の２３区の公務員給与の中で、手当というのはかなりたくさん種類があるのですよね。そうすると、どんな形になっているのか尋ねました。","respondent":"米田人事課長","answer":"いわゆる地域手当のように、本給の一定率を掛け合わせたというものだけがはね返りということになります。例えば扶養手当も地域手当の算入に入る場合がありますので、それ以外の手当は全て諸手当ということでお考えいただければと思います。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問","question":"そういったものが、これはモデルケースなどでは全て含んだ上で年間給与という枠で出てきていると解釈していいのでしょうか。その結果、公民較差１,４１３円という形で、それを解消していくと、そういう解釈でよろしいか尋ねました。","respondent":"米田人事課長","answer":"全て諸々を含んだ給与月額同士の比較で較差が１,４１３円になったということでご認識いただければと思います。","id":"exchange-046"},{"speaker":"須貝委員","kind":"意見","question":"大手が多いのでしょう、きっと東京都には。その辺、人事委員会から来たのですけれども、課長どのように思われますかとの意見を述べました。","respondent":"米田人事課長","answer":"国や東京都の企業規模でいうと５０人以上、かつ事業所規模５０人以上というところを対象にして実施しているものです。その辺で、ある種必要な人材の確保であったり、育成にもつなげる、いわゆる適正な給与というものが担保できているのではないかと考えています。","id":"exchange-047"},{"speaker":"須貝委員","kind":"意見","question":"ですけれども、給与というのは平均給与、何百万、数百万、１,０００万近いというところもあります。本来、やはり社会構造が変わってきたから、何かやり方も算出の仕方も変えなければいけないのではないかなという意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"その結果５件がわかったということですが、全体の数とどういう調査をしたのか、そこを伺いたいと思います。民間のマンションや、旭化成建材がどういうふうに話しているのか、そこも伺いたいと思います。","respondent":"小林施設整備課長","answer":"過去１０年間に遡って調査をして、今言った５件のほかに何件あったかということですが、２３件程度ありました。杭を使っている物件です。","id":"exchange-049"},{"speaker":"中塚委員","kind":"確認","question":"要するに区が独自に調査をして、旭化成建材に確認をとったという関係にあるのか、そこを伺いたいと思います。やはり自治体ですから、住民の生命・財産、また区有施設も含めて守る必要があるわけで今後の方向についても伺いたいと思います。","respondent":"小林施設整備課長","answer":"それに基づいてデータのほうを確認して、現場のほうも調査に行ってまいりました。今の段階では国、対応するものは対応していかざるを得ないのかなという形で、今は都と国のほうの動向を注視しております。","id":"exchange-050"},{"speaker":"須貝委員","kind":"確認","question":"今お聞きしましたけれども、最初建築確認、品川区の建築課でかなりやっていまして、今は民間のほうに建築確認を委ねるようになりました。それとも、もう民間は民間ですから、一部区でやった建築確認もあるのですけれども、それに関しては関知しないという方向で動くのか尋ねました。","respondent":"小林施設整備課長","answer":"建設業法だとかで１０年というのが決まっていますので、そこら辺以上のものについては非常に追跡が難しいのではないかなというのを考えています。ちょっとほかのところの部署なもので、多分そういうふうな動きで動いていると思ってあります。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"これがどういうものなのか教えていただきたいのと、それからほかにも採用されていた部分は平屋建て・２～３階建ての増築部分・既存建物外部バルコニーと耐震補強部分でしたということで、説明を求めました。","respondent":"小林施設整備課長","answer":"先ほども言いましたけれども、鋼管杭も含めて現場調査をして傾きがないということが１点。支持層まで達しているということを確認とったので、そういうものを全て考えて、異常がないものと考えております。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問","question":"不具合について、何て言うのでしょうねで終わらせないで、１つあるのをしっかりその背景を調べていただくということをお願いしたいのと。少なくとも受けとめられるようにしておいてほしいなと思うのですけれども、その２点、区の考え方を説明を求めました。","respondent":"小林施設整備課長","answer":"それとあと２点目の区民からの問い合わせ、これは建築課長に聞いたところ、今のところないと聞いております。今のところはないものだと考えておりますけれども、国等の動向を注視しながら、何かあればその対応をしていくという考えです。","id":"exchange-053"},{"speaker":"あべ委員","kind":"質問","question":"すみません、ちょっと何年前かは忘れたのですけれども、あそこの食堂の運営事業者が変わったときにかなり内装に手を入れて、器具なども取り替えたと思う、それからまだ数年しか経っていないと思うのですけれども、今回照明、什器の入れ替えというのは、何かきっかけというか、背景はあるのか尋ねまし…","respondent":"米田人事課長","answer":"そうやって一部更新はしていますけれども、更新をし切れていないところということでは、照明設備と、いわゆる椅子等の関係ですね。手のついていないところについてやっていて、第二庁舎２階の食堂をより快適にご利用いただくためというようなことでご理解いただければと思います。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858739?Template=document&Id=2030#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":64353,"voices":146}},{"id":"h27-20151110-14","meetingId":"h27-cm11","date":"2015年11月10日","dateIso":"2015-11-10","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ５時０１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件整理しています。","topics":[{"id":"topic-01","title":"平成２７年陳情第２号、未利用国有財産の取得・活用に関する陳情につきましては、予定表３、特定事件調査の(1)公有地・跡地活用に関すること","agenda":"平成２７年陳情第２号、未利用国有財産の取得・活用に関する陳情につきましては、予定表３、特定事件調査の(1)公有地・跡地活用に関すること","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"幾つかまず確認したいのですけれども、東五反田５丁目１８番１６号、建物の用途地域の規制を詳しく教えてください。それから今、建ぺい率６０％と説明があったのですけれども、そういうところをもう少し説明を求めました。","respondent":"柏原企画調整課長","answer":"仮になのですが、いきますと、恐らく延床で２,０００m2以上は建てられるのではないかというような試算はしています。そういったところからしましても２階、もしくは３階いけるかどうかといったところの高さになろうかと思います。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"それから、土地の照会があったところという説明だったのですけれども、想定で結構ですから、もしこの土地を買うとするならば、どれぐらいのお金が必要でしょうか、説明を求めました。","respondent":"柏原企画調整課長","answer":"金額の提示はまず最初にはございませんので、現段階で路線価ほか諸々を調べますと、概ね１７億円から１８億円ぐらいは下らないだろうです。不動産鑑定等をかけて、１７億、１８億円から２０億円ぐらいのところの金額になるのではないかというふうに想定しています。","id":"exchange-002"},{"speaker":"たけうち委員","kind":"質問","question":"極端に公共施設が遠いとか、そういったことがあるのかどうか、まず説明を求めました。","respondent":"柏原企画調整課長","answer":"例えば大井地区であるとか、極端にここの地域が地域センターと離れているかというと、そういったところではないだろうというふうには捉えてあります。学校等々もありますけれども、第三日野小学校であるとか、日野学園であるとかといったところが近隣になるといった状況です。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"質問","question":"なかなか反対があったということも伺っているので、また、仮にそういった施設をつくった場合のその辺のところの懸念材料というのですか。陳情の要旨の２番には、そのような懸念も含めての所感というのですか、感想というのがあれば説明を求めました。","respondent":"柏原企画調整課長","answer":"我々区としましても、今後のオリンピック・パラリンピック、様々な面について観光を推し進めていこうという施策としては持っているところであります。これは慎重に考える必要があるだろうというふうには思ってありますので…","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"区としての見解を伺いたいと思います。区としては、どのようにお知らせしているのか伺えればと思います。","respondent":"柏原企画調整課長","answer":"環境を崩さないような、そういった形で資源を整えていくといいますか、そういった中身でもっているといったところで聞いているところです。そういったお話があるというところで、担当の部門のほうと確認をしているといったところです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"こうしたものを組み合わせた複合施設というのは、私は、品川区としては物件を購入する考えはないのでしょうか。そこら辺をあわせてお伺いします。","respondent":"中村都市計画課長、柏原企画調整課長","answer":"内容等をお知らせするということはしておりませんけれども、環境協定に関する窓口、地域の守る会の窓口をご紹介させていただいているです。そういった形で… それに対する効果、先ほども前段ご質問にお答えしたところですが、費用と効果の部分について慎重に検討が必要だというふうに思ってあります。購入するにあたっては、かなり慎重な検討が必要なのだろうというふうには思ってあります。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"私、伺ったのですが、今回の複合施設という提案ではありますけれども、品川区の福祉と文化や魅力の向上にとって資するものになるのではないかと。そうした考えはないのかということを伺ったので、魅力向上につながるのだけれども、そこら辺が少しわからなかったのでお伺いしますとの意見を述べました。","respondent":"柏原企画調整課長","answer":"それに対して、区としてその課題に対してどう対応していくのかという大きな課題があるといったところです。そういったところを総合的に見ていった場合に、慎重な検討、かなり難しい物件ではないかというふうに思っているといったところです。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"やはり大切なのは、本当に必要かどうかというところが大事なのではないかというところだと思うのです。今年だけで住民税が２０億円積み増されて、基金も７７７億円から８１５億円になっているということで、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"それからそれに対する効果、つくっていけるのか、そういったところを総合的に判断しなくてはいけないというお話をさせていただいているところです。費用をかけることがどういった効果が出るのかというのを十分に検討しなくてはいけない、そういったところをお話ししているもので…","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"やはりすごく、環境協定をつくるほどの地域ですから、地域をよくしたいという熱意があるということなのですね。ですから、私はそこはデメリットにはならないと思いますけれども、もう一度そこら辺についての区の考えをお伺いします。","respondent":"柏原企画調整課長","answer":"そういったところもありますので、効果を十分検証しながら判断するという難しい局面にあるというのは間違いないといったところであります。そういう状況下にあるということをご理解いただきたいというふうに思ってあります。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"それとあと短期間で判断しないといけないというお話でしたけれども、そうなのです。短期間に寄せられた署名の思いというのを酌んでほしいと求めましたし、この陳情に賛成していただくよう呼びかけさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"伊藤委員","kind":"確認","question":"先ほど来説明をずっと聞いていまして、何点か確認と質問をします。聞きたいのが、買う場合には、全部これは品川区の一般会計なのでしょうかということが１点。","respondent":"柏原企画調整課長","answer":"そうしたときに、やはりボリューム的には大きいものが必要になるというのは、一定程度の考え方だろうと思ってあります。ではそれに対してどういった行政の施設ができるかというのをいろいろ検討はしておりますけれども、行政課題に対していろいろ解決できる建物としては。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"意見","question":"例えば３倍、これだけのお金を仮に投入したところで、果たしてこの土地と用途地域の中でどれだけの成果を得られるであろうかということ。そこについて非常に疑問に思うのだけれども、品川区のお考えを説明を求めました。","respondent":"柏原企画調整課長","answer":"区としましても、先ほども議論があったところですが、そこはやはり重点的な検討をしなくてはいけないといったところです。そういったところの判断で、こちらも効果をどう考えていくのかというのは、かなり難しいところにあるというものです。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"意見","question":"ヨガ教室、情報交換の場、終の棲家等々を否定するわけではないです。ただ、値段が安かったり、これはまさに行財政改革特別委員会の議論の中でどう考えて私たちがゴーサインを出すべきかどうかというのはとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"大倉委員","kind":"確認","question":"延床２,０００m2とれるけれども、１点だけ確認なのですが、そういう想定はあるのかどうか説明を求めました。","respondent":"柏原企画調整課長","answer":"建物によって維持の考え方がちょっと違ってきますので、例えば建物をこちらに建てて民間に貸し付けて維持をお願いするという考え方はあるのかもしれませんが、細かい想定は今の段階ではしていないです。","id":"exchange-014"},{"speaker":"大倉委員","kind":"意見","question":"いろいろお話が書かれている中で、ほかと比べてもそんなに差がないとか、また観光の視点からも懸念材料は様々あるというお話もありました。費用対効果という部分ではかなりかかってしまう部分から見ると、難しいのかなというところは非常に感じましたので、意見として述べしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"沢田委員","kind":"質問・要望","question":"１点確認をさせていただきたいのですが、どういうふうに使用するか、それはそういうものなのかということ。大体どういった形で話が進んでいくと想定されるのか、東京都のほうには話は行くのかとか、その辺りの確認をさせてください。","respondent":"柏原企画調整課長","answer":"回答がもし自治体のほうで買うとか借りるという話になればそこで終わりなのですが、基本的には一般競争入札のほうに流れていくのですが、今の段階で。建物の図面であるとか、かなり突っ込んだところの回答をしなくてはいけないというのが実情としてはあります。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"課長のこの委員会での答弁を伺っていると、この案件をどういうふうにするかは決まっているように私個人は感じるのですけれども、まずお伺いします。","respondent":"柏原企画調整課長","answer":"我々担当レベルといいますか、調べるといいますか、担当している部門からしますと、物件としてはかなり難しい物件だという認識はしています。ただ、最終的にどうするかという判断というところでは、まだ判断をしていないという状況です。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"国からというのは同じではないですか。書式になっているようなものというのは、判断するのにおいて、点数制をつけていくみたいなものというのはあるのか尋ねました。","respondent":"柏原企画調整課長","answer":"これは私だけではありませんで、最終的に判断するトップを含めて、悩みながら決めているといったところです。何階建てで何人ぐらいが入るとか、そのぐらいのものはボリューム感としては出さなくてはいけないというのは、国から言われているところです。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問・要望","question":"あえてこういう質問をさせていただいたのですけれども、陳情がこうやって出ていて、地域の方から取得してほしいという陳情が来ているわけです。上大崎は取得したわけですから、東五反田と上大崎の違いというのは、今の時点で考えているのはどこか尋ねました。","respondent":"柏原企画調整課長","answer":"違いというところでありますけれども、１つに絞ってというのはなかなか難しいところがあります。大きくは今３つお話ししましたけれども、トータルですけれども、この物件についてはまだまだ難しい課題があるのだろうというふうに思ってあります。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは訪れる新たな池田山を見に来てくれる方のことですから、それは私は克服できる課題だというふうに思っていますので、これは意見です。質問なのですけれども、どういう意味なのかというのをお伺いしたいのと、（「国だろう」と呼ぶ者あり）そこら辺をちょっとお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"これは変更の可能性がありますというのはもちろん入れながらですけれども、重要なファクターであるというふうに思ってあります。ただ東京都の動きはちょっと見えませんけれども、この段階で動きがないところからしますと、東京都はあまり意向がないのではないかと思ってあります。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"これは事実上、そういったケースになるところというのは、社会福祉法人だけなのですか。例えば宗教法人ですとか、そういったところも入ってくるのか、そこら辺をお伺いします。","respondent":"柏原企画調整課長","answer":"そこの判断は国のほうでしておりますので、どういった法人関係がなるのかというのは私のほうではわからないといったところであります。それ以上の判断につきましては、多分国のほうで判断をしていると思いますので、この場ではお答えが難しいところです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"品川区、とてもよくやってくれていて、大変評価されていました。環境の維持に活用してほしいという思いで出された陳情ですので、この声をしっかり受けとめて、改めて区の考えをお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"申し訳ございません、繰り返しの答弁の部分がありますが、区といたしましては、様々な行政需要等々に対して、どういった効果が出るのかといったところ、それから費用の面、いろいろなファクターを考えながら、総合的に判断をするといったところです。","id":"exchange-022"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"あくまでもここは行革委員会で、この陳情を我々も、我が会派の沢田政調会長も皆さんから意見を伺って、この気持ちはわかります。そういうような発言に聞こえるし、ちゃんと冷静に議論をしているということを、私はやってほしいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"ですから、きちんと税金を納めている方々が、税金は能力に応じて払います。そういった意味で発言をしましたので、ぜひ副委員長には誤解していただきたくないというふうに、私の意見を述べします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから、要望を幾つかつけて、不採択の話をします。ここに書かれた様々な区民要望は、品川区の全体の施策の中で具体的に解決することは私どもも求めてまいります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そういった面ではやはり限られた制約の中で、なかなか使い勝手が難しいのかなという中で、購入は難しいのかなという理由です。区としても受けとめていただいて、できる限り何かまた違う形でやっていただければということを要望して、不採択ということでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"安藤委員","kind":"意見","question":"私は、詳細な具体化を進めていけば、必ず品川区の未来につながるようなすばらしい施設になるということは間違いないのではないかと確信しています。陳情の採択を主張しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"大倉委員","kind":"質問・要望","question":"課題、ほかの行政需要という部分にしっかりと取り組んでいかなければいけないのかなというところで、不採択とさせてほしいと求めました。こうしたところで対応していっていただきたいという思いを持ってはおりますが、今回の陳情に対しては不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]},{"id":"topic-02","title":"特定事件調査の(2)国家戦略特区に関すること","agenda":"特定事件調査の(2)国家戦略特区に関すること","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"５番の民泊のルール整備については、これは今、いろいろな新聞やテレビでも相当報道されていますよね。だから、ああいうアイデアを取り入れていくことを考えていくべきだと思うのですが、品川区のお考えはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"当初は条例でそれを決めようということで我々もいろいろと検討しておったのですが、その考え方を、詰めております。これは条例というのをしなくては物は動きませんけれども、そういったところがもう少し深い検討が必要というところでやっているところです。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問・要望","question":"文化も言語も生活習慣もまるっきり違う方々が日によって出入りをするわけですから、いろいろな軋轢が生じることは確かなことなわけです。やっぱりそれは行政の知恵が求められると思いますので、必ず答えはあると思いますので、頑張って見つけてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"伊藤委員が質問というか、ニュースを見て、これから民泊ですよねと言うとトレンドに乗っかっていていいのかなと。そもそも副委員長、旅館業詳しいかもしれないのですけれども、こういう形で伺ってもいいのですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"もしわかれば教えていただきたいのですけれども、経済的に、民泊をさせてはいけないよというのが強かったのか。そもそも論なのですけれども、すみません、副委員長に聞いてあれかもしれないのですけれども。","respondent":"柏原企画調整課長","answer":"そういったところの受入れがまず何とかできないかというところです。一定程度中小の旅館をやられている方に対しては影響があるというのは、ここは間違いないだろうというふうには思ってあります。","id":"exchange-032"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"安心・安全に宿泊していただける施設を提供する、それが国が今まで言ってきた旅館業法なのではないですか。安全・安心に泊まっていただくにはどういうものがあるのか、基本は旅館組合の方々はそうおっしゃっているのではないかというのが、私の理解です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"藤原委員","kind":"意見","question":"なぜ民泊がいいかといったら、ネットのニュースで見たときに、空いているマンションの１室に泊まっていただいても民泊というのでしょう。反対意見ととられてしまうとあれなのですけれども、いいのかと問いかけはしたいと思ったので、今日そういう話をさせていただきましたとの意見を述べました。","respondent":"中塚委員長","answer":"今、民泊のルール整備がテーマになっているので、もし良ければ、ここを少し深めていけたらいいなと。全部はできませんけれども、整理しやすいので、そんなふうに進めていきたいと思います。","id":"exchange-034"},{"speaker":"たけうち委員","kind":"提案","question":"前々回ぐらいですかね、質問したときに、やっぱりやっていかなくてはいけないのかなというふうに思っております。行政として、しっかりまた我々ももう一回押さえないといけない上で、それで最終的には提案という形でできればいいなというのも含めて民泊関係との意見を述べました。","respondent":"中塚委員長、柏原企画調整課長","answer":"委員会の進め方や必要な資料や、いろいろご意見を出してください。今、たけうち委員から、供給体制がどれぐらいかというのがありましたが、今、何かわかる範囲ということですけれども。 やっぱり８割から９割の稼働率で動いているという数字が、確実に、品川区も例外ではないというところであります。そういった数字の部分については、我々も追いながらというのは必要だろうというふうに思ってあります。","id":"exchange-035"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"それがある程度建っているから、この特例はやめてしまうということは可能なのかどうか。国家戦略特区のここら辺の法的なところというのはどういうふうに捉えたらいいのかとの意見を述べました。","respondent":"柏原企画調整課長","answer":"通常、それに対して東京都からは明確なお答えを我々はもらっていませんので、そこは一つ検討する課題の部分であろうというふうに思っております。我々もポイントの一つだというふうに思ってありますので、調整といいますか、検討していきたいと思ってあります。","id":"exchange-036"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"今はこんな山になっているからあれだけれども、平らにしていくとするならば、もっと公園を広く使えるわけではないですか。だけど、そこに保育園があるから、そこは特例の縛りの中で、それは公園としては使えないと言われてしまうのかというのも改めて教えてほしい。","respondent":"柏原企画調整課長","answer":"旅館業法の話では難しいという答えをもらっているのですが、公園については２年間のうちに申請をしてくださいという、逆に期限を切っているのです。若干、我々としては矛盾を感じているところでありますけれども、今の特区の法体制はそういう考え方をとっているということです。","id":"exchange-037"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"これからまだどういうのが発表されるかわからない時点ですみません、これから出てくるのでしょうから、これは答弁はいいです。これをもし条例化しようとか、大田区も大阪市もいろいろ出てくるとなると、我々はどういう判断をすればいいのかというのを教えてほしい。","respondent":"柏原企画調整課長","answer":"きちんと体系がどうなっているのか、規制がどうなっているのかというのをご説明した上で議論させていただいたほうがよろしいかと思います。すみません、細かい事情もいろいろあるので、できれば別の機会に資料をご用意させていただいて…","id":"exchange-038"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"我々が与えられているのは国家戦略特区ですから、例えばこういうのも行政にやってほしいというようなことも含めて出していければいいかなと私は思ったというのだけ、意見だけ言っておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"その努力の上にこうしたルールがつくられたわけですから、処遇を改善するということが必要なわけですから、私はこの３点は今回。制度上の制限の、スケジュール感等の説明も含めて、西大井でいうと開設の見通しはいつぐらいなのかというのをお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"西大井広場公園、条件等々も含めて合致しているというところがありますので、具体的な内容として検討しています。ほかにも区のほうの公園、種々ありますので、可能性については検討しているといったところです。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"区域会議にかけるということでした。最短で、直近の区域会議というのはいつで、そこにかけた後、そこからどれぐらいかかるのかというのを、もう少しご説明をいただきたいのですが。","respondent":"柏原企画調整課長","answer":"細かい保育園の設置についてのスケジュールというのはなかなか難しいところでありますけれども、調整が終わったところで区域会議にかけると。事前の調整が済んだ中でというところになりますので、今の段階でどのタイミングでいけるかというのは、未定の部分です。","id":"exchange-041"},{"speaker":"伊藤委員","kind":"質問","question":"１番の商店街等の店舗前における道路占用規制の緩和という表現がありますけれども、大崎駅の再開発地域であるとか、新しいまちができたわけです。それを実現するためにはどういうステップが必要なのかということもあわせて説明を求めました。","respondent":"柏原企画調整課長","answer":"それが形としてなっていくかどうかというのは、区としてもいろいろお話を聞きながら、応援できるところは応援していきたいと考えています。具体的にできそうなところが芽出しができたところをうまく使っていくというのが…","id":"exchange-042"},{"speaker":"伊藤委員","kind":"質問","question":"そして大崎駅だって今度、バスのターミナルができますよね。導入策を担保した上で、規制緩和の推進というのは必要だと思うのだけれども、それでも品川区はやらないおつもりなのか尋ねました。","respondent":"柏原企画調整課長","answer":"所管部門がそこのまちの中に入りながら話をしたりだとか、できるかできないかみたいなところも含めてやっていくというのは、実情としてはあります。ただ、時間がかかる可能性があるというところはありますけれども…","id":"exchange-043"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"そうすると、あの時間にそういう通行する方といろいろちゃんと仕分けしたりなんだりするけれども、みんな店を出していいよと。区商連なり単体の商店街でもいいのだけれども、地域がみんなでそれをやりたいのだと言えば、これはオーケーだという理解でいいのですよねとの意見を述べました。","respondent":"柏原企画調整課長","answer":"今、副委員長おっしゃっていただいたような団体の方々がそういう形で使うというのは、特区を使う流れとしてはそのとおりできると思います。いろいろそういったところは個別の要件があると思いますので、それはご相談させていただきながらにはなると思いますけれども、可能です。","id":"exchange-044"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"もう一点そこをお聞きしたいのは、そうなると、例えば今、お買い物道路というのは決め事だけではないですか。そういう理解でいいのかどうかだけ。","respondent":"柏原企画調整課長","answer":"行政機関との調整が事前にありますので、それを経た上で、区域会議に持っていくと。警視庁の協議は一月に１回ぐらいしかできないのですけれども、個別のお話ということでご相談いただければ、調整します。","id":"exchange-045"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"そうすると「かむろ坂等において、道路空間を活用したイベントを実施可能にする」というのは、意味がわからなかったのだけれども、これは、例えば桜とか、話はおっしゃっていたけれども、別に国家戦略特区ではなくてもいいのですよね、これは何でもやれるということですよねとの意見を述べました。","respondent":"柏原企画調整課長","answer":"一定程度のイベントであれば、通常の規制の緩和といいますか、やり方でできると思います。例えば１週間もずっと止めておくとか、そういったスパンで、それは具体的にどういうことをしたいのかによってくると思います。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問","question":"１点だけ端的に。６番の国交省との調整が難色を示しているというところを、もう少し詳しく教えていただけたらと思います。","respondent":"柏原企画調整課長","answer":"区で検討しながらなのですが、打ち合わせといいますか、しています。いろいろなものがないと定期航路というのはなかなか大手の事業者でないとできませんから、その調整をしているということです。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"現在では１０年間ということだったのですけれども、まだ１０年後も保育のニーズが高まった状態で、更新して利用を続けることというのはできるのかということを確認させてほしいと求めました。","respondent":"柏原企画調整課長","answer":"占用の考え方というのは１０年間というのがマックスというふうに聞いておりますけれども、更新という考え方がどういう形でもっているのか、それは確認をさせていただければと思っています。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問","question":"まだわからないということだったので、ぜひわかりましたら、ご報告ほしいと求めました。区に何かこういった、これに関係する連絡というのは来ているのか、お伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"報道等で出ている部分です。中身につきまして細かく通知があったとか、相談があったということは、現段階ではございません。","id":"exchange-049"},{"speaker":"大倉委員","kind":"質問","question":"いろいろお話を伺っている中で、もう少し絞って、何か先に進めていけるような話が今後できたらいいなというところを非常に感じました。今かなり議論にあったところ辺りを絞って、今後やっていっていったらどうかという思いがあったので、意見だけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"}]},{"id":"topic-03","title":"羽田空港の機能強化に関すること","agenda":"羽田空港の機能強化に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"私も２点ほど質問させていただきましたけれども、率直な思いを述べさせていただきたいのですが、計画は中止をと求めたのですけれども。常々国がきちんと説明することを求めていきたいと述べておられますけれども、どのような感想を持たれたか、お伺いします。","respondent":"中村都市計画課長","answer":"区が地域の住民の方に丁寧な説明をという中で進めているところで、今後また第２段階、今後のさらなる対応に期待しています。ミューザ川崎等での見学もしていただきまして、そういった中で一定程度の説明はあって、丁寧に対応していただいたのかなという感想を持っております。","id":"exchange-051"},{"speaker":"安藤委員","kind":"提案","question":"２つ、指摘と提案をしたいのですが、国がどう考えるかという回答がないのです。それは区だけではなく、議会として求めていく必要があるのではないかと思うのですけれども、お考えをお伺いしますとの意見を述べました。","respondent":"中村都市計画課長","answer":"今、フェーズ２にあたりましてまた説明会を予定しているということですので、国のほうからまた情報提供があるものというふうに考えてあります。これは２０１６年のフェーズ２のところに、そして強化方策の実施というものが、こうやって予定として出されております。","id":"exchange-052"},{"speaker":"安藤委員","kind":"提案","question":"品川区のほうから丁寧に説明をしてほしいと求めているのです、私、具体的な提案もさせていただいたのですけれども。何も区が進める事情なわけではないですから、そういった意味で言ったので誤解ないようにぜひしていただきたいと思っていますとの意見を述べました。","respondent":"中村都市計画課長","answer":"丁寧な説明というものの意味合いですけれども、説明会を開催するにあたりましては、こういうことです。国の今後出していくという方針ですけれども、こちらのほうも、やはりわかりやすく、また具体的に出していただくようにお願いをしております。","id":"exchange-053"},{"speaker":"安藤委員","kind":"提案","question":"党派をもちろん超えてということで、そういった提案をさせていただきましたけれども、そういった立場からいって、それはそれとして、ごめんなさい。ご意見を、あるいは質問されていた自民党などに、もしご意見を伺えたらというふうに思っておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"伊藤委員","kind":"質問・要望","question":"意見を表明して、意見書も出して、様々なパイプを使って、品川区議会の要望を伝えた、これは事実です。そこに出てきたときにどうしていくかということについて様々な対応をとっていくことのほうが、品川区のお考えを説明を求めました。","respondent":"中村都市計画課長","answer":"フェーズ２、区としてもフェーズ１のところでもやはり地域の皆様のために国が説明をしたいというところでは協力をしてきたところですけれども。なかなか区としても協力が難しいのかなというところも考えておりますので、これは継続して今後も引き続き協力依頼をしてまいります。","id":"exchange-055"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、様々なルートでこういう情報が入ったら、なるべく早く議会にお知らせしてくださいますようにお願いしておきます。一部分だけ切り取って表現するというのは非常に誤解を生む可能性があるので、それはやめてくださいということをお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"だから、それを自分の支持者だろうが、区民の前だろうが、言うのは構わないが、本当に反省をしてほしいと思っています。ゼロが１になるということは反対が多い、自らそれを訂正する、区民に向かってもちゃんと説明をしてほしいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと厳しいご指摘をいただいたので、私からも発言させていただきたいのですけれども、私はできるだけ正確に言ったつもりではありました。当日、ほかの委員からもいろいろな質問ですとかご意見などを出されておりましたので、ぜひお伺いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"塚本委員","kind":"質問","question":"すみません、最初にちょっと細かいことなのですけれども、ニュースレターについて、多くの意見について、これ全部（案）とついているのです。（案）というのがちょっと違和感があったので、どういうつもりで（案）とつけているのかというのを最初にお伺いしたいのですけれども。","respondent":"中村都市計画課長","answer":"１つは、それを言っていただければここに加えるという、そういった趣旨です。","id":"exchange-059"},{"speaker":"塚本委員","kind":"質問・要望","question":"昨年１２月に議会として第４回定例会で出した意見書に沿って今、丁寧な説明というものを求めて、スタンスであるというふうに思っています。いよいよ第１フェーズが終わりまして、双方向の対話というのはどういうようなやり方を、ちょっとお話をほしいと求めました。","respondent":"中村都市計画課長","answer":"１つは、これは従来の教室型の説明会を行ったときに、どうしても最初の前半部分はこの内容の説明に終始してしまうと。説明をして終わったのだという事実だけが残るですけれども、今回は１回目のフェーズ１の説明で、こういった一回一回の説明会の中でのやりとりと。","id":"exchange-060"},{"speaker":"松永委員","kind":"質問・要望","question":"１２月８日に八潮学園のランチルームということでお伺いしたのですけれども、周知方法というか、お伝えされているのか。最後に、品川区に対してのメリットというのは、区としてはどのように考えているのか、伺いたいと思います。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"八潮の皆様に対する今回の１２月８日の件につきまして、私からご説明します。飛行機の性能は変わったとは国からは聞いておりますが、引き続き試験飛行に関しては、また国に対して要望してまいります。 今回の機能強化につきましては国策で進めるというところで、その説明の中では、こういったものがあります。外国人観光客の増加、こういったところで…","id":"exchange-061"},{"speaker":"松永委員","kind":"質問","question":"いろいろわかりましたけれども、他地区に対してという説明はしないのでしょうか。そうした中でやってもらいたいと私は思うのですけれどもいかがでしょうかということと、あと、住民に対してのメリットというのを聞きたいと思います。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"他地区に対する考え方ですけれども、まず今の現段階につきましては、全てのところに対しては回覧板ということを行っております。回覧板だけではなく、できる限り本当に詳細に各戸配布などを含めて… 国策で進めていくというところで、そういったところが区民の直接的な利益に関連してつながってくるという、そういったところです。","id":"exchange-062"},{"speaker":"のだて委員","kind":"確認","question":"「羽田空港のこれから」のニュースレター２号、北風と南風で４案あるにもかかわらず、１案ずつしか示されていない。１つ確認したいのは、まだ北風と南風で４案残っているのか、品川区は国からどう説明を受けているのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"１つは、実際に事故が起きるというケースは非常に少ないというところが、これは国の説明としてありました。南風２案ずつ４案示されまして、南風案についてそれぞれの１案ずつを採用したい、たしかそういった説明があったというふうに記憶しています。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/842551?Template=document&Id=5996#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":55717,"voices":142}},{"id":"h27-20151111-18","meetingId":"h27-cm11","date":"2015年11月11日","dateIso":"2015-11-11","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時２３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"指導者のところの障害者に対する理解だとか、そのあたりのことをどういうふうに考えておられるのかをちょっと２点目として伺いたいと思います。私が伺った方はたまたま水泳教室だったのですけれども、私はいいかどうか全然わからないのですけれども、その３点を伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"種目についてのご説明です。高くなって落下するようなことがないように、わざと壁際に寄せまして、当然周りにはクッション等のほうも用意させていただきましてやっております。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"これからもっと一層拡大できるように、そういう方向性もどういうふうに考えていらっしゃるのか、その辺を伺っていきたいなというふうに思っています。一つは、７団体に限らずね、障害者のスポーツ人口を広げるための考え方というのがどういうことなのかちょっともう一度教えてほしいと求めました。","respondent":"池田スポーツ推進課長","answer":"ことしは大々的に地域のお祭りともタイアップして行いましたので、大勢の方も参加していただいております。そういったことで、できる限り情報としてつなげるものは利用して、ＰＲ活動を進めていきたいというふうに考えてあります。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"何というのでしょうかね、そういう方向性もちょっと考え方として示していただきたいなと、その２点を伺って終わりにしたいと思います。","respondent":"池田スポーツ推進課長","answer":"例えば、きちんとできる範囲ということで４５人の定員で、たまたま来られない人がいたということでご理解をいただきたいと考えています。こちらのほうをＰＲして、障害を持っている方も健常者の方もご参加いただけるようにということでＰＲしていきたいというふうに考えておりま…","id":"exchange-003"},{"speaker":"筒井委員","kind":"質問","question":"平成２６年度実績を見せていただいたのですけれども、平成２６年度実績をまず見せていただいた、このまず意味を教えてください。というのが１点目で、２点目は、そのブラインドサッカーの教室とか大会等を推進するお考えはあるのかということをお聞きしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"筒井委員","kind":"質問・要望","question":"どんどんブラインドサッカー、ＰＲを広めていってほしいと求めました。それで、何か成果を発揮する場所ということで、大会とかをやる予定はあるのか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ブラインドサッカーの大会というものにつきましては、区内独自で大会というものは今考えてはございません。本当にブラインドサッカーをやっている選手たちが、区が何かしらお手伝いをして、大会の誘致なども今後検討してまいりたいと考えているところです。","id":"exchange-005"},{"speaker":"吉田委員","kind":"意見","question":"２５、２チームというような表記なのですけれども、この参加人数とこの備考との関係をもう１回もしあれでしたら説明していただけるといいと思います。障害者３チームが参加してくださったということで、そういうことがルールというか…","respondent":"池田スポーツ推進課長","answer":"全体では２００人参加されていますけれども、たしか５人か６人の編成チームなのですけれども、あえてこちらのほうはチームというふうな書き方をさせていただいたところです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"確認","question":"では、確認ですけれども、２００人というのは選手として全部を合計すると２００人ぐらいで、その中で障害者のチームの方が３チームということで、ほかの方たち何チームかということですよね。","respondent":"池田スポーツ推進課長","answer":"そうです。２００人の中で、チームの中で３チームのうちの何人かが障害者の方が参加されているというようなことでご理解いただければと思います。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"一緒に、一緒に１チームをつくっているということなのですけれども、大会としてのルールは同じような条件でゲームをしていらっしゃるのでしょうか。それとも、何か本当に楽しめるようにちょっとハンデをつけるとか、そういうことがあるのか説明を求めました。","respondent":"池田スポーツ推進課長","answer":"ルールを変更いたしまして、試合を行いまして、セットをとったというようなこともあります。詳しい、どのように変えたかということにつきましては、ちょっと資料が残っておりませんので、お答えできません。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"具体的には伺わなくても大丈夫かなと思うのですけれども、本当にそれはそれですごく楽しいし、盛り上がるし。ぜひそういう方向も広げていっていただけるといいかなと、これは要望として言っておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"５番のスポレク旗の台地区みんなでグラウンド・ゴルフの、これ感想と確認をさせていただきたいのですけれども、楽しく私も参加させていただきました。それだけ確認させてください。","respondent":"池田スポーツ推進課長","answer":"こちらのグラウンド・ゴルフ大会につきましては、旗の台地区というところで平成１０年度から行いまして、伝統的なものです。たまたま今年度、場所は変わるということはなく、これはずっとおそらく旗の台のほうで続けることになると私は思っております。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"意見","question":"地域とってどういうことかということが書かれていていいなと思ったのですけれども、２７年度末に最終まとめが出るというふうに書いてあったのですね。何か方針とか目標とかが、地方自治体でも頑張りましょうというのが出されるものなのか、どういうものなのかをちょっと説明を求めました。","respondent":"池田スポーツ推進課長","answer":"こちらの方針につきましては、国が地方、これ主に都道府県と政令指定都市を対象に示したものでございまして、最終的には今年度３月に方針というものが出される予定になってあります。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"確認","question":"今後方針というふうに今課長はおっしゃったのですけれども、会議体というか、そういう中身になっていくのかというのをもう一度確認したいのです。やはり仕事との両立というのですかね、人員もさらに広げていくということもこういった普及の促進についてのまとめでは出されてくるのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"文部科学省から都道府県、私どもでいうと東京都を通じて品川区のほうに通知が来るというふうな形になってくると思います。こういった国、都の方針を受けまして、品川区としてまた充実した障害者施策というようなことを考えていきたいというふうに思っております。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"前回、東京都障害者総合スポーツセンターでしたか、視察をしました。何かこう、交流だったり、懇談というのはあるのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"近隣区との障害者スポーツの交流会についてですけれども、昨年は私ども品川区が幹事区になりまして、第３ブロックということで研修を行いました。もしくは、第３ブロックだけでなく、東京都内の障害者スポーツについての情報交換ということも行っているところです。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"支援する周りを増やしていくべきだなと思いますので、そして、支援する側も参加しやすい場をつくっていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"意見","question":"この文部科学省の中間整理の下の枠の５番に、その１番目に、こういう連携というのは日頃どうなってらっしゃるのか。そういうところはもちろん所管をされてらっしゃると思うのですが、日頃のそういう連携というのはどうなっているのかお教えくださいとの意見を述べました。","respondent":"池田スポーツ推進課長","answer":"２番の部分、障害者福祉課とも、こういったものをやりたいのだけれどもということでは協議はさせていただいてあります。文化観光の部門も一緒に入っておりまして、障害者についてということで、連携してやるようなことはやってあります。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問","question":"これはもしかすると委員長にお尋ねするかもしれないです。今日、障害者福祉課長というのはそもそも何かご用事があって来れないということなのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどのちょっと、そこら辺これからやはりもっと連携していただきたいということと、やはり障害者、以前に私こういった経験があったのです。そういう何か教えてくれる指導者の情報を提供してくれないかということで、スポーツ推進課なのか、その辺についてはいかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"ただいまの指導者と、それから、障害をお持ちの方のスポーツについてのご相談ですけれども、正式な場所はどこかということは決まっていないです。そこで担当が回答できるものはそこでお話をするですので、そういったことで区民の方にご紹介していただければとは考えております。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それはまた別の機会だということで伺いましたので、フューチャーされて、それが高い評価を得たというような状況もありました。品川区障害児者総合支援センターですか、連携して取り組んでいただけるのか、その辺について説明を求めました。","respondent":"池田スポーツ推進課長","answer":"ただ、その子たちが成長いたしまして、今ではいろいろなイベントにも呼ばれてダンスを披露するような形になってあります。そういったところで、その中に障害をお持ちのお子さんも一緒にやったりとかということでやっていければなというふうに思っております。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区でもそうやって障害者も含めたダンスの活動に熱心に取り組まれているということですので、これ非常に幸いなことだと思います。この部分ぜひ力を入れてほしいと求めましたし、ぜひ連携をお願いしたいと思いますが、もし一言あればどうぞ。","respondent":"間部文化観光課長","answer":"区民作品展というものを芸術祭でやっておりますけれども、来年度以降、今度アール・ブリュット展も連携していこうということで今調整をかけています。連携をして、きちんと対応していくというのが区の姿勢としては大事だと思っていますので…","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"文化観光課長からもそのように、まさにそのとおりのご答弁いただきました。ぜひそういったものを大切に育成していただいて、意識的に発揮できる場をつくっていただきたい、このような働きかけもお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"渡部委員","kind":"質問・要望","question":"ブロックの中とかで、例えば、それを東京都に上げていこうとかという話は出たりすることはあるのでしょうか。出ていなければぜひ出していただきたいと思うのですが、それを１点お願いします。","respondent":"池田スポーツ推進課長","answer":"目黒区とか、いろいろですけれども、狭い小さいところでは障害者のそういった専用の施設をつくるには大変困難なことだと考えています。これについては、研究させていただければと考えております。","id":"exchange-021"},{"speaker":"渡部委員","kind":"質問・要望","question":"その中で１カ所整備をすることによって、水曜日動けるわという方もいらっしゃるでしょうから、それをお願いします。２０２０年に向けて、都から予算がついてきたらそのような啓発活動をやっていくおつもりかどうか、あわせてお願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"商工会議所と、そういった企業関係、団体関係を一つの品川サポーターのような形で編成をしていくというようなことを今まさに検討しています。それは補助金がつこうがつくまいが、区としてぜひ進めていきたいというふうに考えているところです。","id":"exchange-022"},{"speaker":"渡部委員","kind":"質問","question":"そういうような機会をどんどんつくる。どうですか、積極的にやりたいわと思われるような仕組みに持っていってほしいと求めましたので、よろしくお願いをいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問","question":"あそこの公園そのものは中央海浜公園で、そこの管理というのはこの間私たちも視察に行ったときに説明してくださったところがやっているわけですよね。わからないというか、お答えにくいのかなとはちょっと思うのですけれども、どんなふうなところか説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"その先行して実施している４施設につきましては、予定どおり基本設計等は、年度のほうは予定どおり進んでいるという内容です。その施設運営計画策定支援事業者という位置付けですので、あくまでも今後、民間からも考え方を募るということの事業者だというふうに伺っております。","id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"あまり深入りできないのでどういうふうに伺ったらいいかちょっとわからないのですけれども、どういう、後利用のやり方なので。そうでもないみたいなので、どんなふうに受けとめていったらいいのかなというのがちょっとわからないので、もう一度質問します。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"第三者の目をもう一つ入れて、透明性を高くするということがこの考え方の、東京都の一つの狙いだというふうに聞いてあります。きちんと民間のアイデア等を交えながら、透明性の確保ということもあって、こういった手法を一つ取り入れるというふうに伺っているところです。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"透明性の確保は大事なことだというふうに思うのでね、それはそれで受けとめたいと思っています。もう少し様子を見守って、また後日必要な場面があったら質問というか、はっきり認識していきたいと思います。","respondent":"本多委員長","answer":"以前の委員会でお示ししました調査日程では、次回の１２月３日の委員会では味の素ナショナルトレーニングセンターへの視察を予定しておりました。以上で本日の予定は全て終了いたしました。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/515238?Template=document&Id=6482#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":27396,"voices":57}},{"id":"h27-20151113-10","meetingId":"h27-cm11","date":"2015年11月13日","dateIso":"2015-11-13","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"はじめに予定表の１、区議会防災訓練の実施","agenda":"はじめに予定表の１、区議会防災訓練の実施","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"形になるのですかね。それで連絡を待っているという形で、基本的によろしいか尋ねました。","respondent":"原区議会事務局長","answer":"委員ご指摘のとおり、基本的には２年前にやったものを踏襲しながら、今のところ考えているところです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"提案","question":"提案の中身も、今日もう１回訴えたいと思います。この３点の改善点を求めますとの意見を述べました。","respondent":"渡辺委員長","answer":"ただ進行上、まず１２月５日というものは、ちょっと別立てで考えさせていただければと思います。今承ったので、正副でちょっとお預かりをさせていただければという思いがあったのですが、いかがでしょうか。","id":"exchange-002"},{"speaker":"本多委員","kind":"確認","question":"この区議会防災訓練の実施につきましては、１２月５日にやりましょうという案ですから、これはやはり区議会全員でやるべきだと思うのです。そしてもう１つは、検討の場ということですから、そういう投げかけはいいと思うのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり、一致していない部分があるので、ぜひそれを経て考えさせていただきたいというのが１点です。責任を放棄している場合ではございません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"やはりそういう両面がなくて、全員集まって、ではここへ来て、皆さんどうするんですかという話ですから。議長の肝いりで立ち上がったことですから、このやり方で何ら問題ないと思うし、こういう訓練はやはりやっておくべきだというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"渡辺委員長","kind":"質問・要望","question":"ご要望のあった、重複する部分を確認の上、正副でお預かりをさせてほしいと求めました。その辺の確認だけさせてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問・要望","question":"検討する場を設けるかどうかも、何かの形ではしていく方向で考えていきたい、いただきたいと。それによって、本部の形が何がベストかというのが見えてくるのかというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"たけうち副委員長","kind":"意見","question":"今のＪ－ＡＬＥＲＴのほうは、区の防災無線が流れるということで、当然、流れる前にテストですとかと言うとは思うのですが。事前に、何か、町会長さんとか、そういう方にはお伝えされているということでいいのかとの意見を述べました。","respondent":"原区議会事務局長","answer":"中身につきましては、チャイムが鳴りまして、これはテストですというのを３階繰り返すと。チャイムが鳴りまして、こちらは品川区役所ですということで、終わっていくという、サイレンが最後に鳴って終わりというような内容です。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"本日以降に、各会派に説明にお伺いいたします。以上です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993740?Template=document&Id=5158#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":9806,"voices":33}},{"id":"h27-20151125-10","meetingId":"h27-cm11","date":"2015年11月25日","dateIso":"2015-11-25","committee":"議会運営委員会","time":"午前１０時３０分～午後 ０時０５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"議員提出議案","agenda":"議員提出議案","exchanges":[{"speaker":"沢田委員","kind":"提案","question":"このたびの第４回定例会に、品川区おもてなし条例ということで提出をさせていただきたいと考えています。これからもしっかりと後押ししていくことも目的にしていますけれども、そういった意味を込めてこの条例を提案する次第でありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"この条例案の提出についてお伺いしたいと思います。そのうえでお伺いしたいのですけれども、おもてなしの心を推進していく方法として、どのように考えていらっしゃいますか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"ある意味、シティプロモーション的な部分を込めた意味で、品川区というのはどういう区ですという意味も込めての条例化であります。それを含めて、私たちの会派の中でさまざまな議論を重ねて、そういった条文になったということでありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"ですから、ここの部分はなくていいのではないか。この点については、どうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういった方たちに強制したり、そういうつもりでこれをつくったわけではないので、そこら辺をどうかご理解をいただきたいと思っています。ほかは「とする」とかになっていると思いますけれども、少し強い思いを込めて載せさせていただいたということであります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"区民の方々には、もちろんおもてなし活動をしてほしいし、それをまた区内に広げてほしいと思っていらっしゃる方は大勢いらっしゃると思います。ですから、もしつくるのであれば、その後押しだけで十分ではないか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"区民等と、おもてなし活動の取組みをそういった形で実施していこうということで、理念ということで強く言わせていただいているということです。理念ということで、ある程度強くなっているということで、ほかの条項と区別化しているということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"渡部委員","kind":"意見","question":"今、沢田委員のほうからもありましたけれども、理念の強いものになる。その中で、品川区と限定しておりますので、区に対する誇りと愛着を持ってやっていきましょうというようなところで理念を書かせていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"あべ委員","kind":"提案","question":"こんなことが大切だという何か提案文のようなもの、どういう思いでこんなことを書いています、話をしているのは条例の条文なのです。例えば条例をつくる、あるいは予算の要望をするという形でそれを区にバックアップしてもらう、それは非常に賛成しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"そうではなくて、基本理念と責務と役割と、そこはもうはっきりと明確に分けているわけです。つくった意義とは全く違うので、その辺は、基本理念と責務と役割の区別をしっかりと理解をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"一応、その目的や主体というのは非常に限定的、抑制的にやらなければいけないであろうというようなご見解はいただいています。私ばかり話しているので申しわけないです、ほかにもご意見があれば、お願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"やはりこの一つ一つが、おもてなし活動に参加、協力する努力を求めているという中身であると思うのです。反対の立場をとったときには、条例違反となると思うのですが、この辺に関しての見解を説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"沢田委員","kind":"意見","question":"先ほども、思いであって、条例化するのはどうかというお話も、あべ委員からありましたけれども、まさにつくっている私たちはそういう思いではないと。その辺のところの話が、どうしてもそういうふうになってしまうのですけれどもとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"このままであるのだったら、とても賛成できないというか、やめるべきだという意見を今は持っております。これから委員会での議論になると思いますけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"須貝委員","kind":"意見","question":"受け入れられない方、区民や団体等もあると思いますので、今のこの文面だと賛成いたしかねます。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"たけうち副委員長","kind":"提案","question":"一つ同じような理念条例を議会で提案して、第５条ですけれども、努めるものとするという努力義務ですよね。でも実際にそれが基本理念と違うからどうなのかと、ちょっと行き過ぎかなと、私は思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"たけうち副委員長のお話は参考としては伺いますけれども、全く同一な話ではないと、私は考えております。品川区議会としてのおもてなし宣言を出していく、私は、そういったものでよろしいのではないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"沢田委員","kind":"意見","question":"やはり議会として条例をつくったということで、そういった意味で、区内外へのアピール効果は宣言よりは大きいのではないかという思いはあります。今、宣言の話をされたので、そういった意味では、そう思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"あべ委員","kind":"意見","question":"むしろあまた条例よりも、つくった一瞬ではなくて、区民の皆様方にもアピールし続ける効果は、私は、宣言のほうが高いのではないかと感じております。だから、宣言では足りなくて条例というのは、実態とはずれているのではないかと感じましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]},{"id":"topic-02","title":"区議会防災訓練の実施","agenda":"区議会防災訓練の実施","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"１２月５日までに何か検討をというのは、逆に、前回もいろいろアンケートやフィードバックなどがあったと思います。あるいは、意見交換をするような場を設けるということもあってもいいのかと思います、意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういうところからこういうものが出てくるのか、これはどういうものなのか、ご説明ほしいと求めました。","respondent":"原区議会事務局長","answer":"それぞれ通信班、情報整理班、庶務班、情報連絡班、これは、先ほどご説明させていただきました。そういった意味では、事務局が機能的に、速やかに動ける形ということで、事務局内で議論してつくったものです。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"四つの班ということですけれども、そうすると、この班は、事務局の方が何人いらして、何人ずつの対応になるのか、そこら辺のところも説明を求めました。","respondent":"原区議会事務局長","answer":"１人、４人でもいいのではないかとか、パートの中で実施していこうと想定しているです。実施した後、どんなふうに改善していったらいいかということを、あわせて今後に活かしていこうと思っているところです。","id":"exchange-022"},{"speaker":"あべ委員","kind":"確認","question":"チャートのほうで確認なのですけれども、各議員の安否情報と、幹事長・本部へ報告。４０人というか、何がここで足りないみたいな話が出てきたときに、これはさばける仕組みなのか尋ねました。","respondent":"原区議会事務局長","answer":"活動をしているのでメールはできないけれども、確認しましたということでどなたかが送っていただければ、安否は確認できる。今後については、一覧表ではなく、コピーしたものをお渡しするというような形にします。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"もう少し内容を伴ったものや質問等々、これを早く進めてほしいという依頼、一つのメールという形でやっていくのはなかなか難しいと思うのです。どう対応するかみたいなものを実際にやってみると、なかなか一つのアドレスで４０人が見るという仕組みだと、やり取りまでは難しいだろうと感じます。","respondent":"原区議会事務局長","answer":"各議員がいろいろな想定をしたものを送っていただいたという前例があったものですから、今回、そんなような流れにさせていただきました。どんな情報が欲しいのかというものを、いろいろな形で想定しながら、今後の訓練に活かしていきたいと思います。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"もう１点、事務局の方々は、何か震災があったときに、全てが品川区議会災害対策本部に参集できるのでしょうか。といいますのは、町会によっては、割り振られているとかということはないのでしょうか、全員きちんと来れるのか尋ねました。","respondent":"原区議会事務局長","answer":"手元にある議員と、事務局に戻ってきているものがありますので、一つ一つ確認していきたいと思います。災害があったときには、全員こちらの本部につくことを前提で考えていきますということを申し伝えて、今日にきているです。","id":"exchange-025"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２８年度、平成２９年度の今回の保険料のほうにかかわってくると思うのですけれども、そこの辺の議題はどうなったのか。軽減措置をなくさないように言っていただきたいと、そこら辺のところはどうなっているかについてもお聞かせいただけたらと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"本多委員","kind":"質問","question":"負担が平成２８年度、平成２９年度の保険料にどう反映するのかとか、その辺がはっきりしてくるものだと思います。言われる指摘は、それぞれ多数出ておりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993740?Template=document&Id=5160#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":29183,"voices":81}},{"id":"h27-20151130-6","meetingId":"h27-cm11","date":"2015年11月30日","dateIso":"2015-11-30","committee":"区民委員会","time":"午前１０時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を93件整理しています。","topics":[{"id":"topic-01","title":"第８７号議案、品川区立区民活動交流施設条例の一部を改正する条例","agenda":"第８７号議案、品川区立区民活動交流施設条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"こみゅにてぃぷらざ八潮ができた、あるいは八潮南中学校の校庭も含まれるのか、ちょっとその辺を教えていただきたいのが一つです。ちょっと教育委員会ではないのであれなのですけれども、関係があるから聞いておられると思うので、その辺についてまず教えてほしいと求めました。","respondent":"間部文化観光課長","answer":"当時教育委員会のほうでも、まだどのような利用が見込めるか見えていなかったということがあったようです。５年間経過いたしまして、一体的に管理するのが望ましいだろうということで、今回３月１日よりこのような形で運営を始めるというものです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"せっかくとってある教育の施設ですから。それはそれとして伺うのですけれども、もう一つは、区役所に行って申込みをしなくてはだめだったという理解か尋ねました。","respondent":"間部文化観光課長","answer":"今はスポーツ推進課になってありますが、去年までは文化スポーツ振興課ということで１つの課でありましたので、そういう形での受付になっていたです。当日利用した後、非常に利用者にとっては好ましい形になりますので…","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、ちょっと私、確認ができなかったのですけれども、区役所の窓口に来ないと申請ができなかったということですか。だから、そういう点についてどうなのかというところを改めて伺いたいと思います。","respondent":"間部文化観光課長","answer":"少年少女団体ということで、ほとんど８割方が免除での利用ということで、利用料金をお支払いいただく方というのはかなり少数になってあります。そういった観点では、今までどおり今回も行うものですので、今のところ設備の拡充等は現在では考えていないです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"ほかの２割というのはどういう団体なのか、免除しない理由というのはどういうところにあるのかがちょっと知りたいので教えてほしいと求めました。そこも答弁がなかったのでお願いします。","respondent":"池田スポーツ推進課長","answer":"利用料のことですけれども、ほとんどの方が少年少女スポーツ団体ということでご説明いたしましたけれども、今と全く変わらないということになります。〔「設備」と呼ぶ者あり〕 各団体様の備品類につきましては、施設の余裕というものがございませんので、全てを置いていただけるようなそういった設備につきましては特に考えてございません。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"もう少し詳しく教えていただきたかったのですけれども、それについて改めてお願いします。そこ、ちょっとごめんね、正確にちょっと。","respondent":"池田スポーツ推進課長","answer":"私どもが考えている備品ですけれども、サッカーなどにつきましては当然サッカーのゴール。うちのほうで用意するのは、校庭にラインを引きますので、石灰類のそういった消耗品につきましてはこちらのほうで用意しています。","id":"exchange-005"},{"speaker":"南委員","kind":"確認","question":"ちょっとダブるかもしれないけれども、教育委員会としてそういうふうに教育財産の変更についてはどんな意見が出ていたのか、オーケーにしてもね。オーケーにしてもその意見というのはどのような意見だったのか、最後に確認しておきたいと思います。","respondent":"間部文化観光課長","answer":"当初、今は協定みたいな形で規則でやっていますけれども、これからやろうとする姿が理想であろうということは考えていたようです。ここ数年間は留保していたというような考え方であって、これは第２校庭という位置付けですから、私たちは最終的に判断をしたというものです。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"やっぱり教育財産というところは使われていないからということでこういうふうになっていくということはなかなかストレートに賛成しますとはなり得ま…したがって反対いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"第９５号議案、指定管理者の指定","agenda":"第９５号議案、指定管理者の指定","exchanges":[{"speaker":"南委員","kind":"質問","question":"できているのは当然ですからね、１０年、またそれ以上のお付き合いがあるわけですから。どうなのか尋ねました。","respondent":"間部文化観光課長","answer":"一番大きいのは５年後にはオリンピック・パラリンピックの実施がありまして、当然、文化プログラムというものもあります。当たり前のことを当たり前に評価した結果かもしれませんが、結果的には文化振興事業団が一番すぐれていたと、このように判断をしたものです。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことだったのかと改めて伺ったのですけれども、それは１０年間、求めているところとしては違うのではないかなとちょっと思うのですけれども。もし何かあれば、また改めて公募をしたということについてもう少し別の説明がもしあれば教えてほしいと求めました。","respondent":"間部文化観光課長","answer":"健康センターとか駐輪場だとか、どちらかというとどこでも利用者のサービスの継続性とかそういうものがない場所ですね。やはりそういう中では文化振興事業団が一番適任だろうという判断をされたです。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問・要望","question":"初めて公募されたということは、指定管理者の制度が導入された趣旨に沿う意味では評価をしたいと思います。７番の（３）のところで、それともかなり開きがあったのかとか、その辺のところでもしあれば教えていただきたいなと思います。","respondent":"間部文化観光課長","answer":"指定管理料のところですけれども、文化振興事業団が一番低額であったのですが、文化振興事業団ともう１社について１,５００万円とか２,０００万円ぐらいの差、もう１社が５,０００万円ぐらいの差がございました。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。その上で１番、２番とか当然過去の実績が物を言う部分も含めて、妥当な選定かなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"そこをはっきりさせていただきたいのと、今伺っていると、また指定管理者が５年後には変わる可能性というのはあるのですか。ちょっとそこをはっきり確認という意味で教えていただきたいのと、この文化振興事業団に決まって、私も思っていますみたいなのがないとね。","respondent":"間部文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘の公募の改めてのところなのですが、当然私、先ほどの説明の中で区との連携が密接だという理由を挙げて文化振興事業団と申し上げました。これ、福祉施設のようにやはりケアが継続して行われるようなもの以外については… 今回の指定管理者の選定、こちらの選定にあたってもオリンピック・パラリンピックが大きな要素ということで受け止めてあります。５番の（２）にありますとおり、選定についての審査会…","id":"exchange-012"},{"speaker":"藤原委員","kind":"確認","question":"最後に１つだけ確認なのですけれども、この選定委員会に私が出ていないのでお伺いしたいのですが、１点だけ。そこだけ確認を改めてしたいと思います。","respondent":"間部文化観光課長","answer":"選定に当たりましては、審査会、選定委員会を通じまして、我々は当然、公務員ですから全体の奉仕者として恥じることのない審査をしたと思ってあります。","id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問","question":"ただ、ただこれは当然、ただ区のほうは２つの企業のサービス面というのはある程度掌握されているわけですよね。それをどう文化振興事業団のサービス向上に、できる範囲で活かしてもらうということも、その辺の決意とか考え方をちょっと説明を求めました。","respondent":"間部文化観光課長","answer":"今当然、パラリンピックを開くに当たってそういう福祉的な対応、サービス面でそういう福祉的な面での向上という提案が多々見られたと。私どもとしましては、やはりオリンピック・パラリンピックに向けてきちんとこういう対応をやっていただこうかと考えているところです。","id":"exchange-014"},{"speaker":"たけうち委員","kind":"意見","question":"１つの例で、他社で積み上げてきたノウハウとかそういうものを、ある意味では公募することで区として感じ取ることができる。それをどう活かすかというのは、ある意味ではすごく、そういうのをぜひできる範囲でやってほしいと求めましたのでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"田中委員","kind":"提案","question":"でも、最後のサービス向上がすごい引っかかってしまうのですけれども、２社の方たちが入口で福祉サービス向上の提案をしていたと。それはぜひ本当にやってほしいなとは思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"南委員","kind":"意見","question":"一定の区のこの５年間の推移をご覧になっていて、きちんと選定をしていくという姿勢はずっと持ち続けていただかなければいけないかなと思っています。そこは正副委員長がいらっしゃるのに差し置いてというか失礼なのですけれども、僭越ですが…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"}]},{"id":"topic-03","title":"第９６号議案、指定管理者の指定","agenda":"第９６号議案、指定管理者の指定","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"だってほかに応募していないのだから、ここが評価に値しなかったら大変なことになるのですかという質問です。だから、チャンピオンが評価されなかったら……、同じ質問か、どうなってしまうのですか、運営は。","respondent":"池田スポーツ推進課長","answer":"実際に１社の応募ですけれども、１社の応募の前に、実を言いますと声をかけた事業者が何社かございました。ところが、実態を説明させていただいている中で皆さん辞退ということで、こういうふうになっております。","id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"だって、スポーツを皆さんしにくるところではないですか。まだいろいろ決まっていないところがあると思うのですけれども、啓発か尋ねました。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"今回候補者となりましたスポーツ協会につきましては、最終的に現場説明会の段階では、その数社応募された会社と実は現場で会ってあります。スポーツ協会で提案書を作成し、本当にチャンピオンということで… 今日の見どころはどういったものかというようなことをまず行き帰りのバスで子どもたちにやっていただいているようなことがあります。区といたしましては、そうした本番に向けて協働してこれからも密接にやっていきたいと考えております。","id":"exchange-019"},{"speaker":"松永委員","kind":"意見","question":"１点、言ったの」と呼ぶ者あり）品川区から声をかけた会社というのは、選んでかけているのか。どっちかというのを聞きたいなとの意見を述べました。","respondent":"池田スポーツ推進課長","answer":"公募ということでやりましたので、私どもが声をかけたのではなく、手を挙げたのほうが正しい。申し訳ございません。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"私はやはりこれに向けて、またこれからしようとしているのか、そういうところをとりわけちょっときちんと見ておきたいなと思っているのです。ですから、今までの実績がどうだったのか、改めてその点についてちょっと伺っておきたいなと思います。","respondent":"池田スポーツ推進課長","answer":"障害者の水泳教室ということも第２・４日曜日に行っておりまして、年に１回の障害者の水泳大会も実施しております。そのほかに、そういった障害者スポーツの普及ということについてもこれからの意欲を感じ取れましたので評価させていただいてあります。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"非常に障害者のためのスポーツ施設ですからいろいろな方々がおいでになって、やっぱりオリンピック・パラリンピックに向けて。したがって、その点について、そこも大きな柱に入れていただいてやっていただきたいなということをちょっと私は要望をしておきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"たけうち委員","kind":"確認","question":"１点目はこちらも文化振興事業団と同じように初めての公募だったかどうかということの確認と、それからこれで来たのが１事業者となっていますが。その確認と、わかればということで、お願いします。","respondent":"池田スポーツ推進課長","answer":"現場を見た際に、こちらの総合体育館の施設について、管理が大変難しいものがあるということでの辞退ということでありました。〔「一番最初の質問、以前」と呼ぶ者あり〕 指定管理者の公募につきましては、今回初めてです。","id":"exchange-023"},{"speaker":"たけうち委員","kind":"質問","question":"１週間毎日毎日品川のホームページを見ている人もいれば、よかったらどうぞというぐらいのことは、声かけという形でそれはやっていいのかどうか。そこを一応説明を求めました。","respondent":"池田スポーツ推進課長","answer":"来年の３月で終了するということは、来年切れるのだけれども、いつ頃そういった公募みたいなのがあるのかなという問い合わせはあります。その際に私どもとしましては、こちらに掲載するので、そちらのほうをご確認くださいということでご案内をさせていただいておりました。","id":"exchange-024"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。結果的には１事業者になってしまったということなのですけれども、思っていらっしゃるか、何かありますかとの意見を述べました。","respondent":"池田スポーツ推進課長","answer":"結果的に１業者ということで応募がございましたけれども、確かにほかの自治体での実績というのもかなりある大きな事業者がございました。今回、企画というものを改めて考えて出していただいたということで、大変評価をさせていただいているところです。","id":"exchange-025"},{"speaker":"渡部副委員長","kind":"提案","question":"１点だけちょっと確認をさせていただきたいと思うところがあります。ここの今回の指定管理というのはいわゆる運営ですとか様々な事業提案の部分だと思うのですけれども、その辺の切り分けとの意見を述べました。","respondent":"池田スポーツ推進課長","answer":"普通ですと１つの施設に維持管理、それからソフト部門とあわせて指定管理ということで考えるものが、そういった特殊性というのがあります。戸越体育館は確かに私ども独自ですけれども…","id":"exchange-026"},{"speaker":"渡部副委員長","kind":"確認","question":"その確認をさせていただきたかった。逆を言うと、（２）でやってしまっていいのかなという疑問も出てきてしまったのですけれども、その辺というのは特に問題ないのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"実を言いますと、戸越体育館だけですと維持管理というだけで指定管理の部分の大きさ的なものがないかと思います。体育館は２つございまして、それを２つ総合的にかつ一体的に管理するという意味で２つまとめての指定管理ということでの公募をさせていただきました。","id":"exchange-027"}]},{"id":"topic-04","title":"議員提出第１２号議案、品川区おもてなし条例","agenda":"議員提出第１２号議案、品川区おもてなし条例","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"そのための一助になるべく条例提案をさせていただきました。条例ゆえに誘発する、意識する施策にもつながっていくであろう、そんな思いで提案をさせていただいたのが、全てに関連する項目になりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"たけうち委員","kind":"質問・要望","question":"本来こういう形がどうなのかというのはちょっと事務局にも確認したら、第３条、また会派の中でも実はそういう意見も一定程度ありました。ぜひご審議ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"たけうち委員に伺いたいのですけれども、修正されたそのことは今の説明で出された理由もわかりましたけれども、修正するところは全体の条例の中のこの１カ所だけと考えて、これだけ出されたという認識でいいのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"自民党の提出者の委員の方に伺いたいと思っているのですけれども、前文に「来訪者に愛される区となることこそが私たちの願いであります」とあるのですけれども、これはどういうことを意味しているのか、改めて伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"渡辺委員","kind":"意見","question":"このまちに暮らす人はもとより、現在の区民はもとより来訪者に愛される、同種で考えています。やはり、もう一回訪れたくなることと住み続けたいというのが、愛される区の位置付けかなという捉え方ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"強調されているわけですからね、「こそ」というのは。だから、その辺のことを伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"渡辺委員","kind":"意見","question":"決意の方向性ですね。文脈のその前の流れから、現在の区民の方はもとよりということで、一連して最後強調したという意味合いですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことを求めての表現なのかどうかをちょっと確認したいと思います。それについて評価、どういうふうに思うか伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"渡辺委員","kind":"確認","question":"今、まず最初の文章についてなのですが、確認で一連のご指摘いただいた「こそ」の前のところはつながっているものと捉えてほしいと求めました。同じ思いです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"南委員","kind":"提案","question":"あえてなのですけれども、そういう状況のままこういうふうな提案がされたので、私的にはやはりちょっと違うのではないかなと思いました。私はこの文章を読むとそういうふうに理解できちゃうなと思って、非常にここはちょっと適切ではないなと思うのですけれども、これはどうなのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"意見","question":"これは解釈論の一つなのですが、最後「重要です」でまとめていますので、何かこれがいい悪いという表現は、ここはあえて避けています。一般論的な、やはり誇りと愛着を持つことが重要ですととどめていますので、その後に…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"それが１つと、自民党の「おもてなし」というのはどういうことをイメージしてこういうふうな「おもてなし」という表現を使っているのか。どういう意味なのかを伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"渡辺委員","kind":"意見","question":"かたく言えば第２条の（１）の定義、「誰もが心地良く過ごせるように心を込めて」という、ここはもうまさしく核心ですね。人と人との触れ合いをイメージしたことを定義していますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"そこをやはり相手に見返り、対価を求めずに、相手の心情を斟酌して様々な対応とか接遇とか協力をこちらが行うという意味だと思うのですね。それをまたご意見を伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"渡辺委員","kind":"意見","question":"各項目というよりは、全体で気をつけるべきこと、作成にあたって気をつける、まさにそこは一致していると考えています。ご指摘のとおりだからこそ、おもてなしを総論のところでくくって、そこにとどめたというのが背景ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"それから５条の、おもてなし活動を推進し、「区の魅力を発信するよう努めるものとする」と規定していますよね。この３条だけだとおっしゃったのですけれども、あえて伺うのですけれども、ちょっと質問したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"たけうち委員","kind":"質問","question":"この第５条を見ていただくと、比較的、何ていうのですかね「ならない規程」ではなくすることで。そこを整合性をどう考えているか、逆にお聞きしたいなと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"南委員","kind":"意見","question":"ちょっとそのことは今、覚えていないです、率直に言ってね。我が党の態度は、反対したのだと私は記憶しているのですけれども、違ったかな……との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"たけうち委員","kind":"質問","question":"そうですか。ちょっとわからないんだけど、調べてみなきゃね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"だけれども、ほかの人は何であんなのちゃちだよとか、色が気に食わないとかいろいろ価値に対して評価が違うのは当たり前ではないですか。そのことについて、どうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"渡辺委員","kind":"提案","question":"ここは今修正案を出していただいたように、一考というか、ここに集約されるというのが、提案者としても今感じているところです。逆に言うと、各項目のご指摘もクリアになるのかなというのが、まさしく公の議論の中で今私自身も感じているところですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"それで、精神条例ですから、その文言というのは、やはりみんなでたたいて共通の認識にしてつくるべきだと思うのです、それは大前提。それを伺いたいのと、「等」というのはどういうことを指すのか、それを説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"渡辺委員","kind":"意見","question":"そして、子どもたちというものを表記した思いですが、まさしく観光ですとかオリンピック、幅広くこれから動いていく中で１つ軸になると。懸念されるような、これまでの地域力を活かした、おもてなし精神がある前提を継承していく思いから上げるべきであろうという結論でしたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"この前、区民の方の求めている条例だということを本会議場でおっしゃられていたのですけれども、もっと福祉的な条例が求められてきています。そういった声とかも拾ってほしいなということと、あと文言の修正はやはりいろいろな意見を聞いてしてほしいということと、いろいろ思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"田中委員","kind":"意見","question":"すみません。行政はどうやって動くのかなということですねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"渡辺委員","kind":"意見","question":"先ほど押しつけるというか、自主性が尊重されるべきというのは、まさに同じ思いです。今懸念されたこと、このような公のところでの説明として受け取っていただければ間違いないものだと思いますので、ご理解ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"田中委員","kind":"質問","question":"そうであるのならば、やはり記載するべきだと思います。どうなのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"渡辺委員","kind":"意見","question":"その前にいろいろあるのですが、まずここがポイントの１つです。同趣旨のものが、この前文にもそうですし、その後の定義にも含まれているということで理解いただけないかなということが言いたかったわけですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"田中委員","kind":"意見","question":"そういう誤解が生まれてしまったら、せっかくの条例がもったいないと思うのですね。これで伝わるようにこういう表現で書こうと、これで記しておこうということが大事なのではないかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"田中委員","kind":"質問","question":"そういう表現をしてほしいのですけれども、やはりいろいろ見ていただくべきなのではないかということを思うのですが、どうでしょうか。質問です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"渡辺委員","kind":"質問","question":"特にさっきのご質問にあったようにおもてなしの定義とかを含めて、全体に関わる、各論の行動に移らないように気を付けた経緯があります。くくれるものという思いで文章表現をしたということになります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"そういうことが起こったら困るなと思っているので、そういうところはきちんと書いていただきたいです。どうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"できないわけですから、これをそういう意味ではありませんなんて、どんなに説明しても理解はできません。そこは気が付かないでこの条文をつくったのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"南委員","kind":"質問","question":"これは私の感想ですから、率直なところを申し上げたので、批判をしているつもりはないです。そういう点でこの条例については、態度も言いますけれども、賛成はできないと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"松永委員","kind":"意見","question":"１つだけ。原案第３条のところの基本理念で、第５条で区民等の役割を定め、その点について１点だけとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"渡辺委員","kind":"提案","question":"先ほどの修正案に沿うものではないかなというのを原案の提案者としても感じているところであります。ここは議論の中で修正案を出していただいたがゆえに気付けるところ、ご指摘のとおりだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"田中委員","kind":"意見","question":"もしも本当に条例にするのなら、先ほどから何度も言っていますが、自主性が尊重されるといった、そういう文言は必ず入れるべき。これを根拠に使われるようなことがあってはすごく困るので、そういうふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"たけうち委員","kind":"質問・要望","question":"どういうことを懸念されているのかちょっとわからないのと、商店の方が一生懸命頑張っているとおっしゃっている、そのとおりだと私も思っています。そこはよくご理解いただきたいと思うので、何を懸念しているのかよくわからないのだけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"田中委員","kind":"質問","question":"あ、そうです。この文化芸術・スポーツのまちづくり条例を根拠にこれを出されたではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"田中委員","kind":"質問","question":"いえいえ、話に出されたではないですか。それはちょっと行き過ぎではないですかと、区が言うものではないのではないですかという条例が出されたときに、ではおもてなし条例が出ていたのに。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"たけうち委員","kind":"質問","question":"そこは規定していないではないですか。それだけ意見として言っておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"田中委員","kind":"意見","question":"押しつけているわけではないのですよということをちゃんと明記しないと、読んだ方には絶対に伝わらないので、そこをきちんと書いてください。解釈の問題ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"渡辺委員","kind":"確認","question":"賛成していたら大前提が崩れますので、発言の信憑性がずれるかと思うので、これはご確認されたほうがよろしいかと思います。は個人の感じ方、解釈の仕方になるので、これ以上ちょっとご説明が難しいかと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"田中委員","kind":"質問","question":"私がここの「品川区には、長い年月を経ておもてなしの心が根付いています」という明記もきちんとあるわけではないですか。ただ、区民の方たちが嫌な感じに思ってしまうような条文だともったいないなということを伝えました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"南委員","kind":"質問","question":"そこはそういうふうになっているとは認めないのですか。質問です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"渡辺委員","kind":"質問","question":"もちろん条例ですからそれぞれ規定があって、縛るというものもある。それ以上でもそれ以下でもありません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"南委員","kind":"質問","question":"あなたの言っているそこも入っているのですよでは、これでは全然だめだとさっきから言っているではないですか。そういうふうにやはり田中委員は変えたらどうですかということまでおっしゃっている。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"渡辺委員","kind":"確認","question":"もう一度今の確認も含めて。これはあとは委員会の判断に委ねるものと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"田中委員","kind":"質問","question":"今「縛る」という答弁をされたのですけれども、やはり縛りつけるものでもあるのですか。お答えください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"渡辺委員","kind":"意見","question":"先ほど来ご指摘があった自主性とかを否定するものではないですし、区民に何かを具体的に拘束をするものではないというのが、この文案の説明です。ここはしっかりご理解をほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"南委員","kind":"質問","question":"修正案に対してですか。最後の表現だけ変えたことをもって賛成はできません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"南委員","kind":"意見","question":"これでは私は誤解を恐れずに言いますけれども、余りにも傲慢です。そういう条例に賛成はできませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"トータルで２億５,６００万円という、そういうことは当然領収書は出るけれども、ちょっとその点を少し確認をしたいと思います。３点目は、区民に対して説明とか意見は求めないのか、それについて３点伺います。","respondent":"久保田地域活動課長","answer":"次に、パブコメについてですけれども、この条例についてパブリックコメントをかけるという予定はございません。町会・自治会の活動を支援するための条例をつくってまいりますので、場合によっては複数回来てくれと、広く意見を聞いていっているというものです。","id":"exchange-080"},{"speaker":"南委員","kind":"質問・要望","question":"例えばなんですかね、そういうあとどれがどうというのは言えませんけれども、削るということはそういう点でできるのではないかなと思うのですが。意見を求めるということは区民にとってマイナスではないと、やはりやるべきだと思っているのですけれども、改めてどうかということです。","respondent":"久保田地域活動課長","answer":"これも１３地区全部で説明をしてきました。秋には具体案を持ってご説明に参りますので、町会の中等で議論をしていただいて、町会の中では広く意見の集約ができているのかなと考えています。","id":"exchange-081"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、やはりそこからは区を外に出して視点を持ってやっていくということが大事だと思うので、ぜひ私はパブコメまでやるべきだと。むしろ品川区の将来、それから地域の活性化、その上でパブコメは大事なことだと思っていますけれども、パブコメの位置付け、認識について伺います。","respondent":"久保田地域活動課長","answer":"パブコメの対象になってございませんので、パブリックコメントは行いませんけれども、町会・自治会の連合会のほうと協働でやっているというものです。これも広く町会・自治会の皆様にお配りをして知っていただきたいと考えていますので…","id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"平均年齢７１から７２ぐらいですかね、もう少しいっているのではないかなという印象を持ちます。これは私の要望ですから、また何かの検討の際に、ぜひ思い出していただいて、取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"渡辺委員","kind":"質問・要望","question":"おそらく課題ももれなく出ていますし、すごく要望に沿っているという前提でお聞きしたいと思います。決定的に根底がビジネスではなくてやはり任意団体ですから、ボランティアの限界もあると思うのですね、負担を極力少なくしていきたい。","respondent":"久保田地域活動課長","answer":"２回目、３回目も平成２８年度以降もやっていきたいなと考えていますので、いや。実際には、こういった仕組みも地域センターのほうに広げていきたいなと考えているところです。","id":"exchange-084"},{"speaker":"渡辺委員","kind":"意見","question":"どうしても行政は限られた人材なので受け身ですが、職責として位置付けが設けられると、あるいはやりがい度も高いのではないかと。いい仕事ができる取組みという位置付けがなされるとプラスに働くのではないかなと思うのですが、その辺をもう一度だけご答弁いただいて終わりますとの意見を述べました。","respondent":"久保田地域活動課長","answer":"そういったまずは信頼関係を築くということが大事だと思いますので、信頼関係を築いていただいて、その中で積極的に外に出ていくと。アウトリーチというのでしょうか、巡回をして地域の困りごとを一緒になって考えていけるような…","id":"exchange-085"},{"speaker":"たけうち委員","kind":"質問・要望","question":"どうしても公が、区がやることですから、どんぶり勘定的に出すわけにはいかないというのはわかっているので。今すぐ答えを求めませんので、何かやってもらいたいなと要望しますので、よろしくご検討ください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"渡部副委員長","kind":"質問","question":"このさばきというのでしょうか、一番実情を知っているわけですから、その辺どのようにお考えなのか。お母さんが、逆を言えばそれを重ねてきたことによって新たな町会役員として活動していただいているというケースもたくさんあると伺っています。","respondent":"久保田地域活動課長","answer":"そういう意味では各会長以外の役員の方々もそういった我々のやっていることに対して認識を持っているのだなということを感じているところです。どういうふうにやるか今検討していますし、そういったものでずっと未来永劫出すような形はちょっと難しいかなと思ってあります。","id":"exchange-087"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"１回来るお父さん、それをどうやって捕まえようかと身銭を切る、お酒飲んだり何かまた違うところで使うわけですから。そういう人たちがその気になってやってくれるケースというのが多いですから、そうなりますと、よろしくお願いしますと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"藤原委員","kind":"質問","question":"憲法解釈まで私は言ってしまったかもしれないのですけれども、そんな中で、町会・自治会の目的が地域コミュニティではないですか。課長のお口からも祭礼等というお話が出ているのですから、私個人は思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"久保田地域活動課長","answer":"委員お話のように、実際の場面では、神社のお祭りというのは地域コミュニティの中でも大切な役割になっているということは私どもも認識はしています。やはり慎重な対応が必要なのかとは考えているところですが…","id":"exchange-089","title":"町会・自治会支援"},{"speaker":"藤原委員","kind":"質問","question":"昔はいろいろあったのですよ、町会の中でもお祭りをやりたくない人もやりたい人も参加したい人も参加しない人もありますよ、現実。１回というか、そういう流れも出て来たのではないかなという思いがあるので、その辺についてはいかがか尋ねました。","respondent":"久保田地域活動課長","answer":"例えば、私どもも足を運んで見て直接お話も聞いていますので、そういった意味では町会のほうもいろいろご努力をされているです。いろいろな面からご協力はしていきたいと考えていますので、私ども全くばさっと切るというような考えで今取り組んでいるわけではございませんので。","id":"exchange-090"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後にしますが、課長も他地区とかどこかでそういうのがあるかもしれないではないですか、そういうふうに何か時代に合ったというか。今日要望を含めて話させていただいたので、今後とも今日から始まるみたいな考えでやっていきたいと思ってあります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"}]},{"id":"topic-06","title":"本定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","agenda":"本定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"担当課長に伺いたいのですけれども、東京さくらツーリストの件を今年の委員会が最後なので、明日でいいですから、どういう経過になってどういう形になっているというのを、明日また報告していただければ幸いですというか、報告してください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-092"},{"speaker":"藤原委員","kind":"質問","question":"どっちでも、伺いたい。やはり私は区民委員会という委員の１人として、今年最後ですから、今どういう状況でどうなっているかと報告していただければ幸いです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/878133?Template=document&Id=2738#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":65235,"voices":210}},{"id":"h27-20151130-7","meetingId":"h27-cm11","date":"2015年11月30日","dateIso":"2015-11-30","committee":"厚生委員会","time":"午前１０時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"再指定がされなかったというのですか、この部課長ですか、そういったケースというのがあるのかどうなのかというのをお伺いしたいのと。どんどん世代もかわってくると思うので、それに対応し切れるのかなんていう疑問があるので、それだけお答えください。","respondent":"大串福祉計画課長","answer":"こういったものへの対応ということでの助言、指導、こういったものは常に行っているところです。状況、こういったものにも対応していただけるようにこちらのほうでも日々対応をさせていただいているといったところです。","id":"exchange-001"},{"speaker":"横山委員","kind":"質問","question":"品川区指定管理者制度活用に係る指針を拝見させていただきました。１点目なのですけれども、5)番ですかね、なぜそういった判断をされたのかというところをもう一度詳しく教えていただけたらと思います。","respondent":"松山高齢者地域支援課長","answer":"かなり大規模であるということなので、そういったスケールメリットを活かした指定管理ということに、今回はそのようにさせていただきました。大崎の場合は、単独館でもありますし、小規模であるというところで、こちらのほうは公募して委託という方式を選択させていただきました。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問","question":"そうしますと、この資料をいただいたところになると、5)番の施設の規模というところに該当したというご説明でよろしいのでしょうか。そちらだけお願いいたします。","respondent":"松山高齢者地域支援課長","answer":"委員ご指摘の5)番のところ、こちらのほうについて適当でないと認められる場合というところです。それと、あと、平塚橋につきましては、平成２４年に既に建設のときとともに、公募のプロポーザル方式によって選定をしたという経緯があります。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"平成２７年９月１１日に福祉部長決定ということで資料等をつけていただいております。指定管理者の制度に対して、こうした資料をいただいているのだと思うのですけれども、その辺の経緯について教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"先ほど、冒頭ご説明したように、１から４の大きな基準項目を設けしています。それぞれの１にぶら下がっている(1)とか(2)、(3)といったところで、施設の種別に対応するような形での基準を設けさせていただいている。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"福祉のこの部局に関してはやはりさまざま、実情と制度の面、こちらを合わせていく必要というのが今後出てくるかと思います。ぜひその点、よろしくお願いしたいという要望で、私からは終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、労務監査を行っていくという話があったと思うのですけれども、その件がどうなったのかというところを教えてほしいと求めました。職員体制のことを伺ったのですけれども、三徳会とまだ協議中だということだったので、その協議はどうなったのかもお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長、松山高齢者地域支援課長","answer":"三徳会のほうでかなり一生懸命ＰＲをして、結果的に１２月にまた面接する方を入れると、約８割ぐらい達成しているというふうに聞いています。多方尽くしておりますので、多分… はヒヤリハット報告を活用しました予防計画、それから、緊急対応のマニュアルというのを作成するというのが予定されているところです。２点目の職員の体制についてということで、何名というのはまだあれなのですけれども…","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、指定管理の要項とか、まだ決まっていないというのはどういうことなのかお聞かせほしいと求めました。労務監査のほうは昨年から実施しているということで、今、福祉施設で言うと何カ所ぐらいやられているのか、お聞かせほしいと求めました。","respondent":"松山高齢者地域支援課長、永尾高齢者福祉課長","answer":"それから、ほかに常勤職員が２名ということで、常勤のほうは計３名。そのほか非常勤のほうを、シフトの関係がありますので、これから複数名配置する予定だです。 福祉の関係でいくと、今年度やるものが１件という予定です。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"何カ所中何カ所やられていて、しっかりサービスが低下することなく行われているのかというのを確認させてほしいと求めました。介護報酬を下げられている中で、職員の処遇が委託料を入れることによって改善されているのかどうかというところもお聞きしたいと思います。","respondent":"永尾高齢者福祉課長、松山高齢者地域支援課長","answer":"総合事業のほうも区のほうで設定をしていますけれども、それによりまして安定的な収入は確保されているというふうに認識しております。加算があるとか、そういうのはその施設の運営状況を見ながら加算をつけたりということで… ３名で職員が大丈夫なのかというご質問だと思いますが、多世代交流を考えるというような検討会を設けまして、その中で企画するような計画をしております。","id":"exchange-008"},{"speaker":"のだて委員","kind":"確認","question":"運営の状況を鑑みて加算していくということで、しっかりと職員の処遇が保たれていると認識していいのかなと思うのですが、その辺をもう一度確認です。常勤の方が入って、あとは運営している、ほかの団体の方も入ってやるということでよろしいのかという確認です。","respondent":"永尾高齢者福祉課長、松山高齢者地域支援課長","answer":"２カ月ごとの事業所連絡会等で職員との意見交換もきちんとしておりますので、それをまた区のほうで検討するような形式をとっておりますので、一定程度理解をしているところだというふうに認識しています。 多世代のこちらの検討会につきましては、事務局をこちらの法人が行うということで、それぞれこちらの施設を利用する団体の意見を調整しながら企画していくという方針です。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"提案","question":"５年で人材育成を、どうしようというのが、そこが一番育ちづらいのではないかと言われているわけではないですか。２回、３回となってくるのであれば、そういうことを含めて答弁をいただきたいとの意見を述べました。","respondent":"大串福祉計画課長","answer":"これが本当にモニタリング等々で、再指定、そういった形につながっていくものというふうには考えているところです。ただ、あるいはまた次の５年間を見据えた上で、通所者の処遇の向上につなげていただきたいということはお願いをしているといったところです。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"それから施設に対する補助と、要は、指定管理の部分と違う部分と全体の部分のお金が２つぐらいに分けて出ているわけではないですか。こういう機会ではないとそういうのを工夫してもらえそうもないから、そういうのがあればいいと思うのだけれども、それというのはどうか尋ねました。","respondent":"榎本（圭）福祉部長","answer":"その分もあわせて見える化をしていくという形の検討が今行われていますし、法人会計のほうは新しい基準に合わせてきているところです。育成を継続的にしていくという意味でいくと、いろいろと課題を検討して、進めていきたいというふうに思っています。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それに対して区としてはどういうような支援をしていくのかというあたりを伺いたいのですけれども、継続して指定管理者として選定されるというのは当然だというふうな前提でお聞きするわけなのですけれども、委託料ですとかそういうところでの考え方を教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"例えばデイでいけば、そういうことの検討も進めているということで、この先どういうふうな流れになるかということを注目していきたいと考えています。今回の報酬で確定ということではなくて、全体を見ながら見直しが必要であれば…","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"基本のベースを上げていくというところでやるべきなのに、それからあと、デイサービスに管理運営委託料というのがそれぞれ出ていますよね。やはりこれがなければ、デイサービスとしては介護報酬だけでは運営委託が難しいというところで出ているという考え方なのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"ただ、国のほうもその問題意識を持って検討していますので、その辺の動向をこれから見ていきたいというふうに考えています。修繕に対しても同じような考え方を持っていて、運営の会計上の収支とかそういうことも加味しながら相談をしているというような状況になっています。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"あまりに労働条件が低賃金で条件が悪いというところでやめざるを得ないという状況にならないためにも、ぜひ強力に国に求めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"区のほうからも８億だか１０億だったか支援をしたというところで、今後、この施設の老朽化も含めてというくだりで取り上げたことを思い出しています。５年ということで何かそこに人材育成、法人のほうから要望等、そういう意思疎通があるのかどうかというのは１点確認をさせてほしいと求めました。","respondent":"榎本（圭）福祉部長、永尾高齢者福祉課長","answer":"１点目のほうの会計基準のほうですけれども、まだそれが積み重なっていかない状況です。ただ、区立のものもあれば法人立のものもあるという形で、その中でどんなふうに区分けていくかという形です。 今の５年の指定管理についていろいろな、ご意見というか、そういうものは現在いただいておりません。区が５年ごとにやるということに対して、そういうことを考えると、やはりこの５年というのは必要かなというふうに思っているところで…","id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"これをいきなり５ページからの別紙２にするのではなくて、例えば、どういうふうにやっているのでしょうか。さまざま指定管理、現法人との意思確認も含めてずっと来て、そこら辺の再指定施設についてのスケジュール感を教えていただけますか尋ねました。","respondent":"榎本（圭）福祉部長、大串福祉計画課長","answer":"実は平成２７年度から新しい基準でというのが原則になっていますので、それはちょっと基準が違うので見られないというような状況です。今後、いろいろな規模も下がっても、そういう形で見せていきましょうという流れになっているです。 最終的な選考結果という形で、今日お示ししたような形で、委員会のほうには資料としてお出しさせていただいているといったところです。これという形でのスケジュールがというわけではないという形です。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"スケジュールのほうは、そうすると、区のほうから引き続きどうですかというふうな問いかけをされているのか、法人のほうからぜひこの次も再指定に向けて頑張りますのでという、そこら辺のスタートはどうなっているのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"全部それを提示して説明するとなると、特に継続のものについては、提示をしたところです。別のところをお願いするというような考えはありますけれども、実際のところ、そのまま継続されているということになります。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問","question":"委員会に出すのはそぐわない、そういう判断はしないということで、そういう理解でよろしいですか。部門によってまた違うのかもしれないけれども、また、何とか系施設によって違うのかもしれないですけれども。","respondent":"永尾高齢者福祉課長","answer":"点数表、どこの配点を何点にするとか、そういうことについては公開するのはいかがなものかというようなことです。今言った考え方、特徴的な工夫をしているところだとか努力をしているところとか、そういうところを挙げさせていただいているところです。","id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ちょっと質問しづらい部分もあるのですが、引き続き確認というか、ここに選定理由とあるではないですか。利用者や家族の要望の収集とか、施設を運営する側は当然やるべきことであって、こういうので締めくくるというのはどうなのかと。","respondent":"大串福祉計画課長","answer":"選定理由に関してですけれども、委員おっしゃるように、独自性、こういったところも選定委員会の中では当然評価していた部分です。そういう、他とは違うといったところ、こういったものが出るような形で表記のほうについては検討していきたいと思います。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"サービスについても、創造力をきかせたサービスをぜひ追求してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"北品川つばさの家の部分でまず質問します。世話人業務というのは、具体的にどのような業務になりますか尋ねました。","respondent":"中山障害者福祉課長","answer":"実際に利用者との直接処遇をするところになります。人によっては、促しをしたりとか、そういうような直接処遇の部分をやっているのが世話人業務になります。","id":"exchange-021"},{"speaker":"横山委員","kind":"確認","question":"世話人業務のご説明、ありがとうございました。「げんき」ということで読み取れるのですけれども、その辺、事実確認だけお願いできればと思います。","respondent":"中山障害者福祉課長","answer":"なので、「ぴゅあ・さぽーと」のほうでやっている仕事と、「げんき」でやっている仕事と、切り分けがだんだんできてきたところです。今後、こちらのほうの選定におきましては、現在やっている世話人については「社会福祉法人げんき」のほうに移行するというふうに聞いております。","id":"exchange-022"},{"speaker":"横山委員","kind":"確認","question":"もう一度確認なのですけれども、現在は、世話人業務は「ＮＰＯ法人ぴゅあ・さぽーと」が実際行っていらっしゃるということでよろしいのですよね。「ぴゅあ・さぽーと」と「げんき」のほうで引き継ぎ等が進められているという理解でよろしいか尋ねました。","respondent":"中山障害者福祉課長","answer":"「ＮＰＯ法人ぴゅあ・さぽーと」と「社会福祉法人げんき」というのは、同じ理事長のもと、体制を組んでいる法人になります。「社会福祉法人げんき」のほうが、世話人については「ぴゅあ・さぽーと」から移管をし、全面的に行っていくというふうな形になります。","id":"exchange-023"},{"speaker":"のだて委員","kind":"確認","question":"その中で、利用者が４０％入れかわるですとか、それが今年に入ってしっかり改善されているのかというところを確認したいと思います。この前、大幅に減らされたということで、運営費のほうが今年からその分上乗せになっていくのかどうかというところもお聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"特養の関係で、せんだっての説明の中で、利用者の入れかわりのお話がございました。きちんとした数字が今すぐに出てこないのですが、大体３程度だったと思いますけれども、具体的な数字については今手元に用意していない状況です。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"改めて確認させてほしいと求めました。職員の待遇、給与の問題でもしっかりとした待遇をされているのか、こういったところも確認させてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"その中での人事異動という関係で、基本的にはやはり事業の継続性から考えると、あってはならないことかなというふうに思っているところです。３対１というのが国基準ですが、品川区立の施設に関して言えば…","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"「げんき」に指定管理者を指名するというところで、もう一度確認なのですけれども、よろしくお願いいたします。今回、「ぴゅあ・さぽーと」のほうで指定管理者にしなかったということの理由がもしわかれば、それもお聞きしたいと思います。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"所得の少ない方が、２だと入れないけれども、認知症でケアが必要という方についてどういうふうに救ってあげようかというところから始まったものです。今年度から開始しまして、約４割程度の方が受けられるようになっております。 今回、今後の事業の継続が難しいということでご連絡をいただくと同時に、「ＮＰＯ法人ぴゅあ・さぽーと」として世話人業務の委託を受けておりました。継続性、それから、今までのケアの質を担保したいというふうに思っているところです。","id":"exchange-026"},{"speaker":"のだて委員","kind":"確認","question":"今の説明のとおりだとは思うのですけれども、加えてあれば教えてほしいと求めました。認知症グループホームの４割ということでしたけれども、介護認定１から２の方の中で４割の方が対象ということでいいのか、確認です。","respondent":"中山障害者福祉課長、永尾高齢者福祉課長","answer":"都からの指導ということなのですけれども、口頭指導ということで、社会福祉法人としてグループホームの世話人業務もできるのはないかと。再委託するのではなく、そこは自前でやるような方向で今後検討してくださいというような… 説明が不十分だったかと思いますけれども、グループホームに入っている方の多くが要介護１、２の方ということです。先ほどの４割というのは、グループホーム入所者のうちの４割です。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問","question":"今お話を伺っていると、それで、指定管理者候補は今までこういういろいろな利用者の状況を把握した世話人業務なんてやっていないということなのです。そこら辺の身分のあり方を説明を求めました。","respondent":"中山障害者福祉課長","answer":"ここの表現は、こういうつばさの家において「げんき」がやっているかのように書かれているというところでは、訂正をさせていただければと思います。申しわけありませんでした。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"法人をかわるということなわけだから、そこら辺は物事を分けていただきたいというのは、これは要望だけしておきます。それが特区ではないとか都のあれでやれるとか補助金の問題とかいろいろあるかもしれないけれども、そういういろいろ考え方があるわけではないか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"それで、それぞれ利点があるので、全部多床室だとか全部個室とか、そういう考え方はあまりいいことではないかなというふうに思っています。そうであれば、個人個人を大切にしたケアをしていくという三徳会の考え方については…","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問","question":"それはそういうふうになっているからなのだけれども、そうすると、区もそれはメリットと思っているのですかということを聞いているわけ。すると、両方賛否ありながらやっているにもかかわらず、ここでメリットと書いてあることはメリットと思っているのかということを聞きたいだけ。","respondent":"永尾高齢者福祉課長","answer":"住み慣れた地域で家族のような生活を引き続き行うというような考え方になると思いますけれども、嗜好を見ながらというやり方になるかと思います。ご家族のご希望、そういうことによって選択できるような施設の整備というのは大事かなというふうに思っております。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"改めて職員体制が管理運営と世話人業務でそれぞれ何人の職員体制なのかということを１つ教えていただきたいのと、資料を新規という形でつくっていただきたいということで、要望もさせてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"それから、いただきました、新規の説明であればそういった資料をです。申しわけありません、次回以降、十分に注意して、経過を含め、わかるような形で提出させていただければと考えています。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"人はかわらずに、「ぴゅあ・さぽーと」の人が「社会福祉法人げんき」の配属というか、そこが変わるというふうなことで捉えていいのか。職員の待遇とか、そういうのは変わるのかどうか、そこの点についても説明を求めました。","respondent":"中山障害者福祉課長","answer":"身分ですが、「ぴゅあ・さぽーと」のほうから「げんき」のほうの職員ということで切りかえを行います。支援員であるとか、「社会福祉法人げんき」のほうの世話人業務と同等のものですので、賃金その他が変わることはないというふうに聞いております。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今までできてきた大部屋がたくさんあるわけですから、杜松は小規模ですから、ぜひ頑張っていただきたいという思いをしているところです。その中で出されている全室個室という形で今回行う平塚橋の特養ホームの職員体制がどうなるのかということについて、お聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"職員体制としては、管理者、生活相談員は、管理者１名、相談員が２名ということです。看護職員が常勤換算で６名、管理栄養士とか機能訓練指導員は１名ずつ、介護支援専門員が２名というような配置の予定になっております。","id":"exchange-033"},{"speaker":"若林委員","kind":"質問","question":"お聞きしておきたいと思うのですが、さっきご説明ありましたけれども、なかなか進んでいないという状況が１つ課題としてあると。施設的な部分なのですかね、２つぐらい、お願いします。","respondent":"中山障害者福祉課長","answer":"入浴等、今後はやはり最後まで地域の中で、重度化に対応していける施設にしていきたいと思ってはおります。まだまだ２０代、ご本人の一番望ましい生活支援のあり方、こういったものは一方でまた追求していければと思っているところです。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"先ほどもありましたけれども、管理委託料の基準というのですか、どういう形で決まっているのか教えてほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"こちらの管理運営委託料の主なものが、工事の関係の費用が入っておりまして、維持管理の工事費によってかなり使用料より多くなっているというのが現状です。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"工事で高くなっているということでしたけれども、工事以外のところの決定の基準、これをもうちょっと詳しく説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"指定管理業務の概要といたしましては３つありまして、管理人業務というのが主なものでございまして、管理人業務のところの費用ということです。それ以外で工事費というのは、年度ごとにかなり老朽化しているものもありますので、その年によっては大幅にかかってくるものがあるで…","id":"exchange-036"},{"speaker":"のだて委員","kind":"確認","question":"主に管理業が多いということでよろしいのかという確認なのですけれども、人数が、入居戸数が違うということで、多いところがより管理の業務にお金がかかっているということでよいのか、確認です。","respondent":"松山高齢者地域支援課長","answer":"確かに入居者数がかなり違いますので、そういった部分もありますし、一番主な、多いところは、工事の費用が一番大きいところです。","id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけど、これぐらいのことを、例えば、ここの部分については、どうしても費用がかかる部分だと思うのです。今３つぐらい挙げたこれでは、今回は今回でもうこれはいいので、ここの部分についてはよく考えてほしいという要望だけしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"実はアパートを建て替えるのに、今、除却費用がかなりたくさん出るではないですか。１３軒くらいあるのに、高齢者の方がたくさん住んでいるかどうかというのはわかるわけですから、いかがか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"今、そういったような情報がございましたので、住宅のほうの所管部門と連携をとりまして、きちんと区としても周知を図ってまいりたいと考えています。","id":"exchange-039"}]},{"id":"topic-02","title":"の専決処分の報告","agenda":"の専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この方が支払い能力があるにもかかわらず、悪質に滞納してお金を返さないということをしっかり確認しているかということと、それを訴訟するということを決定するのは誰になるのかということを確認させてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"区といたしましては、やはり払える能力についてはまず第一番に見ながら、返済の相談を受け付けているところです。この方につきましては、今回ご報告いたしましたとおり、和解で決定したというような内容になっております。","id":"exchange-040"}]},{"id":"topic-03","title":"の専決処分の報告について（報告第３４号）","agenda":"の専決処分の報告について（報告第３４号）","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"こちらも同じなのですけれども、被告のほうが支払い能力があるにもかかわらず、悪質に滞納していたということを確認されているということでよいかという確認です。","respondent":"永尾高齢者福祉課長","answer":"生活ができないぐらいまで区のほうで無理やり払ってもらうような督促はしておりません。きちんとした相談を行いながらということで、進めてきているところです。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/841532?Template=document&Id=3432#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":53186,"voices":217}},{"id":"h27-20151130-8","meetingId":"h27-cm11","date":"2015年11月30日","dateIso":"2015-11-30","committee":"建設委員会","time":"午前１０時００分～午後 １時３９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"の１、視察","agenda":"の１、視察","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"建ぺい率と、階数と、高さ何ｍかということを教えてください。開発の地区の前面にある区画道路２－２号、こちらの車両通行はどうなるのか、そちらもお伺いします。","respondent":"溝口都市開発課長","answer":"建物の高さにつきましては、今現在、計画されている建物の高さとしましては、約１４０ｍの建築物の高さを予定しているものです。委員ご質問の区画道路２－２につきましては、今、交通課が管轄しています警視庁と協議を進めているというのが今の現状です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"１４０ｍということですけれども、階数は何階なのかということが漏れていましたので、後で教えてください。なぜ今回、区画道路５号を新設といいますか、区画道路５号は何のために新設するのかお願いします。","respondent":"溝口都市開発課長","answer":"建物の階数ですが、今現在、予定しておりますのは、地上３８階を予定しているものです。２６号線に戻る、そういった形でのループ状の交通処理をさばくということを考えておりますので、計画しているものです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"私の質問と食い違っているのか、私が伺ったのは、ちょっと前に１９階建てのマンションがこの計画地の北東にできたのです。区画道路５号が、先ほどありました容積率を約５０％、建ぺい率７０％というのは幾つになるのかということを伺いたいのです。","respondent":"溝口都市開発課長","answer":"両地区のまちづくりを一体になって進めていく観点から、今回の区画道路５号ということで８ｍのエプロンを整備していくことになっております。前面が２ｍですが、基準法の中で将来的には最低４ｍに広げなければいけないという考えになりますので…","id":"exchange-003"},{"speaker":"筒井委員","kind":"質問","question":"ちなみに、このマンションの駐車場もあると思いますけれども、駐車場に入る道はどこになるのかと思いまして。おそらく駐車場へ入るための道という必要性もあるのかと思っているのですけれども、その点はいかがなのか尋ねました。","respondent":"溝口都市開発課長","answer":"区画道路５号、または付帯商業設備、そういったところの搬入・搬出のトラックもこちら側から入るような計画になっているものです。","id":"exchange-004"},{"speaker":"西本委員","kind":"意見","question":"所管が違うかもしれないので申しわけないのですが、区画道路５号、この再開発の反対側のほうはどういうふうになってくるのか。この道路を新設する反対側のほうは、今後どういうふうな形になるのか、わかる範囲で結構ですとの意見を述べました。","respondent":"溝口都市開発課長","answer":"ですから、そちらと合わせれば１６ｍの歩行者、車が通れるようなオープンスペースができる。今現在、その中で将来的には同じようにしていくのか、または一定程度の歩道状の空地を設けてまちづくりを進めていくような形になると思います。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"意見","question":"この武蔵小山パルム駅前再開発事業の計画なのですけれども、まさにこれは一体的なまちづくりに取り組んでもらいたいことが１つと、また、これも防災上の向上につながると思いますので、これからの武蔵小山の発展、開発事業に対しては、自民党としては賛成ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"一般質問でも私たちの会派で提出させていただきましたが、印象被害など、被害の拡大を押しつけることになります。反対です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"の第８４号議案 平成２７年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"の第８４号議案 平成２７年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"今回、補正で組まなくてはいけない理由があれば教えていただきたいというか、伺いたいと思います。地域の声ですとか、提案とかを取り入れられる仕組みがないとだめだと思うのですけれども、そこもお伺いしますとの意見を述べました。","respondent":"和田河川下水道課長","answer":"これまで次年度からこの詳細設計を実施する予定でございましたが、前倒しで設計を開始するために予算を計上させていただいたものです。これについても需要等調査委託を今後も続けていく予定でございまして、その中でにぎわい創出手法の検討だとか…","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"誰でもトイレにすべきだと思うのですが、そこの考えはどうですかということが１つ、伺います。それと、実際にどういうような感じで防災のときに使用する考えをお持ちなのか、具体的にお伺いしたいと思います。","respondent":"和田河川下水道課長","answer":"どのようなトイレを設置していくかにつきましては、今後、調整していきたいというふうに考えてあります。ＦＥＭ解析という特殊な方式で検討することも視野に入れながら考えていかなければならないということが検討項目としてわかってまいりましたので。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"新設する場合は誰でもトイレというふうなことも伺っているのですけれども、もし所管の課長のお考えがあれば、ぜひお伺いしたいということが１つです。もう少し実際にどういったことを想定していて、どういう格好でやるのか、もう少しこれは防災の面からお伺いしたいと思います。","respondent":"多並公園課長、和田河川下水道課長","answer":"リバーステーションを検討していく際に、最終的には今の検討をしているところがありますので、残ったスペースも考えながら総合的に判断するべきことだと考えているところです。 それから運営主体ですが、まさにこの運営主体をどうするかということを今後の委託の中で検討していきたいというふうに考えてあります。委任をしていくのかということが、一番いいやり方を検討して…","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"来年度にかけて設計をして、実際の工事施工時期、それと完成時期はどのぐらいになるのかということを教えてください。それから、これを整備したところに対しての追加の工事ですが、今までやった部分とは全く別の部分に手をつけているという考え方でいいのか。","respondent":"和田河川下水道課長","answer":"予定ですが、完成は、現在の目標としましては平成３１年１２月の完成オープンを目指して工事を進めていきたいというふうに考えてあります。２番目のご質問ですが、大崎橋の広場の形態のことでよろしいでしょうか。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"意見","question":"最初にある程度わかっていたのではないのかというところが聞きたかったのです。そうしたら、なぜ最初からそっちへ行かなかったのかということが、そこの感覚なのだけれどもとの意見を述べました。","respondent":"和田河川下水道課長","answer":"それから東急の既設構造物に影響が考えられる範囲に及んできたということでございまして、今回わかったということで、前倒しで詳細設計を始めすることになりました。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、最後にお話があったけれども、最初の設計がなぜというのは、そこにちょっと疑問を感じたので、これから活用してもらうためには、いいものにしていただきたいのですけれども、最初の段階の設計というのは、あくまでもまたこれも考えてもらいたいということを一言言わせてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"}]},{"id":"topic-03","title":"専決処分の報告について（報告第３５号）","agenda":"専決処分の報告について（報告第３５号）","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"時期は報告で１個前の段階だけれども、たしか９月の委員会で報告があったときには、そこがちょっと気になったのでとの意見を述べました。","respondent":"小林品川区清掃事務所長","answer":"ちょうど時期が５月の連休明けの同じ週で、同じようなコースで、似たような事故を起こしてしまった１つの要因であろうというふうに思っております。その後の対応として、十分状況を承知した者と、日々人がかわっても作業チームが組めるように変更するなどの対策をとったところで…","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。物損事故で人も絡んでいないというお話で、やはり今後も気をつけていただきたいとお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"お伺いしたいのは、ここ３年ぐらいの年間件数の推移などがもしあれば伺えればと思っているのですけれども、いかがか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"今年度はまだ四月残しておりますけれども、４月から現時点までで１３件という状況です。平成２５年度の資料は、数字はちょっと今、ほぼ平成２６年と同じ２０件強というところであったと記憶しています。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"２７日の本多健信議員の「駅舎等のセーフティー化について」の質問がありましたけれども、駅のホームドア整備推進という質問でした。区からも東急に要請していただきたいと考えているのですが、品川区の考えと取り組みの現状について伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/557041?Template=document&Id=4156#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":13788,"voices":65}},{"id":"h27-20151130-9","meetingId":"h27-cm11","date":"2015年11月30日","dateIso":"2015-11-30","committee":"文教委員会","time":"午前１０時００分～午後 ５時５７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を136件整理しています。","topics":[{"id":"topic-01","title":"本日の議案審査の進め方","agenda":"本日の議案審査の進め方","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"この１００分の８０が１００分の９０にという改定がどういう意味をしているのか、数字で申しわけないのですけれども、教えていただきたい。条例の付則のところに書いてある切替日とはどういう中身なのか、意味を説明を求めました。","respondent":"渋谷指導課長","answer":"確認なのですけれども、１点目の１００分の何とかというのは、どこに書いてあるのですか。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"切替日とはどういう意味。文言がわからないので説明を求めました。","respondent":"渋谷指導課長","answer":"切替日については、施行日の前日までの間における異動者の号給ということで、条例の施行される日にちが平成２７年４月１日からになるという日程です。それから、１００分の９０というのは、給与月額に１００分の９０を掛けた額が限度額になっているというものを定めた比率です。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"今回は勤勉手当で０.１月を支給するということで、その時々によって、期末手当ではなくて勤勉手当になることの影響はあるのですか。大もとのところで申しわけないのですが。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問","question":"私も到底自分では言えないと思うのですけれども、総額の幼稚園教育職員の給与、また学校教育職員の給与が全体でそれぞれどのくらい上がるのか。全体でそれぞれを教えてほしいと求めました。","respondent":"渋谷指導課長","answer":"これは、１人当たりということでよろしいでしょうか。全体。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"これは、毎年のように改正されていると思うのですけれども、大体２００万円から３００万円近く毎年上がっていくというイメージなのでしょうか。これは教員の数にもよると思うのですけれども、総じてどのような流れに毎年なっているのかということの概略を説明を求めました。","respondent":"渋谷指導課長","answer":"人事委員会勧告がプラスのときには、その割合に応じて、若干額の変動があるです。幼稚園の教諭で２名、固有教員でも２名が育児休業になっていて、飲み込めるという形になります。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"概略的なところをお伺いしたのですけれども、さまざま要因があって、変化はしていると思います。民間に対してどうなのかとか、そういう流れの中で、やはり適正な賃金にされていくという流れだと思いますので、その点については了解いたしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"}]},{"id":"topic-02","title":"第８８号議案、品川区立保育所条例の一部を改正する条例","agenda":"第８８号議案、品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"その点が１点です。今回、公設民営ということなのですけれども、指定管理者と委託の違いを説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"例えば、開所時間等につきましても、品川区でこれから規則で定めてまいりますが、そういう内容を定めるものです。それぞれの条例で定めて、使用許可等も含めまして、事業者に包括的に業務を委託するものです。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どうして民営なのか。この点に関して、非常に残念な思いをしているのですけれども、なぜ委託の手法をとるのかというところをお答えほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"国では多様な設置主体によりまして、待機児童対策を進めていこうという中では、私立の保育園で進めていくという方針に変わりはございません。最後、解体までする形で進めてまいりますので、そういう面では指定管理者制度にはなじまないものだと考えております。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜ品川区の直営で、そこのところをもう一回お答えいただきたいのと、開所時間のところなのです。１９時３０分というところで、ここがどういう経過でこの時間になったのかという判断を説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"新規開設については、民間事業者等の活力を得ながら進めていくという方針ですので、まずは民間事業者の活力を得る方法から検討して進めたところです。皆様午後７時半までは開設しておりますので、スムーズに移行できるということも考えて、午後７時半と考えております。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"なぜ区立でないのかというところは、「区立保育園の今後の運営について」という報告があるので、そこでじっくりとご意見を伺いたいなと思っています。大体この辺で大丈夫だろうといった判断があったのかなと思うのですけれども、もう一回、その点はいかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"これを検討するにあたりましては、お迎えが大体午後７時ぐらいまでのところでピークを迎えますので、適切な時間だと考えています。近隣に品川保育園等も午後１０時まで開園の園等もありますので、駅近だけではなく、全体の近隣の保育園とのバランスを見て決定したところです。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"大した質問ではないのですけれども、１つだけお伺いしたいことがあります。大した質問ではなくてすみませんけれども、そこら辺、どういう番号の運営になっているかというのを説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"こちらの条例の設置以降は、どんどん設置順番に付番しているわけですけれども、全部が繰り上がるような形で認識しております。ただ、最終的にそういう事例がございませんので、そのように考えております。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"やはり開園していて、その園が閉園した場合にはどうなるのかというのは、今、事例がないというお話なのでしょうか。これは要望ということでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"意見","question":"大体地域の名前がつく区立保育園はそういうところが多いと思うのですけれども、大体漢字なのですけれども、何で平仮名になったのか。誰が考えたのか、その点が疑問ですとの意見を述べました。","respondent":"今井待機児童対策担当課長","answer":"例えば、豊町にありますゆたか保育園は豊町保育園と言いませんで、平仮名で「ゆたか」となっております。わかりやすさという形も含めて、今回検討したものです。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"働いている方々の確保状況は、保育士も集まりづらいという状況のもとで、何か聞いているでしょうか。伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"全国的に、または品川区の近隣の目黒区、港区でもう既に認可保育園を開設しているというところでございました。私どもも保育士の確保については、いろいろな情報共有をしておりますけれども、現在のところスムーズに行われていると聞いております。","id":"exchange-014"},{"speaker":"伊藤副委員長","kind":"確認","question":"３つお伺いしたいのですけれども、１つは、前にお話をしていたのですが、通園の安全性の確保について。この場所で、そういう話をしてほしいという話があったのですけれども、それを夢工房はなさったのでしょうかということの確認をお願いいたします。","respondent":"今井待機児童対策担当課長","answer":"保護者への保育の説明会の中でも細かく説明していきますし、丁寧に説明をして、安全についてはご理解をいただくようにしてまいりたいと考えています。それから、地域への説明ですけれども、こちらは運営だけではなく、工事につきましても近隣の町会…","id":"exchange-015"},{"speaker":"伊藤副委員長","kind":"質問","question":"５年ということはわかっているのですけれども、急転直下にＪＲとまとまって、この場所を再開発することになる可能性もあるわけではないですか。その施設をＪＲの施設の中に入れてもらうなり、そういうアイデアを持って交渉していくべきだと思うのだけれども、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"では劇団四季のような品川区の集客施設もあることですので、駅前などの立地条件を踏まえまして、町内全体での議論になろうかと考えています。保育課としましては、在園児の皆様への周知などを含めて…","id":"exchange-016"},{"speaker":"伊藤副委員長","kind":"質問","question":"こういう条例を出してきたわけですから、ＪＲと相当協議をして、逆に言うと５年後に保育園をどうするか。せっかくあるわけですから、お願いしたいのは、最後に一言お願いいたします。","respondent":"金子子ども未来部長","answer":"ひろまち保育園が再開発の予定地内につくるということで、保護者の皆様方には周知しなければならないということで明示しているわけです。そういう意味では、今から確定的なことは申し上げにくいのですけれども、さまざまな状況を踏まえて対応していくことが必要かと考えておりま…","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認を忘れたのかもしれませんが、５年より延長する可能性や、そういうことに関してはどういう表現で夢工房とお話をなさっているのでしょうか。５年が区切りだとすると、どういった表現になっているのか、２つお願いします。","respondent":"今井待機児童対策担当課長","answer":"早めに内定の方が４月以降に向けての定期利用の更新ができるように、情報提供は早めにしていきたいと考えています。それ以外にも、そういう４カ所の駐輪場の情報自体を既に内定の段階でお示ししていくような考えでおります。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"意見","question":"延長のほうは、今後判断するという表現で契約している。先ほどの自転車のほうは、またそれはそれで交通安全のほうで自転車置き場がという話になってくるので、ぜひ連携をとっていただくようお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"園庭のことで伺いたかったのですけれども、屋外遊戯場で、近くの公園ということになってしまうのでしょうか。そういった考えはないか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"中庭が約２００m2、６０坪以上の面積を持っておりますので、こちらで泥遊び等をしていただくという形で考えております。駐車場で引き続き活用していくという考えに変わりはございません。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"なかなか難しいというお話も伺っていたのですけれども、この間、園庭という形ではされてはいないということですか。そこを伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"ＪＲ東日本、劇団四季とは運営事業者を交えて、また品川区独自でいろいろ打ち合わせをしてきたところですけれども、この園庭につきましては、特に議題としては上っておりません。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり園庭がある保育園にということで、父母の皆様からの要望が本当に多く届いているところですので、ぜひ今後も努力をしていただけたらと思うのですけれども、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"ＪＲ東日本も１,０００人以上の方があちらで勤務されている状況もありますので、その状況等を踏まえまして、ＪＲが判断されているものです。私どもとしましては、ＪＲの考え方がありますので、そちらを園庭という形で要望する考えはございません。","id":"exchange-022"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認で、３００人の子どもが災害で何かあったときに、その辺がどうなっているか教えていただきたい。例えば、ＪＲと協議もいろいろされて、劇団四季ともという中で、そういった避難についてはどういう協議をされているか説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"いろいろな災害が考えられるわけですけれども、まずはそこで待機できるように努めますとともに、事業者とまた細かく検討していきたいと考えています。現時点では、ここの地域は基本的には延焼の心配のない地域ということで、品川区としても事業者と協議をしているところです。","id":"exchange-023"}]},{"id":"topic-03","title":"第９０号議案、品川区立学校設置条例の一部を改正する条例","agenda":"第９０号議案、品川区立学校設置条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今、説明をしていただいたのですけれども、品川区としては、何がどう変わっていくのか。何か国のほうで法改正ということだというご説明があったのですけれども、品川区では具体的にどんなふうに、何がどう変わるのか伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"基本的には校名が変更になるというのは大きな変更点なのですけれども、基本的にはないものと考えております。今まで従来行われてきた小中一貫教育が、今回法的にも制度的にも明確に位置づけられたと捉えているところです。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"母校の名がなくなるということにおいて驚いたのですけれども、地域の皆様は本当に学校を大事に思って、いろいろ活動もされているのです。そういったところへの説明なり、そして声というのはどのように把握されているか尋ねました。","respondent":"品川庶務課長","answer":"１０月の上旬ぐらいに学校説明会を行ってあります。小中一貫校６校につきましては、学校説明会の中で、義務教育学校の説明もしているという状況です。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういった説明の中で、何か校名が変わってしまうということに関しての声が出ていたのかどうかというのをお答えいただきたいのと、これが法制化されて、義務教育学校になるということで、何で校名が変わっていかなければいけなくなるのかというのを教えていただきたいのです。","respondent":"品川庶務課長","answer":"声につきましては、小中一貫校、例を挙げれば日野学園につきましては、今年度で１０周年を迎えております。正式には小学校と中学校が２校あったという状況ですが、今回の法改正によりまして１校という形になりましたので、名称はなくなるです。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"確認","question":"施設分離型の学校も義務教育学校になっていくということですけれども、ここは当然そのままの名称が残る。これは変わらないということで確認します。","respondent":"品川庶務課長","answer":"施設分離型の義務教育学校ですが、今回につきましては、品川区の中で施設分離型の義務教育学校というのは設定をする予定はございません。あくまでも施設一体型の義務教育学校を６校やっていくです。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"学校名のところは「残します」と言っていたのに、ショックなのですけれども、地域の方々からも少しずつそういった声が寄せられているのです。学校の名前というのは、区の判断で残していくというふうにはできないということなのか尋ねました。","respondent":"品川庶務課長","answer":"それを今回は１校にしていくですので、残していくというのは２校の名前をそのまま１校に残すということはなかなか難しいところもあります。前の学校名を残すというのは、２校を１校にするという中で、難しいことだと考えております。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なくなりますといったことを言わないにしても、やはり私も驚いたので、そういったところでの説明をしてほしいと求めました。一貫校と一般の小・中学校を比較しての成果というものがどうあるのか伺いたいと思うのです。","respondent":"品川庶務課長、渋谷指導課長","answer":"声を聞く説明をしてほしいという提案ですが、校長先生、学校を通じまして説明会をしています。説明はしていることですので、現在のところ大きい声はございませんので、十分説明は果たしていると考えております。 小中一貫校の成果というお話でございましたが、基本的に品川区は全区で小中一貫教育を進めておりまして、特に施設一体型の一貫校が特別ずば抜けて成果があるというご説明はしていないかと考えています。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですが、声も聞かれて、教育的な効果やデメリットも本当に十分検証されて進められたものなのかというのを伺いたいのです。法制化についてです。","respondent":"渋谷指導課長","answer":"あえてその部分で十分検討したかというと、国の法制化が整ったので、そこに品川区も改めて正式に乗っかっていったという流れです。施設一体型一貫校の施設的な部分、ハード的な部分での成果等々をここで改めて検証したということではございません。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですから、先ほども言いましたけれども、教育的効果のデメリットを十分に検証されていないのではないか。それで進んでいくものだと感じるのですけれども、その辺、品川区としてはいかがか尋ねました。","respondent":"品川庶務課長","answer":"今、まさに委員がおっしゃったことで、法改正が今回なされたということで、今まで小中一貫教育を長年進めてきた品川区が、新たにこういう義務教育学校という形で学校を設定していくです。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういったところの検証がしっかりされてきたのかということを伺っているのです。お願いします。","respondent":"渋谷指導課長","answer":"義務教育の質の向上を目指して取り組んできているわけですので、そういう部分で成果があるというのが、まず１つです。さまざまな学校の形態のものを用意して、保護者、地域の皆様の選択に耐え得るような条件を整えることの１つと考えられるのではないかと考えています。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"意見","question":"生徒同士の問題等々、本当に対策の問題があって、私たちもこれを議論する中でもまとめ切れないぐらいにたくさんの課題がまだまだあるなと思うのです。そういう中で、法制化までして進めていくというメリットが私にはわからないのですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"法制化を機に、改めて教育的な効果やデメリットというのを、もっと発信していただきたいと思うのです。そういったところで、問題点と成果というものをもっと明らかにしていただきたいのですけれども、いかがか尋ねました。","respondent":"渋谷指導課長","answer":"改善を図っていくという営みを我々はしているところでありますし、これからもきちんとそういったものについては、全ての教育活動において取り組んでいきたいと考えております。","id":"exchange-034"},{"speaker":"鈴木（博）委員","kind":"質問","question":"結局、文部科学省が出した法案というのは、積極的にこれがいいから新しい概念の義務教育学校をつくるということがあまり読み取れなかったのです。この法案の中ではどこが、文部科学省が義務教育学校をつくるという積極的な意味づけを読み取ったらよろしいのか尋ねました。","respondent":"渋谷指導課長","answer":"積極的な意味づけというよりも、義務教育学校の法制化については、自治体、現場レベルでの実践が先行して、既に１０年たってきたということで、各地方自治体が主体的な意思を持ってやりたいことについて、法案としてお墨つきを与えたという解釈だと考えています。","id":"exchange-035"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、現場でやっているから、国としてそれに認可を与えるというスタンスでこの法律が出たのでしょうか。そうすると、あまり積極的な意味はないと思うのだけれども。","respondent":"渋谷指導課長","answer":"積極的な意味合いというよりも、やはり実践をしている現場にとって、よりやりやすくなるようにという意味合いで法制化したと考えています。現場の事務軽減になったり、そういうことが国の法制化によってより進んで…","id":"exchange-036"},{"speaker":"鈴木（博）委員","kind":"意見","question":"そうすると、２枚目の「４－３－２」や「５－４」などの柔軟な学年段階の区切りを設定することも可能である。ただし、これは課程の変更を意味するものではなくて、これはどういうふうに読み取ったらいいのかとの意見を述べました。","respondent":"渋谷指導課長","answer":"その部分での「６－３」の枠組みはあります。勉強の中身を考えるときに、５年生から教科担任制を取り入れたりということは、各自治体の工夫の中で自由にやっていいですという意味合いのものです。","id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"意見","question":"わかりました。「僕は日野学園だ」と言う人がいても、その名前がかなり浸透していると現場では理解している人間もいるということを一言だけつけ加えておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"浅野委員","kind":"質問","question":"検討しないかということもあると思うのですが、基本的に分離型を義務教育学校という形でやろうとした場合にどのような問題点が発動するのか。交流するにしても、離れているとやりづらいというのもあるかと思うのですけれども、そこら辺をどのようにお考えになられているか説明を求めました。","respondent":"渋谷指導課長","answer":"例えば一番大きなネックになるのは、義務教育学校になったときに、校長先生を１人にするというところが一番大きなポイントになるのだろうと。施設が離れることによって、校長１人ということで、その管理…","id":"exchange-039"},{"speaker":"浅野委員","kind":"質問","question":"ある意味では平均的というのでしょうか、品川区としての教育の考え方をしっかりと平等に伝わるような形をとっていってほしいと求めました。このような文章が出てきたということになりますと、区としての固有教員の考え方と、あとは都から来ていただいた教員の考え方というのか尋ねました。","respondent":"渋谷指導課長","answer":"小中一貫教育を進める品川区としては、免許制度については非常に大きな関心を持っているところです。今後になりますが、義務教育学校設置の暁には、例えば義務教育学校に対する公募制度の設立等々をぜひ強く求めていきたいと考えているところです。","id":"exchange-040"},{"speaker":"浅野委員","kind":"質問","question":"この中で特に左側の小学校のほうで、空欄みたいな形になっているのですけれども、この空欄はそのまま空欄で条例という形になるのですか。実際に条例となる場合にはどのような形を考えられているか説明を求めました。","respondent":"野呂瀬学務課長","answer":"今日お示しした新旧対照表では、対比させる意味で空欄にしておりますけれども、実際に条例になったときには詰めるように考えております。","id":"exchange-041"},{"speaker":"大倉委員","kind":"質問・要望","question":"今後、都のほうにも要望していくというところなのですが、どういう考え方で要望していくのかというところを教えてほしいと求めました。国や都など、いろいろなところに要望していかなければいけないと思うので、そういうところがあれば教えていただきたい。","respondent":"渋谷指導課長","answer":"方針についてなのですけれども、文部科学省としても早急にここ５年、１０年で事態が急速に解決するというものではないと捉えているようです。最後３点目の縛りについてですが、これは先ほどの説明とも重なりますが…","id":"exchange-042"},{"speaker":"大倉委員","kind":"質問","question":"今後も小中一貫教育に関しては、今の６校で進めていくという考え方に特に変わりはないのかどうか。今後の義務教育学校についての進め方、学校のあり方、進め方に変わりがないかどうか教えていただければ。","respondent":"品川庶務課長","answer":"６校でとめるという考えではなく、広げていく考えは、６校でとどまるという考えではないです。","id":"exchange-043"},{"speaker":"大倉委員","kind":"質問","question":"今後、分離型なのか、一体型なのかわかりませんが、義務教育学校というものができたことで、品川区の学校のあり方としても、もう少し動きが出てくるような考え方が今出てきたという認識でいいのか尋ねました。","respondent":"品川庶務課長","answer":"直近で何かどうこうするということではありませんが、やはり将来に向けては６校体制でいくということではなく、少し考え方が変わってくるものではないかです。","id":"exchange-044"},{"speaker":"大倉委員","kind":"質問","question":"子どもたちが主体ですから、設置についても取り組んでいってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"意見","question":"中学校が存在するという２種類の種類というか、どう言うのかわかりませんが、複数の学校制度が明らかになっていく。今後もわかる範囲で明解に言っていただけますかとの意見を述べました。","respondent":"渋谷指導課長","answer":"品川区でも、約３割弱のお子さんが何らかの私立、国公立の学校に進むという現状があります。お子様にさまざまな選択肢を用意するという１つの方向性としては、区民のニーズに合致したものではないかと考えているところであります。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"選択してもらう選択肢が多いほうがいいと考えているわけですか。もう一回、そこをお伺いしたいと思います。","respondent":"野呂瀬学務課長","answer":"当初、私が説明したときに戻りますけれども、今現在小学校が３１校あって、中学校が９校ある。今までやっていました施設一体型の小中一貫校が今回法制化に伴って義務教育学校という名前に変わるということを申し上げているところです。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"確認","question":"何で今までと違って、耳慣れない義務教育学校というものにするのかという話になってしまうのではないでしょうか。そこを確認させてください。","respondent":"品川庶務課長","answer":"それは委員おっしゃるとおりで、法律が変わったということに対して、当然小中一貫教育を進めている品川区として、先行して義務教育学校をやっていこうというスタンスです。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日の資料で出ていましたけれども、学校教育制度の多様化、弾力化の推進とは一体どういう意味なのかお伺いしたいのが１つです。特に校名について、どのような説明をしていたのか、改めてお伺いしたいと思います。","respondent":"品川庶務課長","answer":"それから、ＰＴＡのほうにも小学校ＰＴＡ連合会、中学校ＰＴＡ連合会にも集まっていただきまして、この点についても説明しています。周知についても、十分説明をしているです。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どれくらいの方とこの間、どの期間に、いつぐらいの間にどのくらいの方々にこれをお伝えしたのか。口頭なのか、文書があるのだったら、文書を示してほしいと求めましたが、いかがか尋ねました。","respondent":"品川庶務課長","answer":"再度説明申し上げますが、法改正による義務教育学校の設置です。それから、周知の点につきましては、いつですが、義務教育学校の具体的な説明会は９月下旬に行われました。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"９月の下旬から１０月の上旬まで周知、相手は先ほど述べたとおりです。私は何人ぐらいの人にお伝えしたのですか、文書なのですか、口頭なのですかと聞いていますので、きちんと答えてください。","respondent":"品川庶務課長","answer":"確かに１人１人、人数を数えているという状況ではございませんので、ある程度の説明で人数の規模はご理解していただけるかと思います。それから、その際に書面を出しまして説明を行っているという状況です。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"同じ質問ばかり繰り返すつもりはないのですが、もう一回、学校説明会というのは、対象はどういう方なのでしょうか。理解を得られないと思っているので、この点について、何か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"当時何と言っていたのかという質問を先ほどしましたけれども、「十分しています」と、本当に区民の方の理解を得られていると思うのですか。私だけではないと思いますが、いかがか尋ねました。","respondent":"品川庶務課長","answer":"法改正による義務教育学校設置ということで、周知につきましても先ほど答弁したとおり、９月下旬から１０月上旬まで説明会等を行っております。校名については、いろいろご意見はあると思いますが、今現在、慣れ親しんでいる名前で学校名はいくということで判断をしています。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺の義務教育学校の施設設備の基準、先ほど校長先生が１人になるという話は聞いたのですが、教職員の配置基準など、明確に出ているのでしょうか。私としては、その辺の基準がどうなっているのかと、区が進めている上でどういう中身でいくのかというところを説明を求めました。","respondent":"品川庶務課長","answer":"先ほど委員がおっしゃったとおり、説明の中でもありましたとおり、校長先生１人、副校長先生３人という体制。これについては具体的に出ておりますが、それ以外についてはまだまだ基準というのは、現在のところ特段出されている状況ではございません。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"提案","question":"従来のところで特例的にやっていたけれども、やってきた問題点をしっかり出して、改善していく中身でどんどん提案していくべきだと思うのです。この大規模化に対して、特に配慮を考えているところがあるのか尋ねました。","respondent":"品川庶務課長","answer":"当然用地の問題になってまいりますので、なかなか広い土地にすぐ学校をつくるという状況は品川区の中では非常に難しいところではないかと思います。そういう中でも、学校の設置基準にのっとった形でしっかりと学校建設はしておりますので、よろしくお願いいたします。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問","question":"体力的にも伸び伸びと育ってほしいというところで、校庭の格差と言ってしまっていいくらい広さにすごく違いがあると思うのです。実際に大規模でやっているのですから、そこのところの基準、よりよい基準を出していただかなくてはいけないと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問","question":"何ですか。条例審査だからこそ、中身を言っているのではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教育委員会としてはぜひ考えていっていただきたいという思いがあるので、学校の規模、学級数をどう捉えているのですか。おかしいではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"意見","question":"文部科学省も過大規模校では生徒の個性や行動を把握しづらく、問題行動が発生しやすくなることも考えられると、やはり問題点を指摘しているのです。そういった意味で、子どもたちのための基準が守られるような状況に力を尽くしていただかなければ困ると思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかお尋ねするのですが、これはおそらく品川区で現状１０年やってきて、通ったのではないかと思っています。それから、特別支援学級は、学級数や先生の配置など、そのまま現状と同じようにいくのか尋ねました。","respondent":"渋谷指導課長","answer":"「４－３－２」については、今後、そういった部分もあわせて検討していきたいと考えているところです。特別支援教育につきましては、現行のものが基本的には踏襲されていくという理解でおります。","id":"exchange-060"},{"speaker":"高橋（し）委員","kind":"提案","question":"小中一貫教育推進委員会の第２回で、平成３１年から品川区義務教育新体制の提案とあって、学習指導要領も平成３１年度は小学校が入るわけです。大きな枠の中でといいますか、考え方というか…","respondent":"渋谷指導課長","answer":"今、目指すところは品川区としては９年間の義務教育にしっかりと責任を持っていこうです。９年間、義務教育学校の制度、地域の子どもたちをしっかり育てていくような教育を執行していきたいと考えているところです。","id":"exchange-061"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、平成３１年からの体制づくりにとって重要な検討、議会も含めて議論をする機会をつくってほしいと求めました。分離型も存在しますけれども、先ほどの平成３１年からのところにつながるのかもしれませんけれども、どのようにお考えか尋ねました。","respondent":"渋谷指導課長","answer":"学校の教育活動の中での連携、総合的に子どもたちを９年間見ていく仕組みとして、品川版のコミュニティ・スクールということを考えております。中学校区という大きなまとまりで義務教育というものの９年間を考えていくような仕組みができるといいのかなと考えて…","id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"質問","question":"一般質問でもお話ししたのですが、１０月下旬あたりにいろいろ地域にも説明され、在校生や新入生にも説明されたわけですね。本会議の質問ですので、繰り返しになってはいけませんので、そこのところを感想というか、お話しして、そこまで。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"伊藤副委員長","kind":"確認","question":"義務教育学校の確認ですけれども、いろいろなところから文部科学省に届いて評価をいただいた。改めて義務教育学校になった後、では品川区がどういう教育を展開して、その２つをまずお答えください。","respondent":"渋谷指導課長","answer":"さまざまな要素を総合的に勘案して設置者が主体的に判断できるように、義務教育を行う学校の設置の制度上の選択肢を増やしてくださったということで。選択肢が増えたことによりまして…","id":"exchange-064"},{"speaker":"伊藤副委員長","kind":"確認","question":"法改正ですから、これは品川区のみならず、全国の話であるから、おそらく全国の自治体の中で、形はどうあれ一貫校を展開してきた。法律ですから、さらに前に進めていく意味の教育の価値は相当あったと思うのだけれども、その解釈を確認でもう一度だけ説明を求めました。","respondent":"渋谷指導課長","answer":"学校の団体間の接続に関する優れた取組みの普及による公教育全体の水準向上に資するというのが、国の大きな考え方だと思っているところです。私どもも、ぜひまた品川区全体の教育、９年間の義務教育というものをしっかりと見据えて取り組んでいきたいと考えています。","id":"exchange-065"},{"speaker":"伊藤副委員長","kind":"質問","question":"さまざまなことをお伺いする中で、これは非常に功績があるということで、方向性を変えてきました。教育次長でいいですかね。","respondent":"本城教育次長","answer":"今、議会からもご支援いただきながら取り組んできたところに、安定的な仕組みとしての基盤を与えてもらったのだと考えています。これを１つの契機として、教育の改善、向上に努めていきたいと考えているところです。","id":"exchange-066"},{"speaker":"伊藤副委員長","kind":"質問","question":"その場、いいものはいい、そういうことを踏まえた上で品川区の教育施策を前進していただきますようお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１０年を経過しましたが、保護者、地域からも教育的効果に疑問が出されています。検証を求めていますが、いまだ示されないままでありますので、一方的に義務教育学校への移行は認められないということで反対いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"}]},{"id":"topic-04","title":"ただいま、第９０号議案、品川区立学校設置条例の一部を改正する条例が可決されましたので、次に、(4)第９１号議案…","agenda":"ただいま、第９０号議案、品川区立学校設置条例の一部を改正する条例が可決されましたので、次に、(4)第９１号議案…","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"は免除することができる」と、「減額し」が新しく入っているのですけれども、この保育料の減免規定に減額を入れるとどういうふうになるのか。どういうふうにこれを読んだらいいのか教えてほしいのと、どういう例があるのか、具体的に教えてほしいと求めました。","respondent":"竹田保育課長","answer":"「減額し、または免除することができる」ということで、より表現を適切な表現に改めたものです。委員会が特に必要と認めたときというご質問ですが、今後、発生するものとしましては、みなし寡婦の減免等を考えているところです。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"今のところなのですが、みなし寡婦以外はないのですか。今まで減免制度にあたった例がどのような例があるのか説明を求めました。","respondent":"竹田保育課長","answer":"ほかにも保育料を減免する例としましては、災害等で損失を受けたとき、あるいは多額の医療費を支払ったとき、大きく世帯の収入が変動したとき等があります。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問","question":"件数的にどのくらいあるのですか。めったにないことか尋ねました。","respondent":"竹田保育課長","answer":"今、正確な数字は持ち合わせていないのですが、項目によって多い、少ないがあります。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"意見","question":"第８９号のところは、この辺は評価をしますけれども、先ほどと同様で義務教育学校のところの反対を理由として反対します。第９３号のほうも、多子減免制度、この辺は評価をしますけれども、同様の理由で義務教育学校の設置ということで反対いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"}]},{"id":"topic-05","title":"第９７号議案、指定管理者の指定","agenda":"第９７号議案、指定管理者の指定","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺の職員の確保のことについて、問題はないかどうか、継続、定着ができているのか、離職率など、わかったら教えてほしいと求めました。正規と非正規の職員のところでわかったら説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"母子生活支援施設につきましては、過去５年間で福栄会の各施設の人事異動と定年による退職、人員の変更等はございませんでした。短期の子育て支援センター等の職員に関しましては、途中で退職される方がいて、確保が困難で課題であるということについては認識しています。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"意見","question":"ひまわり荘のところは、定着して安定してやってくださっているということで、短期の子育て支援のところの課題というのは、どういうふうに解決されていくのかとの意見を述べました。","respondent":"伊崎子ども育成課長","answer":"今、子育て支援センターは東京都の子ども家庭支援センターとして位置づけられておりまして、その中には虐待への対応も含まれております。短期の子育て支援事業などを実施しております。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子育て支援のところで、結構虐待の予防といった、対応的になかなか難しい、あと連携が必要だというところにおいては、ぜひ根づいてやっていただきたい、蓄積していただきたいところなのですが、この職員は正規でしたか、非正規でしたか、どちらでしたか。","respondent":"伊崎子ども育成課長","answer":"子育て支援センターの虐待の対応の職員が常勤、正規です。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大事な部署であるし、これからもますます求められていくし、経験を持って、どんどん周りにも発信しながら連携強化をしていただきたいので、ぜひ続いてお仕事をしていただけるように。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"浅野委員","kind":"質問","question":"事業としては非常に多岐にわたって、難しい事業だとは思うのですけれども、ほかに候補となるような団体というのでしょうか。そういう意味では、そういうところがほとんど見つからない状況なので、今回はこちらに指定をされたのかということについて１点お伺いしたいです。","respondent":"廣田子ども家庭支援課長","answer":"職員の対応に対して丁寧で満足しているというところが母子ともに１００％を確保されていまして、９割近くの回答が得られているところから。リスクに対するさまざまな対応マニュアルについて、平成２６年度に改変を行っておりまして、そちらを評価して対応しています。","id":"exchange-077"},{"speaker":"浅野委員","kind":"意見","question":"確かに長きにわたってやられているということもありますので、取組みも大きな意義があったのかと思うので、よろしくお願いします。引き続き、そこに住まわれている方や対応される方が安全であるような仕組みで、これからも継続して頑張ってもらいたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、長い間と伺ったのですが、何年からずっとやられているのかということと、前回の指定管理の予算といいますか、今回は幾らになっているのかがわかればお伺いします。","respondent":"廣田子ども家庭支援課長","answer":"平成２７年度につきましては、１億４,８５０万円となるのですが、８割近くが人件費ということになっております。保護単価の改定に伴って、予算が変わっているという状況です。","id":"exchange-079"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"平成１４年からやっているので、ぜひそこは続けてとっているから大丈夫だというのではなくて、厳しくチェックをしてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"伊藤副委員長","kind":"意見","question":"だから、それはなかなか切れないところもあるのだけれども、今聞いていると平成１４年でしたか。さまざまな社会情勢も変わっていく中で、なぜ福栄会なのかという疑問がつくのだけれども、改めて答弁をお願いいたしますとの意見を述べました。","respondent":"廣田子ども家庭支援課長","answer":"ここ二、三年で目標を達成できるように積極的な支援が行われているというところで、継続していくことが効果があるのではないかというところです。なので、これは継続したほうがよいのではないかという判断もございまして、今回選定するところでは、このあたりを評価したところで…","id":"exchange-081"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"本来、そういうものは品川区の委員会の中で引き継ぐべきではないですか。そういう実務的な面まで見ているのですかということが、いつも疑問に思っていたのだけれども、いかがでしょう。","respondent":"金子子ども未来部長","answer":"子育て支援センターの虐待、あるいは見守りについての対応というのも、変えていくのがなかなか難しいところです。先ほど来申し上げたとおり、私どもは今回３期目の更新となりますけれども、今回については継続とするところが妥当かと判断したところです。","id":"exchange-082"},{"speaker":"伊藤副委員長","kind":"確認","question":"品川区のさまざまな部署で実務を確認して、東京都の監査を受けて初めてわかったということからすると、やはり品川区としてもっと頑張ってほしい。その体制を強化していただくようにお願いしたいのだけれども、いかがか尋ねました。","respondent":"金子子ども未来部長","answer":"そういうところで、あるいは区民と接触している中で、そういう問題点を区が初めに把握しなければいけないことだと思っています。外側から指摘をされるということはないように、内側からの、課題があれば速やかに把握できるという日常的な運営の仕方をしていきたいと考えています。","id":"exchange-083"}]},{"id":"topic-06","title":"第８４号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第８４号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ある程度平等に１人幾らぐらいといって分けられるものなのか、これを具体的にやらないと配分されないとか、何か制約があるかどうか教えてほしいです。保育力強化事業助成というのが、さまざまな取組みに充てられるということなので、さまざまの中身を教えてほしいと求めました。","respondent":"竹田保育課長","answer":"基本的には、区内の保育施設は全て該当するものと考えております。例えば一時預かり事業を実施している、アレルギー児童の対応を行っている、地域子育て支援の事業を行っているなどの項目について加算するものです。","id":"exchange-084"},{"speaker":"鈴木（博）委員","kind":"質問","question":"お金を上げれば、ほかのところも上げるし、今の保育士はドライですから、お金が高いほうにどんどん流れていってしまうから定着しないと思うのです。その辺はどういうお考えでいますか。","respondent":"竹田保育課長","answer":"高い質の保育を実施することによって、子どもたちも育てる、保育士も育てるという環境のもとで実施することによって。ぜひ品川区の保育を身につけたいとお考えの方も大勢いらっしゃいますので、まずは高い質の保育を提供することが我々の使命だと考えております。","id":"exchange-085"},{"speaker":"鈴木（博）委員","kind":"確認","question":"すばらしいお話を聞いたのだけれども、品川区の保育がそんなにすばらしいとは、確認して、それほど詳しくは知らなかったのです。品川区の保育が周りに冠たるいいところというか、売りどころ、セールスポイントはどんな点がすばらしいのか尋ねました。","respondent":"竹田保育課長","answer":"少し手前みそになりますけれども、具体的に大学の先生に監修いただきまして、『のびのび育つしながわっこ』という冊子を継続的に発行しております。ぜひ保育士の視点から見て、品川区の保育所で働きたいという保育士が増えるように、我々も努力していきたいと考えております。","id":"exchange-086"},{"speaker":"高橋（し）委員","kind":"質問","question":"キャリアアップということは、保育士の賃金をアップすることに使うわけですけれども、それが各私立保育園や認証保育所のところで、個人個人がこれだけお給料が上がったというのは、何らかの形で区はチェックができるのか尋ねました。","respondent":"竹田保育課長","answer":"このスキームにつきましては、各保育所ごとに賃金体系が違いますので、算出根拠に基づきまして、一括して保育所にお渡ししまして、その金額がどんなふうに配分されたのかということを実績報告を上げていただくことによって確認しております。","id":"exchange-087"},{"speaker":"高橋（し）委員","kind":"質問","question":"その実績報告というのは、そのお金は、今まで人件費でこれだけだったけれども、それをこれだけ増やしたという形で報告されるのか尋ねました。","respondent":"竹田保育課長","answer":"今回、補助金としてお渡しした金額の詳細についての明細をいただくものです。","id":"exchange-088"},{"speaker":"高橋（し）委員","kind":"質問","question":"それが人件費に回らないで、全体の別のところにいくということが、今のお話だとあり得ないということで認識してよろしいですか。〔「はい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"伊藤副委員長","kind":"質問","question":"今の話を聞いていて、非常にすばらしいことだと思うのですけれども、継続はできないのですか。つまりキャリアアップや上乗せのところについて、東京都の補助金は単年度だけなのか尋ねました。","respondent":"竹田保育課長","answer":"認証保育所などは、東京都の独自事業ですので、公定価格を受けない部分もあります。公定価格に限定する形で、東京都も賃金改善という形で、今回補助金が創設されたと考えております。","id":"exchange-090"},{"speaker":"伊藤副委員長","kind":"質問","question":"確かに東京都のことですから、課長ではなかなか答えにくいと思うのだけれども、現場としては、大変な中で当然喜んでいらっしゃるわけでしょう。自動的にお金が入ってくる仕組みを構築していってほしいと思うのだけれども、品川区のお考えを聞かせてください。","respondent":"竹田保育課長","answer":"６５％の方が給料が安いということを理由の１つにしているという実態があって、東京都も今回事業の創設に至ったと聞いております。保育士不足というのは続いており、今後も継続して続くと思いますので、この補助金を維持していけるように東京都にも訴えていきたいと考えておりま…","id":"exchange-091"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"さまざまな保育現場の環境を改善していくためには、ある程度安定したものをやっていっていただきたいということでお話をさせていただいています。もちろん課長が決めるとは思っていないけれども、さまざまな部署、課長会、部長会等々で指摘を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-092"}]},{"id":"topic-07","title":"平成２７年請願第２８号、品川区私立幼稚園児保護者負担教育費軽減の為の請願","agenda":"平成２７年請願第２８号、品川区私立幼稚園児保護者負担教育費軽減の為の請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この３つの補助金の出処を教えていただきたいのと、どういった率で出されているのか、わかれば教えてほしいと求めました。","respondent":"竹田保育課長","answer":"こちらはそれぞれ所得に応じて、あるいは第何子かということによりまして、補助金額が決まっているものです。入園料補助金につきましては、お一人につき１０万円を上限に補助しているものです。","id":"exchange-093"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"入園料補助金がどこからで、もう一回分けて説明していただきたいのです。入園料補助金と保護者補助金、そして就園奨励費補助金を、わかりづらかったので、もう一回、ごめんなさい。","respondent":"竹田保育課長","answer":"それから、園児保護者補助金というのが、東京都の補助金に、さらに区が上乗せしている補助金です。それから、入園料補助金は、区が単独で行っている補助金です。","id":"exchange-094"},{"speaker":"石田（ち）委員","kind":"質問","question":"幼稚園等就園奨励費補助金は、国だけで出されているということでいいですね。平成１６年度には就園奨励費補助金について増額してもらえたというところは、国が増額したということになるということでいいのか尋ねました。","respondent":"竹田保育課長","answer":"すみません。どこの部分ですか。","id":"exchange-095"},{"speaker":"石田（ち）委員","kind":"質問","question":"請願文の２段落目というのでしょうか。入園料補助金のところは区が増額したということでいいのか尋ねました。","respondent":"竹田保育課長","answer":"就園奨励費補助金につきましては、原則、国の補助金ですが、区も一定程度補助を出しているものです。園児保護者補助金については、こちらにつきましても、東京都の基準にさらに区が一定程度上乗せしている補助金です。","id":"exchange-096"},{"speaker":"石田（ち）委員","kind":"質問","question":"幼稚園等就園奨励費補助金の件は、品川区と国の補助金から交付されていますと思っていいのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"飯沼委員","kind":"質問・要望","question":"昨今のいろいろな経済的事情もあって、さらなる助成という意味では、所得制限の撤廃をということが第１点目に書かれているのです。先ほど少しおっしゃったのですが、もう一度、なぜ所得制限がここにかかっているのか教えてほしいと求めました。","respondent":"竹田保育課長","answer":"高額納税者の方も当然いらっしゃる中で、こういう補助金制度というのは、一定の所得制限が必要だと考えております。平成２６年度に拡大しまして、園児保護者の約７０％を目標に拡大したところですので、今後も適切な支援をしていきたいと考えております。","id":"exchange-098"},{"speaker":"飯沼委員","kind":"質問","question":"その方に助成をするとなると、どのくらい金額がかかるのでしょうか。わかったら説明を求めました。","respondent":"竹田保育課長","answer":"園児保護者補助金をご説明しますと、平成２６年度は区内の園児総数が３,４４０人です。すみません。","id":"exchange-099"},{"speaker":"飯沼委員","kind":"質問","question":"もう一点、ここに所得制限導入以来、公私立幼稚園における教育費負担の格差が拡大しておりますと書かれているのですけれども、公私立の教育費の負担の格差というのは、現状においてどう捉えていらっしゃるのか伺います。","respondent":"竹田保育課長","answer":"公立保育園につきましては、従来は８,０００円か、あるいは免除という体系でございました。今回、所得に応じた７段階のご負担をいただくという内容に変更いたしましたので、一律に広がっているとは認識していないところです。","id":"exchange-100"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど、予算を伺ったのは、現状、これに負担がかかっているのは幾らなのですか。どうか尋ねました。","respondent":"竹田保育課長","answer":"平成２６年度におきましては、６億４,４４９万４,６００円ということで、区の負担も増えているところです。","id":"exchange-101"},{"speaker":"飯沼委員","kind":"質問・要望","question":"少子化の問題もいろいろ言われていますし、切実な請願なので、どうしたらこの支援ができるのかというあたりを考えてほしいと求めました。お母さんたちも元気に暮らしていけて、将来に明るい展望が持てると思うので、ぜひこの辺のより一層の努力をお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-102"},{"speaker":"浅野委員","kind":"意見","question":"採択。教育関係もいろいろな事業もできるようになるし、またいろいろな取組みもできるようになると思いますので、またとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-103"},{"speaker":"大倉委員","kind":"質問・要望","question":"採択でお願いします。ぜひ図っていただきたいのと、支援をしていくことが大切だと考えますので、採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"意見","question":"保護者の方々は、この中にあるように、今さまざまな事情でご苦労されていると思います。多様な教育ということで、私立幼稚園の位置づけも重要なものだと思いますので、採択といたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"}]},{"id":"topic-08","title":"平成２７年請願第３２号、認可保育園・区立幼稚園保育料値上げとすまいるスクール有料化の中止を求める請願","agenda":"平成２７年請願第３２号、認可保育園・区立幼稚園保育料値上げとすまいるスクール有料化の中止を求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それを１０％の保育料の改定でマイナス１％になるから、そうすると、保護者負担が上がる人はいないということなのですか。そこを伺いたいと思います。","respondent":"竹田保育課長","answer":"さまざまなご家庭の形態、あるいは所得があると思いますので、上がる方、下がる方は当然いるものです。先ほども申し上げたとおり、マイナス１％と試算しておりますので、全体として利用者負担が増加するものではないと考えております。","id":"exchange-106"},{"speaker":"石田（ち）委員","kind":"質問","question":"さらに、希望する２人以上の子どもを産める状況ですかと聞くと、厳しいと。負担軽減が必要だと区も述べていることに対して、この保育料値上げとの関係をどう考えるか、伺いたいと思います。","respondent":"竹田保育課長","answer":"少子化社会に対応していくということは、大変重要な問題だと考えております。５歳児から小学３年生までに拡大し、第二子は半額、少子化社会に対応した保育料になっていると考えております。","id":"exchange-107"},{"speaker":"石田（ち）委員","kind":"質問","question":"それを保育料の１０％で補っているという仕組みというか、区の言い分というのが、本当にひどい仕組みだと思うのです。その辺の見解を改めて伺いたいと思います。","respondent":"竹田保育課長","answer":"１０年近く経過しているということで、保育料の改定は必要なものと考えておりまして、今回改定させていただきました。一方で、少子化社会に対応することも必要と考えておりまして、一方で多子減額の拡大も行ったものです。","id":"exchange-108"},{"speaker":"石田（ち）委員","kind":"質問","question":"無料だったものが何で有料になるのかというのを率直に感じるという声を寄せていただきました。何で有料になるのかというのを伺いたいのと、何に使われるのですかという疑問もすごく多いのですけれども、そこも伺いたいと思います。","respondent":"伊崎子ども育成課長","answer":"１年生から３年生までに限定して、夜６時から７時までに延長したということで、総経費ももちろん増額を見込んでおります。これは保護者会でもご説明しておりますけれども、Ｂなり、全体の事業の中でのご負担の割合を一定額にしていただくという考え方です。","id":"exchange-109"},{"speaker":"石田（ち）委員","kind":"質問","question":"保育料も上がって、そして６時までの人は３,２５０円、７時までの人は４,２５０円という大幅値上げを到底受け入れられないと私は思うのです。これだけの値上げが負担になるとは感じないのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"言いかえますと、来年度からは５５０円の、今おっしゃられている参加費というものがなくなりまして、利用料という形で月額に変わってくるです。その金額が負担となってすまいるスクールに参加できないということがないように、今減額・免除の対象を検討していますので…","id":"exchange-110"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"有料化はやめて、今までどおり子どもたちが、そして親たちも安心してすまいるスクールに通わせることのできる制度にしていくべきだと思います。改めて、私も中止を求めますけれども、いかがか尋ねました。","respondent":"伊崎子ども育成課長","answer":"学童保育との比較にならないというご指摘ですが、すまいるスクールはほかの児童クラブと放課後子ども教室の両方を一体的に実施している事業です。今回の見直し等々につきましては、既に条例でご可決いただいているところですので、来年度４月の実施に向けて準備をしています。","id":"exchange-111"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その子がどういう状況を抱えて、何を求めてそこにやってくるのかというのを、決してそういう状況ではないと職員の方がおっしゃっているのです。一人ひとりが問い合わせをすれば、どういうふうに変化するのかわかるのか尋ねました。","respondent":"竹田保育課長","answer":"在園児の方については、それぞれの施設を通じてご説明しています。施設長会等を通じまして、施設の長には私どももご説明させていただいているところです。","id":"exchange-112"},{"speaker":"飯沼委員","kind":"質問","question":"説明会みたいにして行っているのですか。保育課のほうにはどのくらいお問い合わせが具体的にあるのか説明を求めました。","respondent":"竹田保育課長","answer":"広報紙にも詳細を載せておりまして、そういったものを通しまして、保護者の方には園からご説明いただいているところです。お問い合わせの数はカウントしてございませんので、正確な数は把握しておりません。","id":"exchange-113"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子どもたちの環境がよくなるのですか、もっと環境がよくなるのですか、また保育士さんの給料が上がるのですかと。私は、これは当然な当たり前の声だと思うのですけれども、どうしてこうならないのか尋ねました。","respondent":"竹田保育課長","answer":"児童１人当たりの平均月額は２万３,５７９円です。前回の全保護者を対象とする保育料の改定から１０年以上経過していることから、今回の保育料の改定は必要不可欠なものだと認識しております。","id":"exchange-114"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それを目指してほしいし、財源がどんどんたまっていて、使えるお金があるのに使わない。十分品川区はできると思うので、私は行政のほうへはたびたび求めていますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"したがって、ある程度の負担はやむを得ないと考えて、それをどうやって過不足なく合理的に組み立て、持続可能にしていくかが問題だと思います。私たちはこの請願そのものは不採択でお願いしたいと思うのですが、それと同時に、十分な説明をするように要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-116"},{"speaker":"浅野委員","kind":"質問・要望","question":"こちらについては減免を検討しているという話をいただきましたので、来年４月からスタートできるように、今検討されていると思います。あまり時間がないとも思いますので、きちんとスタートしてほしいと求めましたので、また報告ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-117"},{"speaker":"飯沼委員","kind":"意見","question":"子育てへの経済的負担軽減、これはなくてはならないものであると思っています。安心して子どもを産み育てられる品川区にしていくためにも、応援していくという意味で採択を主張しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-118"},{"speaker":"大倉委員","kind":"質問","question":"適切な認可保育園の運営という部分においても、区からお話を伺ったところにおいては、納得できるところであります。今までもさまざま議論がされて決定されたことでありますので、今回の請願については不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"全体的な区の政策の中での整合性というところ、それは合理的な理由、あるいは応能負担といったところが理由だと思います。そしてすまいるスクールのほうは今後検討するということですので、そのあたりは確実に政策、制度として実行していただくことを要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-120"}]},{"id":"topic-09","title":"平成２７年請願第３３号、一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"平成２７年請願第３３号、一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"一人ひとりが大切にされることを求める請願なので、ぜひ皆様にもしっかり受けとめていただいて、ご発言をお願いしたいと思っています。ぜひ認可保育園をしっかりと柱に据えていくということを自治体は肝に銘じるべきだと思うのですけれども、この１点でいかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"これまでもご説明していますけれども、東京都の基準に従って設置、これは子どもの安全・安心を守る基準がきちんと担保されております。今年の平成２７年４月から国の基準に基づいて、事業については子どもの安全・安心を守るための設置基準、誤解のないようお願いいたします。","id":"exchange-121"},{"speaker":"飯沼委員","kind":"質問・要望","question":"余分な言葉をつけないでほしいと求めました。そこのところをどう捉えて、それで認可保育園と同等であるというのは間違いだと思いますけれども、そこの認識はどうなのか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"保育士も１０割、保育の１人当たりの面積を３.３m2とっているなど、または保育士の基準で運営されていると認識しております。","id":"exchange-122"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は認可を柱にしていくことが、まず大前提であると思うのですが、さまざまなところではなく、本当に認可で増設を考えてほしいと求めました。これ以上やりとりしても長くなるので終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問","question":"この間、保育所に公園アンケートをとっているということで、それは国家戦略特区でしたか。とってきているわけですので、その辺、今どんなところまで進んでいるかを伺いたいのです。","respondent":"今井待機児童対策担当課長","answer":"主要な目的は、実際に公園をどのように利用されているかを踏まえて、公園の中に保育園の設置を検討していくものです。特に、今取り上げてここが課題というところでは認識していないところです。","id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"園庭をつくってほしいという理由の中には、今後の子どもたちの一人ひとりの成長に、そういうところからも述べられていると思います。今後つくっていく認可保育園には園庭をつくっていくということを、区の姿勢として持っていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"全てが設置を義務づけるということは、一方であります待機児童解消のための新規開設の妨げにもなりますので、必置を求めることはございません。は屋内のホール等で体を動かすなどの取組みについて、また保育園とその辺は検討していきたいと考えています。","id":"exchange-125"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１１月１日号の広報しながわで、受け入れ枠の拡大を実施してきましたが、開設経費や運営経費も増大しています」と書かれているのです。そうすると、保育料の値上げをしたことで、待機児対策がぐんと進むということとして受け取っていいのかどうか確認したいのです。","respondent":"今井待機児童対策担当課長","answer":"新たな人口推計の結果が出ましたので、それを踏まえて改めて乳幼児人口、そして入園者の申込率を含めて開設をしていく形になっております。保育料の決定につきましては、保育園運営経費、待機児童に伴う新規開設が当然保育料に反映していっているものだと考えております。","id":"exchange-126"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、保育料から増設に回るお金というのは、大体何割ぐらいになっていくのでしょうか。つくっていく数で違うとは思うのですけれども、大体１園増設するのに、保育料からかかるのはどれぐらいになるのか、わかれば説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"先ほど、保育課長が答弁申しましたとおり、運営費の１５％が保護者負担です。全体の経費の中で今後検討していくものだと考えておりますので、何園つくったから幾ら上がるという単純計算ではないです。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、補助金も納めているということなのですけれども、それは本当かと思ったのですが、そういう事実があるとして、詰められているのでしょうか。新年度の認証も含めてそういうことになると思いましたが、その点はいかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"すぐ３カ月以内に立ち入った後に、１年の中でもう一回、東京都と品川区が見る形になっております。先ほどの委員のお話の中で、そのような認証保育所がございましたら、私どもは速やかに立ち入りの検査等をしていきたいと考えています。","id":"exchange-128"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"これは非常に失礼な話です。認証やその他のさまざまな保育園の方々が、やはり議会として品川区の見解を確認していただきたいと思うのですが、ご答弁をお願いいたします。","respondent":"今井待機児童対策担当課長","answer":"先ほども申しましたとおり、認可保育園、小規模保育事業、認証保育所、それぞれ大もとは保育所保育指針ですけれども、それぞれの基準、通知、要綱に基づいて、適切に子どもと安全、そして健やかな発達を保障するための保育を実践しています。","id":"exchange-129"},{"speaker":"伊藤副委員長","kind":"質問","question":"１万２,０００人の子どもたちについても品川区は責任を持っていくべきだし、何も認可保育園だけを錦の御旗にすることはないと私たちは思う。保育園や幼稚園に通っていない子どもたちに対しても、品川区としてはさまざまな保育の環境を準備していくべきと考えますが、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"３歳、４歳、５歳は何らかの幼稚園、保育園、幼児教育施設、保育施設に通っていらっしゃいます。明日ご説明します、生活支援型の事業ですとか、そういうものも含めて大きく視野を持って進めていきたいと考えております。","id":"exchange-130"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"最後に保育園をたくさんつくってほしいという３番目なのですが、これに関しては品川区も今後努力されればいいのではないかということで要望します。以上、まとめますと、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-131"},{"speaker":"浅野委員","kind":"質問","question":"待機児童の解消、このような手を活用してというのでしょうか、利用して待機児童対策をこれからも進めていってほしいと求めました。そういう観点から不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-132"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほどの他の委員の発言なのですが、人の発言を曲げて表現するような手法はやめていただきたいということを１つ言っておきます。待機児対策、命を守るために国基準、国が責任を持つ認可保育園を柱に据えてほしい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-133"},{"speaker":"大倉委員","kind":"質問・要望","question":"認可保育園だけではなくてさまざまな選択肢がある中で行っていくこともスピーディーかつ柔軟性を持ってやっていくということは非常に大切だと思いま…なかなか品川区の現状から考えると難しいという部分でありますので、そういったもろもろを含め、不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１番の認可保育園でということですが、認証保育所を誘導しているという政策は、いただいた資料からもわかります。本当に安全を確保して、広場や地域の公園に連れていって、伸び伸びとそこで遊んでもらえるように保育士の配慮を求めます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-135"}]},{"id":"topic-10","title":"その他の(2)その他を行います。 まず、今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、文教委員会にかかる項目","agenda":"その他の(2)その他を行います。 まず、今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、文教委員会にかかる項目","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"マイスクール八潮の質問で、受け皿になっているのではないかという質問の答弁で、全ての生徒の選択肢に定時制はなっているという答弁だったのです。区としては、定時制高校は存続していくべきだという立場なのかどうかを伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-136"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/184577?Template=document&Id=4870#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":88300,"voices":417}},{"id":"h27-20151130-5","meetingId":"h27-cm11","date":"2015年11月30日","dateIso":"2015-11-30","committee":"総務委員会","time":"午前１０時００分～午後 ５時０８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件整理しています。","topics":[{"id":"topic-01","title":"では、(1)の第８５号議案からの審査でありますが、会議の運営上、審査の順番を入れ替えます。 まず、(4)第１１４号議案 職員の給与に関する条例の一部を改正する…","agenda":"では、(1)の第８５号議案からの審査でありますが、会議の運営上、審査の順番を入れ替えます。 まず、(4)第１１４号議案 職員の給与に関する条例の一部を改正する…","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"まだ以前のところと比べればどうなのか、それぞれ中身によって違うかもしれませんけれども、区の評価も２点目に伺いたいと思います。管理職の４級以上と、いわゆる４級と６級と、そこを解説してほしいと求めました。","respondent":"米田人事課長","answer":"２年連続の引上げ改定ということについては、可及的速やかに実施するようにというようなところ、そちらの議論が行われたというふうに聞いております。その民間の実施状況を踏まえて…","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"ここでちょっとお聞きしたいのですが、品川区ですから、実際上がっているのでしょうか。わかる範囲で結構です。","respondent":"米田人事課長","answer":"２３区内に事業所のあります事業所規模５０人以上の事業所だったり企業の給与が、ある程度、それを踏まえて勧告をしているものです。平均０.３５％の引上げを図ったというようなことで、大きくはないですが、少し改善のほうに働いているというようなことで理解しているものです。","id":"exchange-002"},{"speaker":"須貝委員","kind":"提案","question":"そういうところの給与水準と、今回こういうふうに上がるという提案なのですが、大分かけ離れているようにすごく思うのです。その点、今、課長は全体像ということで答弁してくださいましたが、実際は、区内は私が今聞いたところとは違うのか尋ねました。","respondent":"米田人事課長","answer":"それをもとに給与水準を算出しているものですので、それについては少し上がっているということは事実だろうと思いますし、それに応じた給与の改定も必要だろうというふうに考えているものです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"我々は区民のために、いろいろ区政を司って様々な事業を展開している中で、そういうギャップがあっていいのかということはすごく感じます。そういうことを鑑みると、今回の職員の給与に関する条例改正案に対しては、我々の会派としては賛成いたしかねますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"人事委員会がこういう作業を長年やってきていて、サンプルをとる対象は変わりつつあるのか、その辺の推移みたいなところを概要を教えてください。細かいことではなくて、変化があるとかないとか、その辺のことで。","respondent":"米田人事課長","answer":"およそ１０年前になりますけれども、調査の対象とする事業所を１００人から５０人に引き下げてあります。５０人程度の人数であれば、国および東京都、各人事委員会もそういうような水準に置き替えているところです。","id":"exchange-005"},{"speaker":"本多委員","kind":"意見","question":"企業にもいろいろあると思うのですけれども、大企業から中小企業までありますけれども、やはりその辺の的確なところを見ながら人事委員会が結論を出しているものだと考えていますので、適正だと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"人件費トータルで考えたときに、例えばこの引上げということは、少し人件費に余裕が出てきたという面もあるかと思います。新規の採用については労使交渉の中ではテーマになったのか、あるいは、もしテーマに入れたとしたら、どういう方向で交渉されたのか説明を求めました。","respondent":"米田人事課長","answer":"あくまでも給与条件の確定の交渉ですので、そちらについては出ていないというふうに記憶しています。","id":"exchange-007"},{"speaker":"あくつ副委員長","kind":"質問","question":"労使交渉の妥結も経ているということで、もちろんそれは尊重するという上で、１つだけ質問です。人数が減ったとか、何かそういう高まりというものがあるのであれば、そこのところをご説明ほしいと求めました。","respondent":"米田人事課長","answer":"課題であったり、生み出していったりとか、あるいは区民の方の要求の度合いも高まっていると思います。ある程度人数を絞り込んで任用をしております関係上、品川区のみならず、特別区全体について言えているものであるというふうに考えてあります。","id":"exchange-008"}]},{"id":"topic-02","title":"に戻りまして、(1)第８５号議案 品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関す…","agenda":"に戻りまして、(1)第８５号議案 品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関す…","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今後１２月に入って年賀状シーズンになり、特段の追加の対策などは今検討されているのか、あわせて伺いたいと思います。いよいよ手続に入る条例がここから始まるというわけですから、ここもしっかりとご説明ほしいと求めました。","respondent":"仁平情報推進課長","answer":"こちらは、担当の所管部署のほうで誤配をしてしまったご家庭に謝罪に行きまして、事情を説明して、これは郵便局と一緒に謝罪に行っております。制度で予定しておりますように、こちらを電子的に処理が行えるということで、そういう面で利便性が上がっていくと考えております。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、逆にこういうマイナンバーの条例で新たに加わる手間とか書類はどういうものになってくるのか、特徴的なところを伺いたいと思います。そのお子さんの本人確認は一体どうやってやるのか、どう管理するのか、ご説明ほしいと求めました。","respondent":"仁平情報推進課長","answer":"誤配ですが、１１月に２件発生しております。例にあります児童手当関係では、特にお子さんの個人番号を管理するというような、そういう仕組みにはなっておりません。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味では、２件の誤配については改めて委員会に、経過とその後の対応も含めてご報告をしていただきたいという要望をしておきたいと思います。そういう事務も今後されてくるのか、それは全くないのか、そこを伺いたいと思います。","respondent":"中山企画部長、仁平情報推進課長","answer":"事務の説明は後ほど課長のほうから。冒頭の誤配に関する対応です。 先ほどご説明しましたように、所得情報を把握しなければいけない方の個人番号を申請書に記載していただくというような形になります。それと、転入者の方が省略できるケースですけれども…","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"もうちょっと伺いたいのが、予防接種だけなのですか、ほかにもあり得るのでしょうか。なので、大事なところになりますので、改めてこの点を伺いたいと思います。","respondent":"仁平情報推進課長","answer":"その給付自体を受けている方がお子さんということであれば、そちらの方の個人番号の記載というのは考えられる話です。申請書の内容をチェックする段階で、そちらはまた個人番号とは違った今までどおりの確認という、こういう手順になります。","id":"exchange-012"},{"speaker":"中塚委員","kind":"確認","question":"もう１つ、最終的にやっぱりマイナンバーを扱うのは職員というか人間ですから、どう徹底されているのか。あらゆる事業に広がるわけですから、全員がその研修の対象なのか、そこを確認したいと思います。","respondent":"仁平情報推進課長","answer":"このネットワーク間でのマイナンバー関係のデータのコピーはありません。特定個人情報を処理できる職員も、課であっても中で切り分けていくような仕組みをシステム的に行っていく、そういう予定になっております。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"窓口に来た本人以外の確認について「委ねられる」と聞こえたのですけれども、そういう仕組みだということをお認めになるということなのでしょうか。実際に区の職員の方の仕事量も随分増えるわけですから、しっかり検討していくべきだと思うし、改めて伺いたいと思います。","respondent":"仁平情報推進課長","answer":"そういう手順ではなくて、申請者の方に状況を確認してというのは、これは今後も変わらないというふうに考えているところです。それ以上の細かい点の手順等につきましては、各窓口のほうでも違いがありますので、省略します。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問・要望","question":"この番号の利用等に関する、税に関するものと社会保障に関するものと、あと防災に関する事務ということで、以前の自分の中では認識をしております。この６ページ以降、どうも探しても見当たらないのですけれども、そこのところはどのような位置づけになっているのか教えてほしいと求めました。","respondent":"仁平情報推進課長","answer":"防災関係につきましては法で対応する部分がございまして、例えば区も検討したのですが、要支援者名簿の作成にはどうかという検討があったのですが。緊急時は法律で生命・財産を守るための対応ということはできることになっていますので、今現在、判断しているものです。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、６ページにおいても、法定というところで、独自利用を抜いた部分が、独自利用は区独自で判断されたところだろうと、法定のところがある。今、もう一度すみませんけれども、そこのところの経緯と行政で判断をした考え方を教えてほしいと求めました。","respondent":"仁平情報推進課長","answer":"非常時の場合には、行政としては対応していくという、これは法律に基づいて対応していくということになります。要支援者関係は独自利用になるのですけれども、こちらは番号で支援者名簿づくり、本人確認を行うというそこまでの判断に至りませんでしたので。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"この内容は、これの独自利用は、今後も流れとしては検討の進捗に従って増やしていくという方向にあるのでしょうか。その場合はどのような手続き、条例改正を伴いながらということになるのか尋ねました。","respondent":"仁平情報推進課長","answer":"例えば自治体間の情報連携にとって国の定めでは足りない部分があるということであれば、必要な改正は今後とも行っていく、そういう手はずになっております。","id":"exchange-017"},{"speaker":"あべ委員","kind":"確認","question":"法の関係ないし条例の改正といったものを伴わないうちに内容が増えていくということはないという理解でよろしいでしょうか、これが１点です。例えば、申請していないとか利用していないとかという方に対しては、積極的に何か働きかけていくというような運用の変化は今後あるのか尋ねました。","respondent":"仁平情報推進課長","answer":"予定はわかりませんけれども、法に類似するような区としての単独の事業であると判断した場合には、条例を改正して運用できるようにしていくものです。１つに、そういうような仕組みも導入していくという予定になっておりますので、そちらのほうで例えば未実施の記録を。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"これはどんなことなのでしょうか。逆に言えば、選択しなければ、そのお知らせは行かないということになるのか、その辺も教えてほしいと求めました。","respondent":"仁平情報推進課長","answer":"自治体がそちらの情報サイトのほうにどういう情報連携の仕方をするかというところの詳細設計は、その辺の仕組みが導入される。その中の１つのサービスとして、プッシュ型のサービスも行うような仕組みを導入していく、そういうお話です。","id":"exchange-019"},{"speaker":"大沢委員","kind":"質問","question":"４ページの防災に関する云々で条例は、そういう文言は私には読み取れないのですけれども、これで大丈夫なのか尋ねました。","respondent":"仁平情報推進課長","answer":"第１９条に７項だけ入れてあるのですけれども、こちらの１３号に、そういう法の定めがあります。これに基づいて、緊急時には区は対応できると判断しているものです。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"では、緊急時は条例で定めるものでなくても対応ができるという、そういう法律の読み込み方でいいということですね。表示する必要がなかったのか、私は表示をしていただきたかったと思うのですけれども、いかがか尋ねました。","respondent":"仁平情報推進課長","answer":"申し訳ございません。資料は主に関係するところでという抜粋で載せさせていただきましたので、防災につきまして説明不足だったことは申し訳ございません。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけ簡単なことをお聞きしたいのですが、今回、マイナンバーカードで郵送されてきました。そして、その場合に法的罰則等はどのようになっているのか、すみません、それだけ説明を求めました。","respondent":"仁平情報推進課長","answer":"受け取り拒否で戻された通知カードですけれども、これはあるというふうに思います。ただ、実際に本人を確認する時点では、個人番号の通知カードを見せてくださいというふうに求められることになっているかと思います。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"ご質問の中に入っていたと思うのですけれども、なぜ、ご本人に間違いありませんかと。具体的にどういうミスが起きて、そのミスにどう厳しく今後の対策をとってほしいというふうに申し入れたのか伺いたいと思います。","respondent":"仁平情報推進課長","answer":"次に８軒目の方にお伺いしたときに、ここもご不在でしたので、その対応をしようかと思ったところに、７番目の方が戻ってきたのです。こう２枚重なっていたと、上下がどちらかわからないのですけれども。","id":"exchange-023"},{"speaker":"吉田委員","kind":"確認","question":"ということは、その場で本人確認を忘れてしまったという、忘れたというか、省略してしまったということで理解してよろしいか尋ねました。","respondent":"仁平情報推進課長","answer":"そういう手順になっているそうなのですが、そこにちょうどたまたま帰ってきましたので、渡したものがちょっと入り組んでしまったという。その７番目の方からは郵便局にすぐに連絡がありまして、隣の方のものですということで、開けられていなかったということです。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう１つ伺いたいのは、具体的にはその手続きのときに個人番号を記入するという、そういうことが求められるということなのでしょうか。そのときに提示は求めて、その辺について、今後の区の対応はどのようにお考えか伺いたいと思います。","respondent":"仁平情報推進課長","answer":"例えば区として調べしますけれども、ご本人確認をさせてくださいと、そういう手順になると考えているところです。例えば１月以降、こういう申請書で個人番号が必要となりますという、そういう詳細の部分を周知していくように考えているところです。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"それはどういうことかという質問と、区のほうで調べ直すというお話がありましたけれども、それがどういうことかを伺いたいと思います。忘れたから追い返すことはないというのがどういう流れなのか、区のほうで調べ直すというのはどういう流れなのか、ご説明ほしいと求めました。","respondent":"仁平情報推進課長","answer":"窓口の対応ですけれども、番号を区でわかっておりますので、こちらはシステム的には調査をして記入させてよいという形になっております。ただし、番号を使うということになりますので、本人であるかどうかを厳正に窓口では確認をしなくてはいけない、こういうことになっています。","id":"exchange-026"},{"speaker":"中塚委員","kind":"確認","question":"そのときは厳正に本人確認をするということですけれども、つまりはどうやって本人確認をされるのですか。やはりそこになりすましの要素が含まれてくるのではないかと思うのですけれども、その点を改めて伺いたいと思います。","respondent":"仁平情報推進課長","answer":"健康保険の資格のカードになりますけれども、そちらと例えば年金の証書関係とか、紙だけですと２種類の書類で本人を確認する。通知カードと例えば免許証とか、そういう確認の方法になりまして、ただ単に口頭だけで本人確認を行うという仕組みではございません。","id":"exchange-027"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"返送された１,４６０件と伺ったのですけれども、現在まで何％とか、何件届いているのかということを教えていただきたいことが１つ。その２点、先にお伺いしたいと思います。","respondent":"仁平情報推進課長、立川経理課長","answer":"それと、２点目の大日本印刷が開発した「Ki-Re-i」という証明書写真機なのですけれども、今現在、第二庁舎の３階のほうに設置をしています。そういう仕組みの写真機が、今現在、第二庁舎の３階に設置しているところです。 先週の１１月２５日に設置をしました。１２月１日からご利用できるです。","id":"exchange-028"},{"speaker":"あくつ副委員長","kind":"質問","question":"最初の質問で５６％なのですけれども、まず間に合うのかということが１つ、５６％。そういったことがあるのかどうか、１２月１日は明日からですからわからないと困るのですけれども、その辺を教えてほしいと求めました。","respondent":"立川経理課長、仁平情報推進課長","answer":"１月以降にはできるですけれども、区の窓口のほうで本人確認をしつつ、交付ができるというふうに聞いております。」と呼ぶ者あり〕 詳しいことはわからないのですけれども、当然、到着順に処理するということにはなるとは思います。 進捗を考えますと、東京都は１２月８日ぐらいには完了するのではないかというような、そういう報道があったというのは耳にしています。ただ…","id":"exchange-029"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"この質問はこれで終わりますけれども、本当は当初のとおりにできるだけ１２月中旬ということで配達を終えていただきたいことが１つと、何かあれば。","respondent":"中元広報広聴課長、中山企画部長","answer":"広報しながわでは、１２月１１日号に個人番号カード発行に関する記事を載せる予定で準備をしております。その中で今の発行機のことも載せる予定で準備をしています。 今の新しい取組みであるとか広報、そしてしっかりやっていく部分については、速やかにいろいろな方法でやっていきたいと考えております。","id":"exchange-030"},{"speaker":"あくつ副委員長","kind":"確認","question":"先ほどのご答弁、ほかの委員とのやりとりの中で、マイナポータルの話が出たのですが、これはカードがないとだめなのでしょうか。生活福祉課であるとか、税務課から情報を提供しましたというものが全部今後自分で確認できるようになるのか、そこのところを説明を求めました。","respondent":"仁平情報推進課長","answer":"行政機関間で行った履歴、これは国のネットワークシステムで履歴管理しますので、こちらが検索できる仕組みということです。課題的には、では、今後どういうふうにしていくかということで検討課題にはなっているという話になっております。","id":"exchange-031"},{"speaker":"あくつ副委員長","kind":"質問","question":"１つこれは品川区としてはこれはすばらしいことだと思うのですが、これを国としてそういう指針が出ているのかどうか。そういう指針がないのかと心配になってしまうことが１つと、人数です、もしわかるのであれば説明を求めました。","respondent":"仁平情報推進課長","answer":"ただ、区としましては、今現在もそうなのですが、登録された職員しかそれぞれのシステムを使えないという形にはしてあります。課の中に１台設置されて、それでも、それで安全管理をさらに向上させていこうということが区の取組みになっております。","id":"exchange-032"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほど、人的なところと、品川区独自のセキュリティシステムだと思うのですが、それは本当にありがたいことだと思います。最後は要望ですけれども、本当にセキュリティのことについては、漏出等々ないようにお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問・要望","question":"それで、まだ全く配達していない割合は、ある程度残っているのでしょうか。ぜひこういった数字も細かく数字を把握していただきたいと思うのですが、その状況を、配達していない方々の内訳がわかるとありがたいのですが。","respondent":"仁平情報推進課長","answer":"誠に申し訳ございませんが、郵便局の残っている、まだ未着手の通数がどのぐらいあるかまでは確認できておりませんで、申し訳ございません。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問・要望","question":"期限で区役所に戻ってきた数字１,４６０件、これは出ておりましたけれども、そういった常に動いている数字を把握してほしいと求めました。関心を持ってほしいと求めましたし、区民がどういう状態にあるかということは、ぜひリアルタイムで捕捉をしていただくようにお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"中塚委員","kind":"意見","question":"誤配が２件、あと書類や窓口の煩雑さ、情報漏えいの問題、進めるべきではないと思いますので、反対ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"生活者ネットワークも、こういう個人に番号づけをするようなことにそもそも反対であると同時に、やっぱり今の手続きを伺うと、誤配の問題もありますし、まだまだいろいろなところが詰め切れていない、その状況で進めていくというのは本当に危険だと考えていますので、反対いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]},{"id":"topic-03","title":"第８６号議案 品川区長等の退職手当に関する条例の一部を改正する条例","agenda":"第８６号議案 品川区長等の退職手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"規定の根拠が変わったということですけれども、この変更で具体的に何がどう変わるか、もう少し説明してほしいと求めました。","respondent":"米田人事課長","answer":"厚生年金に統一する観点から、もともと共済年金に係る部分の条文についてはなくなったということで、そちらについての条文の変更があったです。傷病の程度につきましては、全く同じ規定の内容ぶりですので、傷病の程度については変わっていないです。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと聞きたいのですが、ここには載っていないのですが、今、区議会議員に関しては退職金はもちろんありません。区長に関しては退職手当があるということなのですが、実際、どういうときにもらえて、幾らぐらいの額なのか説明を求めました。","respondent":"米田人事課長","answer":"それぞれの任期の満了のときに、１年当たり、例えば区長ですと１００分の４８０という比率に基づいて、在職年数ごとに、いわゆる任期の更新がありましたら一旦退職ということで、その更新ごとに支給されるものです。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"大体、例えば４年を基準とするのですか。そうすると、金額的にはどれぐらいの金額になるのか尋ねました。","respondent":"米田人事課長","answer":"この第４条は特例的な取扱いですので、第４条の前に第３条ということで一般的な取扱いということになっています。その一般的な取扱いの場合は、概ね現行の給料で計算いたしますと、約２,２００万円余ということになります。","id":"exchange-040"}]},{"id":"topic-04","title":"第９４号議案（仮称）東五反田四丁目認知症高齢者グループホーム新築工事請負契約","agenda":"第９４号議案（仮称）東五反田四丁目認知症高齢者グループホーム新築工事請負契約","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"今は現地はちょうど解体工事中であったかと思いますけれども、今後の竣工までのスケジュールについて教えてほしいと求めました。","respondent":"立川経理課長","answer":"解体につきましては今年度中でございまして、今年度、解体中に説明会を実施いたしまして、年度内の着工を予定しております。竣工につきましては、平成２９年２月末でございまして、開設は平成２９年５月を予定しています。","id":"exchange-041"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ近隣住民の方々のお声に配慮しながら進めていくということを、この落札された業者にもお願いしてほしいと求めました。どこの工事でもそうですけれども、やはり住宅地ですので、その辺を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"あくつ副委員長","kind":"質問","question":"福祉計画課長からもお話を伺ったのですが、２億４,０００万円であの土地を取得をして、利用目的としては大変すばらしいと思います。うまくいっていないとは言われないとは思いますけれども、うまくいくのかどうかという、そこら辺の工夫について説明を求めました。","respondent":"大串福祉計画課長、立川経理課長","answer":"こちらの運営事業者、指定管理者候補者予定者という形になるのですけれども、こちらは新生寿会という社会福祉法人。福祉施設の関係については、グループホームだけではなく、特別養護老人ホーム等も含めて行われているです。 設計と施工につきましては、基本的には分離して発注していますので、地域的に離れていると言いましても、当然、出張等をしてもらって、連絡を密にとっていただいて施工はしていくということで聞いているところです。","id":"exchange-043"}]},{"id":"topic-05","title":"平成２７年請願第２７号 上大崎シルバーセンターに隣接した空家の土地を品川区で取得することに関する請願","agenda":"平成２７年請願第２７号 上大崎シルバーセンターに隣接した空家の土地を品川区で取得することに関する請願","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"例えば、少しは交渉してもいいというところまでお気持ちが動いていらっしゃるということは伺ったのですが、そういう事実はあるのでしょうか。それがあると、とてもいいなと思うのですが、その辺はどうなのか尋ねました。","respondent":"柏原企画調整課長","answer":"空き家の条例をつくりまして、区がそれに今対応ということで動いてありますので、その中でアンケートをしたというところがあります。仮に考え方としますと、話がある、区に伺いがあるという状況はないです。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問","question":"本当にこれは質問なのですけれども、どういうことになるのでしょうかというか、文言が土地を取得するという結論の請願になっているわけです。その取得という文言の中に、そのことがどうなのだろうかというのが私はとても心配なのですが、どうなのか尋ねました。","respondent":"柏原企画調整課長","answer":"お答えがそのまま１００％お答えになるかどうかちょっとあれなのですけれども、こちらは今ご説明した中で、課題になっているご議論をいただいて。ただ、空き家の適正化というところは区も施策として動いているところがありますので…","id":"exchange-045"},{"speaker":"吉田委員","kind":"確認","question":"例えば、瑕疵というのは言い過ぎかもしれませんけれども、きちんとその辺のことも含んだような形にするとかということは難しいでしょうか。特に問題ないと思われるか尋ねました。","respondent":"原区議会事務局長","answer":"これは請願が採択されたから全くそのとおりにしなくてはいけないということではなく、その議会の意思を区長がどのように判断をしていくか。それを受けた後、区長がどのように判断するかというのは、議会の意思を受けてというような形になろうかというふうに考えているところです。","id":"exchange-046"},{"speaker":"本多委員","kind":"質問・要望","question":"所有者は今こういう請願が出ているとか、動きはご存じなのでしょうか、それが１つ。２つ目は、ハエが大量に発生したとか、何かその辺をつかんであれば教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"ほかの方からもお話がありましたけれども、区としては、この請願が持ち主の方に届いているかどうかということは把握はしていないというところです。環境の部門であるとか、それから衛生を所管する部門のほうには…","id":"exchange-047"},{"speaker":"大沢委員","kind":"確認","question":"そこの土木とか、権利関係に対する情報は持っていないんですよね、そのことを確認をさせてください。今、後者のほうは別の情報だと思うのですけれども、後者のほうの情報については何か持っていらっしゃるところはあるか尋ねました。","respondent":"柏原企画調整課長","answer":"ですので、どなたの所有物であるだろうというところまでは確認はとれておりまして、その方に対してアンケートということで書類をお送りしています。その方から、正式な形での回答なり連絡は、その流れの中ではいただいていないという状況です。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問・要望","question":"こういったご要望があるというのは当然この中に書いてあるわけですけれども、他の行政需要も考えながら勘案していくべきものだろうと思います。どういう形ですることがよりスムーズに、結果は交渉事ですからどちらにしろわからないにしても、ちょっと今判断しかねている。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"須貝委員","kind":"確認","question":"売却代金がどうで、それがないのに、請願で今回どうでしょうかと決めるべき次元のものではないと私は思います。本人の、売却の意思もありますということを確認してから進めなければいけないし、僕はこの委員会でも議会でも決めるべき話ではないと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"中塚委員","kind":"確認","question":"紹介議員に３党なっているので、それは任意売却ということですよねという、それを一応確認したいということ。いわゆる民民の任意売却かどうかを１点確認したいことと、もう１つは、多世代のものに使ってほしいという中身だということでよろしいのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"一応１点確認したいのですが、もちろんそういうことを全てわかった上でこの請願者は空き家ということでの利活用ということで求められていると思うのですが、これについてのご見解を伺いたいと思います。","respondent":"柏原企画調整課長","answer":"区が進めています空き家の施策のところですけれども、適正に空き家を管理するような方向に持っていくのだということが大きな趣旨のところであります。それを前提に全部動くということではありませんので、そこに関しては意向を聞いて、その中に幾つか手法があるというものです。","id":"exchange-052"},{"speaker":"あくつ副委員長","kind":"質問","question":"ですから、購入ありきとかという話ではもちろんなくて、多分、請願者の方はそれをわかった上で請願をされているということは私は感じました。先ほどの回答になればというふうに思っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"大沢委員","kind":"質問","question":"あくまでも請願なのですから、お伺いを立てたことに対して、ここはそういう意思を表明する場所だと思います。あくまでもこれは請願ですから、私有財産に行政が足を踏み入れるとか、そういうことではないと私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"吉田委員","kind":"確認","question":"議会が採択するわけですから、そこまで入ってしまうのではないかということを懸念して私は解釈とか質問をしました。ちゃんと時系列的にも相手方の意思も確認した上で、この趣旨に沿った結論が出せるかなというふうに思って、そのように申しました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"あくまで双方の合意ですから、地域の方がこういう要望がある、それも一定の合理性がある。つまりは、区に買う意思があるかどうか、ここをまず確認しないといけないなと私は思うのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"須貝委員","kind":"質問","question":"きちんとした地域活動課の人もいるのだから、いろいろ相談してやるべきではないですか。人の土地、人の不動産、所有物件に関して、こういう出し方は、私は本当に間違っていると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"大沢委員","kind":"意見","question":"それは、請願というものに対する本質的なものよりも、それは須貝委員の単独的なエゴイスティックな自己見解に満ちたものだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"本多委員","kind":"質問","question":"請願権はやっぱり大切にしたほうがいいと思うのです。それを区議会議長が受理をされて総務委員会に付託をしたわけですから、我々の使命としては、これを真剣に討議する必要があると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"町会長も区民ですから請願権はありますし、いさめたり、間違ったりというようなことではないと思います。それに対して私たちがどう受けとめるかというのが、この場かなというふうには考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"吉田委員","kind":"確認","question":"もし採択となっても、その先の相手方の基本的人権の侵害にはならないのだというふうにちゃんとここで確認がとれれば、少なくともそのときには。採択するということはそういうことです、とおっしゃっているので、そこと整合性をつけたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"それは執行機関の話であって、我々が今議論しているのは議会の話であって、この願いに沿って区に進めることを求めるのか、求めないのか。何を言っているかというと、相手の所有権に踏み込むことになるということがよくわからなかったので、もうちょっと教えていただければ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"吉田委員","kind":"確認","question":"相手方の意思の確認も何もなく、だから最初に理事者に質問したのですけれども、どの辺まで取得というもの。それが前提なのですということがちゃんと確認できれば、今後も同じような解釈がされるということが確認できれば私は構わないのですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"あべ委員","kind":"意見","question":"議会としてはつくってほしいのだというような形で採択をすることになると、こういった土地をこういうふうに使ってほしいというものに対しても。この土地をああいうふうに使ってほしいということが出てきたときに、なかなか採択以外の結果を出すことが…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"あくつ副委員長","kind":"質問","question":"請願というのは１つ１つの案件、今回もそのために視察をしたということもありますし、各自持っている情報も違うと思います。ですから、正反対な答えで申し訳ないのですけれども、流れを変えるということにはならないのではないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"あべ委員","kind":"意見","question":"出てくる結論は個々であっても、そこに使うロジックというのは一定の同一性があることが議会の信頼につながる。１つのロジックに当てはめて、ロジックから毎回変えてしまうとちょっと難しい、それも私の意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"本多委員","kind":"意見","question":"請願に関する全ての人たちへ配慮して慎重にというのはすごくよくわかりますが、ただ、我々議会人は、請願に対して態度を表わさなければいけないと思いますので、そこは我々の役割だと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"中塚委員","kind":"意見","question":"確かに、今の土地の所有者の気持ちを思うと、ちょっと不快に思うのではないかというご指摘は聞いてなるほどなとは思いますけれども、一方で、やはりこれについて、これでいく、いかないということを決めるという役割もそうだなというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"本多委員","kind":"質問・要望","question":"結論を本日出してほしいと求めました。態度については採択を主張いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"あくつ副委員長","kind":"意見","question":"意見を１つだけ。区がどういう判断をするのかというまた１つのハードルと言えばハードルがありますので、この議会の意思としては、このように考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"中塚委員","kind":"意見","question":"結論を出すということで、態度についてですけれども、今日、率直な議論が出ていたのは、私も少し学ばされました。にこの土地を取得して活用してほしいと、書かれていることはそのとおりだと思いますので、態度としては採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日、結論を出すということでお願いしたいと思います。そういったことをぜひ考えていただきたいとともに、交渉は今以上に進めていただきたいと思いを込めて、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"須貝委員","kind":"質問","question":"先ほどお話ししたとおり、個人の財産ということにかかわる問題ですから、私は反対いたします。結論を出すということと、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問","question":"ですから、こういう形で請願を出せば、きちんとした採択がされるという形であってほしい。きれいにこの趣旨が通るような形にするためには、継続を主張したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"吉田委員","kind":"質問","question":"あくまで継続を主張したいと思いますので、そうすると、席を外す形か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"吉田委員","kind":"質問","question":"そうですか。反対という結論になってしまうのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問","question":"そういうことですか。〔「採決に加わらなかった」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"吉田委員","kind":"質問","question":"そうですか。〔「だから、どちらか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"}]},{"id":"topic-06","title":"平成２７年請願第２９号 所得税法第５６条廃止の意見書提出を求める請願","agenda":"平成２７年請願第２９号 所得税法第５６条廃止の意見書提出を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"幾つか伺いたいと思いますけれども、前回は、家族間での私利的な所得分割を防止すると。やっぱり間違っているのではないかということが１点伺いたいのと、前回このことを伺ったときに、その中身も伺いたいと思います。","respondent":"黒田税務課長","answer":"現行制度でも、先ほどご説明いたしましたが、適正な範囲で家族に支払う給与については全額必要経費と認めるという制度になっているものです。最高裁で平成１６年に、この第５６条の規定については、そういった中で現在の制度が運用されているものです。","id":"exchange-079"},{"speaker":"中塚委員","kind":"質問・要望","question":"息子であっても、人格を持っているわけですから、ですからこの第５６条は間違っていると私は思うのです。そもそも働いた分を払うのだと、ここをしっかりと考えを変えていただきたいと思うのですけれども、改めていかがか尋ねました。","respondent":"黒田税務課長","answer":"そういった税制上の制度があるというものでありまして、繰り返しになりますが、家族への給与の支払いを所得税が認めていないというものではないというものです。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問","question":"なので、改めて伺いたいと思います。それを認めずに、特例規定として後から認める、この仕組みそのものが私はおかしいと思いますけれども、改めていかがか尋ねました。","respondent":"黒田税務課長","answer":"繰り返しになりますが、申告制度自体は、白色、青色ありまして、家族に給与を支払っている方は青色申告により申告いただければ、その全額が適正の範囲で必要経費として認めるというような税制度になっているものです。","id":"exchange-081"},{"speaker":"須貝委員","kind":"質問・要望","question":"その方法もきちんと優しく教えてくれて、やはり日々の営業活動、商売をされているわけですから。そういう経費をきちんと受けて、営業活動をしているのですから、それに倣ってやっていただきたいと私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問","question":"質問なのですけれども、それによって違いというか、どう違うのか尋ねました。","respondent":"黒田税務課長","answer":"１つ１つの取り引きごとではなく、日々の合計額をまとめて記載するなど、簡易な方法で記載してよいということになっております。青色申告ですと、基本的には取り引きごとに記録するということが複式での考え方ですので、平成２６年度から義務づけられているものです。","id":"exchange-083"},{"speaker":"吉田委員","kind":"質問","question":"では簡便というのは、単式出納帳ということなのですか。それとも、複式だけれども、少し簡単なやり方ということなのか尋ねました。","respondent":"黒田税務課長","answer":"１つ１つでなくても、控除の金額が違いますので、その辺は記帳の内容の正確度によって税制上の制度の違いがあるというものです。","id":"exchange-084"},{"speaker":"あべ委員","kind":"質問","question":"今、品川区内の事業者で、青色の事業者と白色の事業者はどのくらいの割合なのか、手元でわかりますでしょうか。品川区としては、青色申告を積極的に進めていくというか、切り替えていくような何か努力をされているのか尋ねました。","respondent":"黒田税務課長","answer":"の白色申告で事業専従者を有する納税義務者は１０６人ですので、ほとんどの方が青色申告で申告いただいているというふうに考えてあります。関連団体がありますので、そういった中で正しくご申告いただいて、正しく税計算するというところには取り組んでいるところです。","id":"exchange-085"},{"speaker":"本多委員","kind":"質問・要望","question":"本日、結論を出してほしいと求めました。態度につきましては、不採択。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"あくつ副委員長","kind":"意見","question":"ちょうど１年前、戦後７０年を経過しまして、この見直しを検討していく必要性についてまで否定するものではありません。特例規定で第５７条も活用されているということもありますので、第５６条を廃止すべきだという考え方には、不採択という立場ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"中塚委員","kind":"意見","question":"配偶者や家族であっても労賃は、特例の規定ではなくて初めから認めるべきものだと思います。それを特例として認めるということ自体がおかしいと、その方の人格を否定するものにつながってくると思いますので、採択ということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"あべ委員","kind":"意見","question":"今、むしろこの第５７条の規定がある以上は、法の中でも望まれている流れではないかというふうに考えます。経営の透明性が外形的にわからない分、これは国税の問題になってきますので、現段階ではこの請願には応えることができないということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"吉田委員","kind":"質問","question":"ただ、廃止というからには、いきなり廃止ということを採択することは難しいかというふうに考えます。不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"}]},{"id":"topic-07","title":"その他の(2)その他を行います。 まず、今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、総務委員会に係る項目","agenda":"その他の(2)その他を行います。 まず、今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、総務委員会に係る項目","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"何か検討するようなことがあったら、私は、しっかり平等に立候補者に対して接してほしいと求めました。それだけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858739?Template=document&Id=2032#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":58523,"voices":229}},{"id":"h27-20151130-10","meetingId":"h27-cm11","date":"2015年11月30日","dateIso":"2015-11-30","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"平成２７年第４回定例会","agenda":"平成２７年第４回定例会","exchanges":[{"speaker":"須貝委員","kind":"提案","question":"給与改正１０年提案がなされたわけですが、今回の議案に関しましては賛成できない、この辺を明確に態度表明としますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993740?Template=document&Id=5162#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":1407,"voices":11}}]);
